window.APP_QUESTIONS = [{"id":1,"chuong":1,"cauHoi":"Tại Đại hội II của Đảng (2.1951), xác định yếu tố tiên quyết nào làm cho Đảng mạnh và làm cho cách mạng mau đi đến thắng lợi hoàn toàn?","dapAn":["Học tập và làm theo tư tưởng, đạo đức, phong cách Hồ Chí Minh","Học tập và làm theo tư tưởng, đạo đức Hồ Chí Minh","Học tập đường lối chính trị, tác phong và đạo đức cách mạng của Hồ Chủ tịch","Học tập đường lối chính trị, đạo đức, phong cách Hồ Chí Minh"],"dung":"C"},{"id":2,"chuong":1,"cauHoi":"Khi nghiên cứu môn học Tư tưởng Hồ Chí Minh cần phải dựa trên một số nguyên tắc phương pháp luận nào?","dapAn":["Thống nhất tính đảng và tính khoa học","Thống nhất lý luận và thực tiễn; quan điểm lịch sử - cụ thể","Quan điểm toàn diện và hệ thống; kế thừa và phát triển","Tất cả các đáp án"],"dung":"D"},{"id":3,"chuong":1,"cauHoi":"Trong Điếu văn của Ban Chấp hành Trung ương Đảng nhấn mạnh: \"Dân tộc ta, nhân dân ta, non sông đất nước ta đã sinh ra Hồ Chủ tịch, (...) và chính Người đã làm rạng rỡ dân tộc ta, nhân dân ta, non sông đất nước ta\"'. Xác định cụm từ còn thiếu?","dapAn":["Người lãnh đạo sự nghiệp giải phóng dân tộc","Người con ưu tú của dân tộc","Người sáng lập Đảng Cộng sản Việt Nam","Người anh hùng dân tộc vĩ đại"],"dung":"D"},{"id":4,"chuong":1,"cauHoi":"Đại hội VII của Đáng (1991) đã khẳng định lấy chủ nghĩa Mác - Lênin và tư tưởng Hồ Chí Minh làm gì?","dapAn":["Nền tảng chính trị, kim chỉ nam cho hành động","Nền lý luận, kim chỉ nam cho hành động","Nền tảng tư tưởng, kim chỉ nam cho hành động","Nền tảng tinh thần, kim chỉ nam cho hành động"],"dung":"C"},{"id":5,"chuong":1,"cauHoi":"Tư tưởng Hồ Chí Minh đã dẫn dắt chúng ta đi trên mỗi chặng đường xây dựng và phát triển đát nước, là ngọn cờ thắng lợi của cách mạng Việt Nam, là sức mạnh tập hợp và đoàn kết toàn dân tộc trong sự nghiệp cách mạng của chúng ta hôm nay và mai sau. Đảng ta đã khẳng định nội dung này trong kỳ Đại hội nào sau đây?","dapAn":["Đại hộc Đại biểu toàn quốc lần thứ VIII (1996)","Đại hộc Đại biểu toàn quốc lần thứ IX (2001)","Đại hộc Đại biểu toàn quốc lần thứ X (2006)","Đại hộc Đại biểu toàn quốc lần thứ XI (2011)"],"dung":"C"},{"id":6,"chuong":1,"cauHoi":"Sinh viên có thể vận dụng vào xây dựng, rèn luyện phương pháp và phong cách công tác như thế nào sau khi nghiên cứu môn học Tư tưởng Hồ Chí Minh?","dapAn":["Xây dựng phương pháp học tập, tu dưỡng, rèn luyện phù hợp với điều kiện cụ thể của từng người, từng địa bàn","Xây dựng phong cách tư duy, diễn đạt, làm việc, v.v...","Xây dựng phong cách ứng xử, sinh hoạt, v.v... phù hợp với từng lúc, từng nơi theo phương châm mà Hồ Chí Minh đã nêu: Dĩ Bất biết ứng vạn biến","Tất cả các đáp án"],"dung":"D"},{"id":7,"chuong":1,"cauHoi":"Đối tượng nghiên cứu của môn học Tư tưởng Hồ Chí Minh là toàn bộ quan điểm Hồ Chí Minh được thể hiện ở đâu?","dapAn":["Trong sự nghiệp của Hồ Chí Minh","Trong cuộc đời của Hồ Chí Minh","Trong di sản của Hồ Chí Minh","Trong quá quá trình lãnh đạo cách mạng Việt Nam của Hồ Chí Minh"],"dung":"C"},{"id":8,"chuong":1,"cauHoi":"Hệ thống quan điểm toàn diện và sâu sắc của Hồ Chí Minh về những vấn đề cơ bản của cách mạng Việt Nam được phản ánh ở đâu?","dapAn":["Trong những bài nói, bài viết; hoạt động cách mạng của Người trong quá trình về nước trực tiếp lãnh đạo cách mạng","Trong những bài nói, bài viết; hoạt động cách mạng của Người trong quá trình tìm đường cứu nước","Trong những bài nói, bài viết; hoạt động cách mạng và đời sống hàng ngày của Người","Trong những bài nói, bài viết; hoạt động cách mạng của Người trong cách mạng giải phóng dân tộc"],"dung":"C"},{"id":9,"chuong":1,"cauHoi":"Đối tượng nghiên cứu tư tưởng Hồ Chí Minh được vận động như thế nào trong thực tiễn?","dapAn":["Là quá trình \"hiện thực hóa\" hệ thống quan điểm của Hồ Chí Minh trong quá trình phát triển của dân tộc Việt Nam","Là toàn bộ những luận điểm của Hồ Chí Minh và quá trình hệ thống hóa luận điểm trong đấu tranh cách mạng Việt Nam","Là toàn bộ những quan niệm của Hồ Chí Minh và quá trình hệ thống hóa quan niệm trong giải phóng dân tộc Việt Nam","Là toàn bộ những luận cứ của Hồ Chí Minh và quá trình hệ thống hóa luận cứ trong xây dựng chủ nghĩa xã hội Việt Nam"],"dung":"A"},{"id":10,"chuong":1,"cauHoi":"Ban Chấp hành Trung ương Đảng Cộng sản Việt Nam đã tôn vinh Hồ Chí Minh danh hiệu gì?","dapAn":["Nhà văn hóa kiệt xuất Việt Nam","Anh hùng dân tộc vĩ đại","Anh hùng giải phóng dân tộc, Nhà văn hóa kiệt xuất Việt Nam","Danh nhân văn hóa thế giới"],"dung":"B"},{"id":11,"chuong":1,"cauHoi":"Khóa họp Đại hội đồng UNESCO lần thứ 24 ở Pari đã đưa ra Nghị quyết số bao nhiêu về kỷ niệm 100 năm Ngày sinh của Chủ tịch Hồ Chí Minh?","dapAn":["Số 23C/18.6.5","Số 24C/18.6.5","Số 25C/18.6.5","Số 26C/18.6.5"],"dung":"B"},{"id":12,"chuong":1,"cauHoi":"Hồ Chí Minh luôn coi trọng lý luận và thực tiễn có sự thống nhất với nhau, do đó, Người đã so sánh có kinh nghiệm mà không có lý luận thì sẽ như thế nào?","dapAn":["Như một mắt sáng, một mắt mờ","Như một chân cao, một chân thấp","Như người không có trí khôn","Như tàu không có bàn chỉ nam"],"dung":"A"},{"id":13,"chuong":1,"cauHoi":"Hồ Chí Minh chỉ rõ con người sẽ mắc phải căn bệnh \"lý luận suông\" nếu không áp dụng vào thực tê. ,... phai ra sức thực hành mới thành người biêt lý luận. Vì vậy, Người đã ví lý luận và thực hành với cái gì?","dapAn":["Lý luận như cái bàn chỉ nam, thực hành như mục đích hướng đến","Lý luận như cái kim chỉ nam, thực hành như mục tiêu hướng đến","Lý luận như cái tên (hoặc viên đạn), thực hành như cái đích để bắn","Lý luận như cái riêng (hoặc cái cá biệt), thực hành như cái chung"],"dung":"C"},{"id":14,"chuong":1,"cauHoi":"Một yêu cầu về mặt lý luận khi nghiên cứu tư tưởng Hồ Chí Minh trên bình diện tổng thể hay từng bộ phận phải luôn luôn quán triệt điều gì?","dapAn":["Mối liên hệ qua lại giữa các yếu tố, các bộ phận khác nhau trong sự khác biệt của hệ thống tư tưởng Hồ Chí Minh","Mối liên hệ qua lại giữa các yếu tố, các bộ phận khác nhau trong sự gắn kết tất yếu của hệ thống tư tưởng Hồ Chí Minh xung quanh hạt nhân cốt lõi là tư tưởng độc lập dân tộc và chủ nghĩa xã hội","Mối liên hệ qua lại giữa các yếu tố, các bộ phận khác nhau trong phân tầng giữa các yếu tố cấu thành hệ thống tư ưởng Hồ Chí Minh","Tất cả các đáp án"],"dung":"B"},{"id":15,"chuong":1,"cauHoi":"Đại hội XII (2016) của Đảng nhấn mạnh phải kiên định chủ nghĩa Mác - Lênin, tư tưởng Hồ Chí Minh và yêu cầu cần phải:","dapAn":["Vận dụng sáng tạo và phát triển phù hợp với thực tiễn cách mạng Việt Nam","Vận dụng và phát triển phù hợp với thực tiễn cách mạng thế giới","Vận dụng sáng tạo và bố sung phù hợp với thực tiễn cách mạng Việt Nam","Vận dụng và bổ sung phù hợp với thực tiễn cách mạng thế giới"],"dung":"A"},{"id":16,"chuong":1,"cauHoi":"Nghiên cứu tư tưởng Hồ Chí Minh, trước hết phải dựa vào các tác phẩm của Người để lại. Những tác phẩm nào sau đây là của Hồ Chí Minh?","dapAn":["Điện Biên Phủ-điểm hẹn lịch sử (1944)","Người đi tìm hình của Nước (1960)","Nâng cao đạo đức cách mạng, quyét sạch chủ nghĩa cá nhân (1969)","Đất nước (1948)"],"dung":"C"},{"id":17,"chuong":1,"cauHoi":"Vì sao phải đảm bảo tính đảng và tính khoa học trong nghiên cứu môn học Tư tưởng Hồ Chí Minh?","dapAn":["Vì phải đứng trên lập trường giai cấp nông dân, quan điểm của chủ nghĩa Mác- Lênin, đường lối, quan điểm của Đảng đề nhận thức phân tích, đồng thời đảm bảo tính khách quan khoa học cho các luận đề nêu ra","Vì phải đứng trên lập trường giai cấp công nhân, quan điểm chủ nghĩa Mác - Lênin, quán triệt cương lĩnh, đường lối, quan điểm của Đảng để nhận thức và phân tích..., đồng thời đảm bảo tính khách quan, khoa học của các luận đề nêu ra","Vì phải đứng trên lập trường giai cấp tư sản, quan điểm của chủ nghĩa Mác- Lênin, đường lối, quan điểm của Đảng để nhận thức phân tích, đồng thời đảm bảo tính khách quan khoa học cho các luận đề nêu ra","Tất cả các đáp án"],"dung":"B"},{"id":18,"chuong":1,"cauHoi":"Ý nghĩa của việc học tập môn Tư tưởng Hồ Chí Minh góp phần nâng cao năng lực tư duy lý luận của sinh viên thể hiện ở nội dung nào sau đây?","dapAn":["Củng cố lập trường, quan điểm cách mạng; kiên định mục tiêu độc lập dân tộc và chủ nghĩa xã hội","Để thực hành đạo đức cách mạng, chống chủ nghĩa cá nhân","Sống có ích cho xã hội, yêu và làm những điều thiện, ghét và tránh cái ác, cái","Nâng cao lòng tự hào về đất nước Việt Nam, về chế độ chính trị xã hội chủ xấu nghĩa"],"dung":"A"},{"id":19,"chuong":1,"cauHoi":"Qua nghiên cứu môn học Tư tưởng Hồ Chí Minh, sinh viên có điều kiện tốt để thực hành điều gì?","dapAn":["Kiên đinh mục tiêu độc lập dân tộc và chủ nghĩa xã hội","Bảo vệ sự trong sáng của chủ nghĩa Mác - Lênin, tư tưởng Hồ Chí Minh","Đạo đức cách mạng, nâng cao lòng tự hào dân tộc, nguyện \"sống, chiến đấu, lao động, học tập theo gương Bác Hồ vĩ đại\"","Vận dựng tư tưởng Hồ Chí Minh vào giải quyết những vấn đề của thực tiễn đặt ra"],"dung":"C"},{"id":20,"chuong":1,"cauHoi":"Đảng Cộng sản Việt Nam xác định tư tưởng Hồ Chí Minh là hệ thống quan điểm toàn diện, sâu sắc về vấn đề gì?","dapAn":["Cơ bản của cách mạng Việt Nam","Kinh tế của cách mạnh Việt Nam","Văn hóa của cách mạnh Việt Nam","Chính trị của cách mạnh Việt Nam"],"dung":"A"},{"id":21,"chuong":1,"cauHoi":"Trên cơ sở thống nhất nguyên tắc tính đảng và tính khoa học, giúp người nghiên cứu hiểu như thế nào về tư tưởng Hồ Chí Minh?","dapAn":["Hiểu cách thức nghiên cứu tư tưởng Hồ Chí Minh","Hiểu quá trình hình thành tư tưởng Hồ Chí Minh","Hiểu rõ và hiểu sâu sắc tư tưởng Hồ Chí Minh","Hiêu tính định hướng chính trị tư tưởng Hồ Chí Minh"],"dung":"C"},{"id":22,"chuong":1,"cauHoi":"Nắm vững quan diểm lịch sử - cụ thể trong nghiên cứu tư tưởng Hồ Chí Minh, giúp người nghiên cứu nhận thức được điều gì?","dapAn":["Bản chất tư tưởng Hồ Chí Minh mang đậm dấu ấn của quá trình phát triển lịch sử, quá trình phát triển sáng tạo, đổi mới","Bản chất tư tưởng Hồ Chí Minh mang đậm dấu ấn của mối quan hệ biện chứng của các lĩnh vực đời sống xã hội .","Bản chất tư tưởng Hồ Chí Minh mang đậm dấu ấn của giá trị truyền thống dân tộc trong tiến trình phát triển của lịch sử","Bản chất tư tưởng Hồ Chí Minh mang đậm dấu ấn của ảnh hưởng văn hóa Đông - Tây"],"dung":"A"},{"id":23,"chuong":1,"cauHoi":"Quan điểm kế thừa và phát triển khi nghiên cứu, học tập tư tướng Hồ Chí Minh đòi hỏi không chỉ biết kế thừa, vận dụng mà còn phải biết:","dapAn":["Quán triệt tư tưởng của Người trong các giai đoạn phát triển của cách mạng Việt Nam","Nhận thức đúng giá trị tư tưởng của Người phù hợp với xu hướng phát triển của thế giới trong giai đoạn hiện nay","Nhận thức rõ bản chất tư tưởng của Người mang đậm dấu ấn trong quá trình phát triển lịch sử","Phát triển sáng tạo tư tưởng của Người trong điều kiện lịch sử mới, trong bối cảnh cụ thể của đất nước và quốc tế"],"dung":"D"},{"id":24,"chuong":1,"cauHoi":"Có nhiều nội dung phản ánh tư tưởng Hồ Chí Minh không ở trong văn bản mà là trong chỉ đạo thực tiễn. Thực tiễn được nhắc đến là thực tiễn nào sau đây?","dapAn":["Thực tiễn của chính bản thân Hồ Chí Minh và thực tiễn hoạt động của các đồng chí, học trò của Người","Thực tiễn của chính bản thân Hồ Chí Minh và thực tiễn của phong trào cách mạng vô sản","Thực tiễn của chính bản thân Hồ Chí Minh và thực tiễn cách mạng giải phóng dân tộc trên thế giới","Thực tiễn của chính bản thân Hồ Chí Minh và thực tiễn phong trào đấu tranh vì hòa bình, dân chủ, tiến bộ trên thế giới"],"dung":"A"},{"id":25,"chuong":1,"cauHoi":"Trong nghiên cứu tư tưởng Hồ Chí Minh, phương pháp chuyên ngành, liên ngành cần được sử dụng như thế nào?","dapAn":["Để nghiên cứu riêng tư tưởng Hồ Chí Minh về độc lập dân tộc và chủ nghĩa xã hội ở Việt Nam","Để nghiên cứu riêng tư tưởng Hồ Chí Minh về Đảng Cộng sản Việt Nam và nhà nước của nhân dân, do nhân dân, vì nhân dân","Để nghiên cứu toàn bộ hệ thống tư tưởng Hồ Chí Minh cũng như mỗi tác phâm lý luận riêng biệt của Người","Để nghiên cứu riêng tư tưởng Hồ Chí Minh về đại đoàn kết dân tộc và đoàn kết quốc tế"],"dung":"C"},{"id":26,"chuong":1,"cauHoi":"Thông qua nghiên cứu môn học Tư tưởng Hồ Chí Minh, sinh viên thường xuyên tu dưỡng, rèn luyện bản thân mình theo tư tưởng, đạo đức, phong cách Hồ Chí Minh, hoàn thành nhiệm vụ của mình gắn liền với:","dapAn":["Trau dồi tình cảm cách mạng, đóng góp thiết thực và hiệu quả cho sự nghiệp cách mạng của đất nước","Củng cố lập trường cách mạng, tích cực, chủ động đấu tranh phê phán những luận điểm sai trái","Học tập nâng cao trình độ chuyên môn, nghiệp vụ","Bồi đắp năng lực tư duy lý luận, chỉ dẫn hành động để sinh viên trở thành công dân có ít cho xã hội"],"dung":"A"},{"id":27,"chuong":2,"cauHoi":"Hồ Chí Minh đã kế thừa những giá trị tích cực nào của Phật giáo để đoàn kết đồng bào theo đạo Phật, đoàn kết toàn dân vì nước Việt Nam hòa bình, thống nhất, độc lập, dân chủ và giàu mạnh?","dapAn":["Tư tưởng từ bi, vị tha, yêu thương con người, khuyến khích làm việc thiện, chống lại điều ác","Đề cao quyền bình đẳng của con người và chân lý","Con người sống hòa đồng, gắn bó với đất nước của đạo Phật","Tất cả các đáp án"],"dung":"D"},{"id":28,"chuong":2,"cauHoi":"Đến với văn hóa phương Tây, Hồ Chí Minh quan tâm, tìm hiểu các cuộc cách mạng tư sản nào?","dapAn":["Thái Lan, Mỹ, Anh","Trung Quốc, Đức, Mỹ","Liên Xô, Mỹ, Pháp","Anh, Pháp, Mỹ"],"dung":"D"},{"id":29,"chuong":2,"cauHoi":"Cuối những năm 20 của thế kỷ XX, câu nói: \"Bây giờ học thuyết nhiều, chủ nghĩa nhiều, nhưng chủ nghĩa chân chính nhất, chắc chắn nhất, cách mạng nhất là chủ nghĩa Lênin\" 3 là của ai?","dapAn":["Hồ Chí Minh","Không Tử","Phạm Văn Đồng","Tôn Trung Sơn"],"dung":"A"},{"id":30,"chuong":2,"cauHoi":"Theo Hồ Chí Minh nhận định: Học thuyết của Khổng Tử, tôn giáo Giêxu, chủ nghĩa Mác và chủ nghĩa Tôn Dật Tiên có những ưu điểm chung nào?","dapAn":["Họ đều mong muốn hòa bình, hạnh phúc, ấm no, tự do cho nhân dân","Họ đều xây dựng lý tưởng về một xã hội đại động, bình đẳng, hạnh phúc","Họ đều muốn mưu hạnh phúc cho loài người, mưu phúc lợi cho xã hội","Tất cả các đáp án"],"dung":"C"},{"id":31,"chuong":2,"cauHoi":"Trong quá trình hoạt động cách mạng, Hồ Chí Minh đã thể hiện những phẩm chất như thế nào?","dapAn":["Có lý tưởng cao cả và hoài bão lớn cứu dân, cứu nước, ý chí nghị lực to lớn","Bản lĩnh tư duy độc lập, tự chủ, sáng tạo, giàu tính phê phán, đổi mới và cách mạng","Có tầm nhìn chiến lược, suốt đời tận trung với nước, hiếu với dân","Tất cả các đáp án"],"dung":"D"},{"id":32,"chuong":2,"cauHoi":"Tài năng hoạt động, tổng kết thực tiễn phát triển lý luận của Hồ Chí Minh được thể hiện như thế nào?","dapAn":["Là người có vốn sống và thực tiễn cách mạng phong phú","Thấu hiểu về phong trào giải phóng dân tộc, về xây dựng chủ nghĩa xã hội, xây dựng đảng cộng sản...","Là nhà tố chức vĩ đại của cách mạng Việt Nam","Tất cả các đáp án"],"dung":"D"},{"id":33,"chuong":2,"cauHoi":"Những hoạt động được xem bước ngoặt quan trọng trong cuộc đời Hồ Chí Minh, bước ngoặt của chủ nghĩa yêu nước kết hợp chặt chẽ với lập trường cách mạng vô sản là gì?","dapAn":["Bỏ phiếu tán thành Quốc tế Cộng sản","Tham gia sáng lập Đảng Cộng sản Pháp","Trở thành người cộng sản Việt Nam đầu tiên","Tất cả các đáp án"],"dung":"D"},{"id":34,"chuong":2,"cauHoi":"Thời kỳ nào hình thành những nội dung cơ bản của tư tưởng Hồ Chí Minh về cách mạng Việt Nam?","dapAn":["Thời kỳ từ đầu năm 1911 đến cuối năm 1920","Thời kỳ từ cuối năm 1920 đến đầu năm 1930","Thời kỳ từ đầu năm 1930 đến đầu năm 1941","Thời kỳ từ đầu năm 1941 đến cuối năm 1969"],"dung":"B"},{"id":35,"chuong":2,"cauHoi":"Hồ Chí Minh sáng lập tổ chức tiền thân của Đảng Cộng sản: Hội Việt Nam Thanh niên Cách mạng được thành lập vào thời gian nào?","dapAn":["4/1925","5/1925","6/1925","7/1925"],"dung":"C"},{"id":36,"chuong":2,"cauHoi":"Hội nghị Trung ương Đảng họp tháng 10/10930 đã ra án nghị quyết như thế nào đối với Hội nghị hợp nhất Đảng do Hồ Chí Minh chủ trì vào tháng 2/1930?","dapAn":["Thủ tiêu chánh cương, sách lược và điều lệ Đảng","Bỏ tên Đảng Cộng sản Việt Nam","Những người thàm gia Hội nghị xác định, lấy tên là Đảng Cộng sản Đông Dương hoạt động theo Chỉ thị của Quốc tế Cộng sản","Tất cả các đáp án"],"dung":"D"},{"id":37,"chuong":2,"cauHoi":"Tư tưởng Hồ Chí Minh được Đảng Cộng sản Đông Dương khẳng định, trở thành yếu tố chỉ đạo cách mạng Việt Nam từ Hội nghị trung ương nào?","dapAn":["Hội nghị Trung ương Đảng tháng 4/1941","Hội nghị Trung ương Đảng tháng 5/1941","Hội nghị Trung ương Đảng tháng 7/1941","Hội nghị Trung ương Đảng tháng 8/1941"],"dung":"B"},{"id":38,"chuong":2,"cauHoi":"Hội nghị Trung ương Đảng tháng 5 - 1941 đã tạm thời gác lại khẩu hiệu cách mạng điền địa, xóa bỏ vấn đề lập Chính phủ Liên bang Cộng hòa dân chủ Đông Dương, thay bằng điều gì?","dapAn":["Chủ trương sẽ thành lập Chính phủ nhân dân của nước Việt Nam Dân chủ Cộng hòa","Nêu chủ trương lập Mặt trận Việt Minh","Thực hiện đại đoàn kết dân tộc trên cơ sở nòng cốt liên minh công nông, nêu ra phương hướng khởi nghĩa vũ trang giành chính quyền...","Tất cả các đáp án"],"dung":"D"},{"id":39,"chuong":2,"cauHoi":"Từ ngày 2/9/1945 đến ngày 19/12/1946, với phương châm Dĩ bất biến ứng vạn biến, giữ vững mục tiêu đầu tranh cho độc lập dân tộc, Hồ Chí Minh đã chỉ đạo thành công sách lược gì?","dapAn":["Tạm hòa hoãn với Tưởng để đối phó với thực dân Pháp","Tạm hòa hoãn với Pháp để đuổi quân Tưởng và tay sai về nước","Củng cố lực lượng, chuẩn bị toàn quốc kháng chiến chống thực dân Pháp","Tất cả các đáp án"],"dung":"D"},{"id":40,"chuong":2,"cauHoi":"Năm 1951, Chủ tịch Hồ Chí Minh và Trung ương Đảng đã triệu tập Đại hội II, đưa Đảng ra hoạt động công khai với tên gọi là gì?","dapAn":["Đảng Cộng sản Đông Dương","Đảng Cộng sản Việt Nam","Đảng Lao động Việt Nam","Đông Dương Cộng sản Đảng"],"dung":"C"},{"id":41,"chuong":2,"cauHoi":"Cuối thế kỷ XIX, đầu thế kỷ XX, xã hội Việt Nam xuất hiện thêm những giai tầng mới nào?","dapAn":["Giai cấp công nhân, giai cấp tư sản, tầng lớp tiều tư sản ở thành thị","Giai cấp tư sản, giai cấp vô sản, tầng lớp trí thức ở thành thị.","Tầng lớp tiểu tư sản ở thành thị, giai cấp công nhân, giai cấp nông dân.","Giai cấp công nhân, giai cấp tư sản, giai cấp nông dân."],"dung":"A"},{"id":42,"chuong":2,"cauHoi":"Khi những giai tầng mới xuất hiện, xã hội Việt Nam có thêm các mâu thuẫn mới gì?","dapAn":["Mâu thuẫn giữa giai cấp nông dân với để quốc Pháp giai cấp tư sản; giữa toàn thể nhân dân Việt Nam với chủ nghĩa đế quốc Pháp","Mâu thuẫn giữa giai cấp nông dân Việt Nam với giai cấp địa chủ; giữa toàn thể nhân dân Việt Nam với chủ nghĩa đế quốc Pháp","Mâu thuẫn giữa giai cấp công nhân Việt Nam với giai cấp tư sản; giữa toàn thể nhân dân Việt Nam với chủ nghĩa đế quốc Pháp","Giữa tầng lớp tiểu tư sản thành thị với giai cấp tư sản; giữa toàn thể nhân dân Việt Nam với chủ nghĩa đế quốc Pháp"],"dung":"C"},{"id":43,"chuong":2,"cauHoi":"Các phong trào yêu nước theo khuynh hướng dân chủ tư sản đầu thế kỷ XX diễn ra đều thất bại là do nguyên nhân nào?","dapAn":["Do giai cấp tư sản Việt Nam còn non yếu; các phong trào chưa có đường lối và phương pháp cách mạng đúng đắn","Do giai cấp nông dân Việt Nam còn non yếu; các phong trào chưa có đường lối và phương pháp cách mạng đúng đắn","Do giai cấp công nhân Việt Nam còn non yếu; các phong trào chưa có đường lối và phương pháp cách mạng đúng đắn","Do tầng lớp tiểu tư sản Việt Nam còn non yêu; các phong trào chưa có đường lối và phương pháp cách mạng đúng đắn"],"dung":"A"},{"id":44,"chuong":2,"cauHoi":"Các mâu thuẫn vốn có trong lòng chủ nghĩa tư bản cuối thế kỷ XIX, đầu thế kỷ XX là gì?","dapAn":["Mâu thuẫn giữa giai cấp tư sản với giai cấp vô sản ở các nước tư bản; mâu thuẫn giữa các nước đế quốc với nhau","Mâu thuẫn giữa các giai cấp tư sản với giai cấp vô sản ở các nước tư bản; mâu thuẫn giữa các nước đế quốc với nhau; mâu thuẫn giữa các dân tộc thuộc địa và phụ thuộc với chủ nghĩa đề quốc","Mâu thuẫn giữa các giai cấp tư sản với các giai cấp vô sản ở các nước tư bản; mâu thuẫn giữa các dân tộc thuộc địa và phụ thuộc với chủ nghĩa đế quốc","Mâu thuẫn giữa các nước đế quốc với nhau; mâu thuẫn giữa các dân tộc thuộc địa và phụ thuộc với chủ nghĩa đế quốc"],"dung":"B"},{"id":45,"chuong":2,"cauHoi":"Giá trị xuyên suốt trong những truyền thống tốt đẹp của dân tộc Việt Nam là gì?","dapAn":["Đức tính cần cù, chịu khó","Chủ nghĩa yêu nước","Tinh thần đấu tranh anh dũng, bất khuất","Tấm lòng nhân ái"],"dung":"B"},{"id":46,"chuong":2,"cauHoi":"Chủ nghĩa yêu nước có ý nghĩa như thế nào với Hồ Chí Minh khi ra đi tìm đường cứu nước, cứu dân?","dapAn":["Là giá trị cốt lõi, điểm đầu tiên và thôi thức","Là cơ sở tư tưởng, điểm xuất phát và thúc dục","Là nền tảng tư tưởng, điểm xuất phát và động lực thúc đẩy","Là kim chỉ nam, điểm đầu tiên và động lực thức đấy"],"dung":"C"},{"id":47,"chuong":2,"cauHoi":"Hồ Chí Minh đã kế thừa giá trị tích cực nào của Nho giáo để góp phần vào quản lý xã hội?","dapAn":["Tư tưởng từ bi, bác ái, yêu thương con người","Dùng nhân trị, đức trị","Khuyên con người sống hòa đồng, gắn bó với đất nước","Con người sống gắn bó, hòa hợp với thiên nhiên."],"dung":"B"},{"id":48,"chuong":2,"cauHoi":"Hồ Chí Minh đã kế thừa, đổi mới và phát triển giá trị tích cực nào của Nho giáo trong việc tu dưỡng, rèn luyện đạo đức của con người; trong công tác xây dựng Đảng về đạo đức?","dapAn":["Tư tưởng từ bi, bác ái, yêu thương con người","Dùng nhân trị, đức trị","Tinh thần trọng đạo đức","Con người sống gắn bó, hòa hợp với thiên nhiên"],"dung":"C"},{"id":49,"chuong":2,"cauHoi":"Hồ Chí Minh đã kế thừa những giá trị tích cực nào của Lão giáo trong quá trình hình thành và phát triển tư tưởng Hồ Chí Minh?","dapAn":["Tư tưởng từ bi, bác ái, yêu thương con người","Khuyên con người nên sống gắn bó với thiên nhiên, hòa đồng với thiên nhiên, biết bảo vệ môi trường sống","Lòng nhân ái, đức hy sinh, khoan dung độ lượng với con người","Công bằng, bác ái, nhân nghĩa, trí, dung, tín, liêm."],"dung":"B"},{"id":50,"chuong":2,"cauHoi":"Hồ Chí Minh đã kế thừa, phát triển những quan điểm về nhân quyền, dân quyền trong những bản tuyên ngôn nào của thế giới?","dapAn":["Tuyên ngôn độc lập của Mỹ (1776); Tuyên ngôn của Đảng Cộng sản (1848)","Tuyên ngôn Nhân quyền và Dân quyền Pháp 1791; Tuyên ngôn của Đảng Cộng sản (1848)","Tuyên ngôn độc lập Mỹ 1776; Tuyên ngôn Nhân quyền và Dân quyền Pháp 1791","Tuyên ngôn Nhân quyền và Dân quyền của Pháp (1791); Tuyên ngôn Quốc tế Nhân quyền (1948)"],"dung":"C"},{"id":51,"chuong":2,"cauHoi":"Tiền đề lý luận nào là quan trọng nhất, quyết định bước ngoặt trong việc hình thành tư tưởng Hồ Chí Minh?","dapAn":["Giá trị truyền thống tốt đẹp của dân tộc Việt Nam","Tinh hoa văn hóa phương Đông","Chủ nghĩa Mác - Lê-nin","Tinh hoa văn hóa phương Tây"],"dung":"C"},{"id":52,"chuong":2,"cauHoi":"Thủa niên thiếu, Hồ Chí Minh ảnh hưởng sâu sắc tinh thần yêu nước, thương dân và nhân cách của ai trong gia đình?","dapAn":["Cha Nguyễn Sinh Sắc","Mẹ Hoàng Thị Loan","Anh trai Nguyễn Sinh Khiêm","Chị gái Nguyễn Thị Liên"],"dung":"A"},{"id":53,"chuong":2,"cauHoi":"Hồ Chí Minh luôn suy ngẫm sâu sắc về Tổ quốc và thời cuộc, Người khâm phục tinh thần yêu nước của các vị tiền bối cách mạng như Phan Bội Châu, Phan Châu Trình, Hoàng Hoa Thám,... nhưng Người lại không tán thành điều gì?","dapAn":["Cách thức tổ chức và khuynh hướng cứu nước","Phương pháp và khuynh hướng cứu nước","Cách làm và khuynh hướng cứu nước","Tư duy và cách làm của các khuynh hướng cứu nước"],"dung":"B"},{"id":54,"chuong":2,"cauHoi":"Thông qua báo chí và các hoạt động thực tiễn, Hồ Chí Minh đã tích cực truyền bá điều gì vào phong trào công nhân và phong trào yêu nước Việt Nam?","dapAn":["Chủ nghĩa yêu nước chân chính","Tinh thần bất khuất, kiên cường, vượt lên mọi khó khăn","Lòng vị tha, khoan dung, độ lượng","Chủ nghĩa Mác - Lênin"],"dung":"D"},{"id":55,"chuong":2,"cauHoi":"Luận điểm: \"Làm tư sản dân quyền cách mạng và thổ địa cách mạng để đi tới xã hội cộng sản', \"đánh đổ đế quốc Pháp, phong kiến An Nam và giai cấp tư sản phản cách mạng\"s được trích trong tác phẩm nào của Hồ Chí Minh?","dapAn":["Bản án chế độ thực dân Pháp (1925)","Đường cách mệnh (1927)","Cương lĩnh chính trị đầu tiên của Đảng (1930)","Thường thức chính trị (1953)"],"dung":"C"},{"id":56,"chuong":2,"cauHoi":"Theo Hồ Chí Minh, thành lập Đảng Cộng sản Việt Nam với Cương lĩnh chính trị đúng đắn và sáng tạo đã chấm dứt điều gì của cách mạng Việt Nam?","dapAn":["Cuộc khủng hoảng về đường lối và tố chức lãnh đạo","Cuộc đầu tranh anh dũng của dân tộc Việt Nam","Cuộc khủng hoảng về phương pháp đấu tranh giải phóng dân tộc","Cuộc khủng hoảng về cách thức tổ chức và phong trào đấu tranh của dân tộc Việt Nam"],"dung":"A"},{"id":57,"chuong":2,"cauHoi":"Thời gian từ năm 1934 đến năm 1938, Hồ Chí Minh ở đâu và nghiên cứu vấn đề gì?","dapAn":["Trung Quốc và làm nghiên cứu sinh tại Ban sử của Viện nghiên cứu các vấn đề dân tộc và thuộc địa","Thái Lan và làm nghiên cứu về các vấn đề dân tộc và thuộc địa","Liên Xô và làm nghiên cứu sinh tại Ban sử của Viện nghiên cứu các vấn đề dân tộc và thuộc địa","Pháp và làm nghiên cứu tại Viện nghiên cứu các vấn đề dân tộc và thuộc địa"],"dung":"C"},{"id":58,"chuong":2,"cauHoi":"Cách mạng tháng Tháng Tám năm 1945 thành công lật đổ chế độ phong kiến và ách thống trị của chủ nghĩa thực dân Pháp trên đất nước ta đã khẳng định điều gì?","dapAn":["Sự thắng lợi to lớn đầu tiên của chủ nghĩa Mác - Lênin và tư tưởng Hồ Chí Minh ở Việt Nam","Sự thắng lợi to lớn trong lịch sử đầu tranh giải phóng dân tộc của Việt Nam","Sự thắng lợi to lớn trong sự nghiệp lãnh đạo cách mạng của Hồ Chí Minh ở Việt Nam","Sự thắng lợi to lớn và mở ra một kỷ nguyên mới ở Việt Nam"],"dung":"A"},{"id":59,"chuong":2,"cauHoi":"Từ năm 1954-1969, Hồ Chí Minh xác định và lãnh đạo đường lối cùng một lúc thi hành hai nhiệm vụ chiền lược của cách mạng Việt Nam là gì?","dapAn":["Giành lại chính quyền ở miền Bắc và xây dựng chủ nghĩa xã hội ở miền Nam","Xây dựng chủ nghĩa xã hội ở miền Bắc; tiếp tục cuộc cách mạng dân tộc dân chủ nhân dân ở miền Nam","Xây dựng chủ nghĩa xã hội ở miền Nam; tiếp tục cuộc cách mạng dân tộc dân chủ nhân dân ở miền Bắc","Giành lại chính quyền và xây dựng chủ nghĩa xã hội ở miền Nam"],"dung":"B"},{"id":60,"chuong":2,"cauHoi":"Luận điểm: \"Toàn Đảng, toàn dân ta đoàn kết phấn đấu, xây dựng một nước Việt Nam hòa bình, thống nhất, độc lập, dân chủ và giàu mạnh, và góp phần xứng đáng vào sự nghiệp cách mạng thế giới\" được trích trong tác phẩm nào?","dapAn":["Chánh cương vắn tắt của Đảng (1930)","Tuyên ngôn độc lập (1945)","Lời kêu gọi toàn quốc kháng chiến (1946)","Di Chúc (1969)"],"dung":"D"},{"id":61,"chuong":2,"cauHoi":"Chủ nghĩa Mác - Lê-nin và tư tưởng Hồ Chí Minh là nền tảng tư tưởng, kim chỉ nam cho hành động của Đảng được khẳng định trong Đại hội nào?","dapAn":["Đại hội VI (1986-1990)","Đại hội VII (1991-1996)","Đại hội VIII (1997-2002)","Đại hội IX (2003-2008)"],"dung":"B"},{"id":62,"chuong":2,"cauHoi":"\"Nước Nga có chuyện lạ đời/ Biến người nô lệ thành người tự do\". Chuyện lạ đời theo Hồ Chí Minh ở đây là gì?","dapAn":["Cách mạng Tháng 10 Nga","Nhà nước công nông đầu tiên trong lịch sử","Liên Xô đánh thắng 14 nước đế quốc","Tất cả các đáp án"],"dung":"B"},{"id":63,"chuong":2,"cauHoi":"Văn kiện nào sau đây đưa ra khăng định: \"Muôn đôi mới tư duy, Đảng ta phải nắm vững bản chất cách mạng và khoa học của chủ nghĩa Mác - Lênin kế thừa di sản quý báu về tư tưởng và lý luận cách mạng của Chủ tịch Hồ Chí Minh\" ?","dapAn":["Đại hội V","Đại hội VI","Đại hội VII","Đại hội VIII"],"dung":"B"},{"id":64,"chuong":2,"cauHoi":"Chỉ thị nào sau đây đưa ra yêu cầu: \"Tiếp tục đổi mới, nâng cao chất lượng, hiệu quả học tập, nghiên cứu, vận dụng và phát triển chủ nghĩa Mác - Lênin, tư tưởng Hồ Chí Minh trong tình hình mớt\"?","dapAn":["Chỉ thị số 23-CT/TW ngày 9/2/2018 của Ban Bí thư khóa XII","Chỉ thị số 24-CT/TW ngày 9/2/2018 của Trung ương Đảng khóa XII","Chỉ thị số 25-CT/TW ngày 9/2/2018 của Ban Bí thư khóa XII","Chỉ thị số 26-CT/TW ngày 9/2/2018 của Trung ương Đảng khóa XII"],"dung":"A"},{"id":65,"chuong":2,"cauHoi":"Đánh giá sau đây về Chủ tịch Hồ Chí Minh là của ai: \"Hồ Chủ tịch là người sáng lập, lãnh đạo và rèn luyện Đảng ta, là người xây dựng nền Cộng hòa dân chủ Việt Nam và Mặt trận Dân tộc thống nhất, là người cha thân yêu của các lực lượng vũ trang nhân dân Việt Nam. Người là linh hồn, là ngọn cờ chói lọi, lãnh đạo toàn Đảng, toàn dân, toàn quân ta đoàn kết một lòng, chiến đấu anh dũng, viết nên những trang sử vẻ vang nhất của Tổ quốc ta\"?","dapAn":["Trần phú","Lê Duấn","Võ Nguyên Giáp","Trường Chinh"],"dung":"B"},{"id":66,"chuong":2,"cauHoi":"Hồ Chí Minh viết: \"Cũng như ngọc càng mài càng sáng, vùng càng luyện càng trong\" được trích từ tác phẩm nào của Hồ Chí Minh?","dapAn":["Đường Cách mệnh","Đạo đức cách mạng","Nâng cao đạo đức cách mạng, quét sạch chủ nghĩa cá nhân","Liên Xô vĩ đại"],"dung":"C"},{"id":67,"chuong":2,"cauHoi":"Tìm một đáp án sai trong đoạn sau đây: trong 10 năm đầu (1911-1920) của quá trình bôn ba, Nguyễn Ái Quốc đã:","dapAn":["Vượt qua 3 đại dương, 4 châu lục","Đến khoảng gần 30 nước","Sống, làm thuê và tự học tại các nước Mỹ, Anh, Pháp","Đến Matxcova và dự hội nghị quốc tế nông dân"],"dung":"D"},{"id":68,"chuong":2,"cauHoi":"Xác dịnh tác giả câu thơ sau: \"Hiền dữ phải đâu là tính sẵn/ Phần nhiều do giáo dục mà nên\"?","dapAn":["Khổng Tử (551-497) - nhà giáo dục lớn thời cổ đại của Trung Hoa","Hồ Chí Minh (1890-1969) - lãnh tụ vĩ đại của nhân dân Việt Nam","Mahatma Gandi (1869-1948) - lãnh tụ vĩ đại của nhân dân Ẩn Độ","Giêsu Crit - người sáng lập Kito ở Phương Tây."],"dung":"B"},{"id":69,"chuong":2,"cauHoi":"Điều kiện thuận lợi để chủ nghĩa Mác - Lênin xâm nhập, truyền bá vào nước ta đầu thế kỷ XX là gì?","dapAn":["Tinh thần ham học hỏi của nhân dân và tinh thần đoàn kết.","Tinh thần đoàn kết và phong trào yêu nước","Phong trào công nhân và phong trào yêu nước","Phong trào công nhân và tinh thần đoàn kết dân tộc"],"dung":"C"},{"id":70,"chuong":2,"cauHoi":"Năm 1919, Quốc tế Cộng sản được thành lập tại Mátxcova và trở thành Bộ tham mưu lãnh đạo phong trào cách mạng thế giới. Dưới sự lãnh đạo của Lênin, Quốc tế cộng sản đầy mạnh việc gì?","dapAn":["Việc giác ngộ lý tưởng về cách mạng tháng Mười Nga và kinh nghiệm của thế giới về cách mạng","Việc truyền bá chủ nghĩa Mác- Lênin và kinh nghiệm cách mạng tháng Mười Nga ra thế giới","Việc tuyên truyền chủ nghĩa Mác - Lênin và kinh ngiệm của cách mạng tháng Mười Nga ra thể giới","Việc giới thiệu chủ nghĩa Mác - Lênin và kinh nghiệm của cách mạng tháng Mười Nga ra thế giới"],"dung":"B"},{"id":71,"chuong":2,"cauHoi":"Hồ Chí Minh đã vận dụng sáng tạo những triết lý của đạo Phật đề đoàn kết đồng bào theo Đạo phật, đoàn kết toàn dân vì:","dapAn":["Nước Việt Nam thái bình, thịnh trị, dân chủ chủ và giàu mạnh","Nước Việt Nam hòa bình, thống nhất, độc lập, dân chủ và giàu mạnh","Nước Việt Nam hoàn toàn được giải phóng, thống nhất, dân chủ","Nước Việt Nam dân chủ, sánh vai với các cường quốc năm châu"],"dung":"B"},{"id":72,"chuong":2,"cauHoi":"Hồ Chí Minh đã tìm thấy những điểm tích cực nào trong chủ nghĩa Tam dân của Tôn Trung Sơn?","dapAn":["Dân tộc độc lập, dân quyền tự do, dân sinh hạnh phúc","Con người sống hòa hợp với thiên nhiên","Tư tưởng từ bi, bác ái, yêu thương con người","Đề cao quyền bình đẳng của con người"],"dung":"A"},{"id":73,"chuong":2,"cauHoi":"Hồ Chí Minh đã trực tiếp nghiên cứu tư tưởng nào của các nhà khai sáng phương Tây như Vonte, Rutxo, Mongtetxkio trong hành trình đi tìm đường cứu nước, cứu dân?","dapAn":["Tư tưởng nhân văn, công bằng, dân chủ.","Tư tưởng nhân văn, dân chủ và nhà nước pháp quyền","Tư tưởng nhân văn, dân chủ, công bằng và nhà nước pháp quyền","Tư tưởng nhân văn, dân chủ, độc lập, tự do."],"dung":"B"},{"id":74,"chuong":2,"cauHoi":"Yếu tố nào là cơ sở lý luận quyết định bước phát triển mới về chất trong tư tưởng Hồ Chí Minh, khiến Người vượt hẳn lên phía trước so với những người yêu nước cùng thời?","dapAn":["Cách mạng Tháng Mười Nga năm 1917, chủ nghĩa yêu nước, chủ nghĩa Mác - Lê-nin","Cách mạng Tháng Mười Nga năm 1917, thời đại mới, chủ nghĩa yêu nước, chủ nghĩa Mác - Lê-nin","Chủ nghĩa yêu nước chân chính, thời đại mới, chủ nghĩa Mác - Lê-nin","Cách mạng Tháng Mười Nga năm 1917, thời đại mới và chủ nghĩa Mác - Lê-nin."],"dung":"D"},{"id":75,"chuong":2,"cauHoi":"Đến với chủ nghĩa Mác - Lênin, Hồ Chí Minh đã giải quyết được cuộc khủng hoảng về đường lối cứu nước ở Việt Nam. Do đó, đối với Người, Chủ nghĩa Mác - Lê-nin là:","dapAn":["Kim chỉ nam cho mọi hoạt động của Đảng","Thế giới quan, phương pháp luận trong trong nhận thức và hoạt động cách mạng","Chủ nghĩa chân chính nhất trong số nhiều chủ nghĩa khác","Tất cả các đáp án"],"dung":"B"},{"id":76,"chuong":2,"cauHoi":"Với vốn hiểu biết sâu sắc kho tàng tri thức của nhân loại, Hồ Chí Minh đã khẳng định học thuyết của Không Tử có ưu điểm là gì?","dapAn":["Lòng nhân ái cao cả","Sự tu dưỡng đạo đức cá nhân","Đức hy sinh","Chính sách phù hợp với nước ta"],"dung":"B"},{"id":77,"chuong":2,"cauHoi":"Điều gì đã khiến Hồ Chí Minh sớm nhận thức và có hướng đi đúng để tìm ra con đường cứu nước, giải phóng dân tộc?","dapAn":["Xác định rõ bản chất của chủ nghĩa để quốc, thực dân","Nhận ra hạn chế của những người đi trước","Cuộc sống nghèo khổ, bị áp bức, bóc lột đến cùng cực của đồng bào mình","Hiểu rõ bản chất của những từ Tự do - Bình đăng - Bác ái"],"dung":"A"},{"id":78,"chuong":2,"cauHoi":"Tiếp thu truyền thống tốt đẹp của quê hương, gia đình và hiểu rõ tình cảnh nước nhà bị giặc ngoại xâm. Năm 1908, Hồ Chí Minh đã tham gia phòng trào gì?","dapAn":["Chống thuế ở Bắc Kỳ","Chống thuế ở Nam kỳ","Chống thuế ở Trung kỳ","Chống thuế ở Phan Thiết"],"dung":"C"},{"id":79,"chuong":2,"cauHoi":"Năm 1919, Hồ Chí Minh gia nhập Đảng Xã hội của giai cấp công nhân Pháp, bởi theo Người đây là một tổ chức như thế nào?","dapAn":["Theo đuổi lý tưởng cao quý của nền dân chủ Pháp: Mợi người có quyền sống, quyền mưu cầu hạnh phúc","Theo đuổi lý tưởng cao quý của Đại Cách mạng Pháp: Tự do, bình đăng, bắc ái","Theo đuổi lý tưởng cao quý của nền độc lập dân tộc Pháp: Mọi người đều bình đằng, hạnh phúc, tự do","Theo đuổi lý tưởng cao quý của nền công nghiệp Pháp: Tự do, bình đẳng, bắc ái"],"dung":"B"},{"id":80,"chuong":2,"cauHoi":"Bản \"Yêu sách của nhân dân An Nam\" được ký tên Nguyễn Ái Quốc có tiếng nói như thế nào trên diễn đàn quốc tế?","dapAn":["Tiếng nói chân chính của đại biêu phong trào giải phóng dân tộc ở các nước thuộc địa","Tiếng nói chính nghĩa của nhân dân An Nam trong phong trào đấu tranh giải phóng dân tộc","Tiếng nói chính nghĩa đầu tiên của đại biểu phong trào giải phóng dân tộc Việt Nam","Tiếng nói chính nghĩa của đại biểu phương Đông về phong trào đấu tranh giải phóng dân tộc ở các nước"],"dung":"C"},{"id":81,"chuong":2,"cauHoi":"Khi nghiên cứu \"Sơ thảo lần thứ nhất những luận cương về vấn đề dân tộc và vấn đề thuộc địa\"(1920) của Lênin, Hồ Chí Minh đã tìm thấy và xác định rõ điều gì?","dapAn":["Phương hướng đấu tranh giải phóng giai cấp Việt Nam theo con đường cách mạng vô sản","Phương hướng đấu tranh giải phóng dân tộc Việt Nam theo con đường cách mạng vô sản","Phương hướng đấu tranh giải phóng dân tộc Việt Nam theo con đường cách mạng tư sản","Phương hướng đấu tranh giải phóng giai cấp theo con đường cách mạng tư sản"],"dung":"B"},{"id":82,"chuong":2,"cauHoi":"Năm 1922, Hồ Chí Minh sáng lập từ báo Le Paria (Người cùng khổ) bằng tiếng Pháp gửi đến các thuộc địa của Pháp, trong đó có Đông Dương để nhằm thức tỉnh điều gì?","dapAn":["Tinh thần giải phóng dân tộc của nhân dân các nước thuộc địa","Tinh thần đoàn kết của nhân dân các nước thuộc địa","Tinh thần chiến đấu của nhân dân các dân tộc thuộc địa","Tinh thần chính nghĩa của nhân dân các dân tộc thuộc địa"],"dung":"A"},{"id":83,"chuong":2,"cauHoi":"Khi tổng kết các cuộc cách mạng của các nước, Hồ Chí Minh vạch rõ cách mạng Việt phải có:","dapAn":["Đảng cộng sản kết hợp với chủ nghĩa Mác - Lê-nin và tư tưởng Hồ Chí Minh","Đảng cộng sản và chủ nghĩa Mác - Lê-nin làm cốt để lãnh đạo; lực lượng cách mạng là toàn thể nhân dân Việt Nam, trong đó nòng cốt là liên minh công nông","Đảng cộng sản kết hợp với chủ nghĩa yêu nước và tư tưởng Hồ Chí Minh","Đảng cộng sản kết hợp với chủ nghĩa Mác - Lê-nin và chủ nghĩa yêu nước chân chính."],"dung":"B"},{"id":84,"chuong":2,"cauHoi":"Tác phẩm Đường cách mệnh của Hồ Chí Minh được xuất bản năm 1927 ở Quảng Châu, Trung Quốc là bước chuẩn bị như thế nào cho sự ra đời của Đảng Cộng sản Việt Nam?","dapAn":["Về phương hướng, sách lược, tổ chức","Về lực lượng, cách thức, tổ chức","Về tư tưởng, chính trị, tổ chức","Về tư tưởng, phương pháp, tổ chức"],"dung":"C"},{"id":85,"chuong":2,"cauHoi":"Trong thời kỳ 1930-1941, một số người trong Quốc tế Cộng sản và Đảng Cộng sản Việt Nam có những nhìn nhận sai lầm về Hồ Chí Minh như thế nào?","dapAn":["Do chịu ảnh hưởng của các khuynh hướng trong Quốc tế Cộng sản","Do không nắm vững tình hình các dân tộc thuộc địa và ở Đông Dương","Do chịu sức ép từ Quốc tế Cộng sản về con đường giải phóng dân tộc","Do không nắm được tư tưởng đúng đắn, sáng tạo của Hồ Chí Minh về còn đường cách mạng ở các nước thuộc địa"],"dung":"B"},{"id":86,"chuong":2,"cauHoi":"Nhận thấy thời cuộc có những chuyển biến lớn, Hồ Chí Minh đã gửi thư cho Quốc tế Cộng sản đề nghị vấn đề gì?","dapAn":["Cho phép tham gia các phong trào cách mạng ở Liên Xô","Cho phép trở về nước trực tiếp tham gia lãnh đạo cách mạng Việt Nam","Cho phép tham gia các cuộc đấu tranh giải phóng dân tộc","Cho phép tham gia thành lập các tổ chức đảng để lãnh đạo cách mạng ."],"dung":"B"},{"id":87,"chuong":2,"cauHoi":"Luận điểm của Hồ Chí Minh: \"Trong lúc này (...). Chúng ta phải đoàn kết lại đánh đổ bọn (...) đặng cứu giống nòi ra khỏi nước sôi lửa nóng\"2. Xác định cụm từ còn thiếu?","dapAn":["Quyền dân chủ được đặt lên hàng đầu/ đại địa chủ và tay sai phản động","Quyền lợi dân tộc giải phóng cao hơn hết thảy/ đế quốc và Việt gian","Quyền tự quyết của dân tộc được đặt lên trên hết, trước hết/ đế quốc và Việt gian","Quyền bình đẳng của dân tộc được đề cao nhất/ đế quốc và Việt gian"],"dung":"B"},{"id":88,"chuong":2,"cauHoi":"Hồ Chí Minh đọc bản Tuyên ngôn Độc lập. Nước Việt Nam Dân chủ Cộng hòa ra đời đã mở điều gì trong lịch sử dân tộc Việt Nam?","dapAn":["Mở ra một thời đại mới - thời đại độc lập dân tộc gắn liền với chủ nghĩa xã hội","Mở ra một kỷ nguyên mới - kỷ nguyên độc lập dân tộc gắn liền với chủ nghĩa xã hội","Mở ra một chế độ mới - chế độ độc lập dân tộc gắn liền với chủ nghĩa xã hội","Mở ra một đất nước mới - đất nước độc lập dân tộc gắn liền với chủ nghĩa xã hội"],"dung":"B"},{"id":89,"chuong":2,"cauHoi":"Trong Lời kêu gọi toàn quốc kháng chiến của Hồ Chí Minh ngày 19/12/1946 vừa thể hiện khái quát đường lối kháng chiến chống thực dân Pháp, vừa là:","dapAn":["Lời thề thiêng liêng bảo vệ Tổ quốc, với ý chí, quyết tâm thà hy sinh tất cả chứ không chịu mất nước...","Lời thề thiêng liêng về bảo vệ chủ quyền quốc gia dân tộc, với sự quyết tâm đánh đồ để quốc chủ nghĩa thực dân Pháp trên đất nước ta...","Lời tuyên bố trước toàn thể quốc dân đồng bào, với ý chí quyết tâm giành được độc lập dân tộc","Tất cả các đáp án"],"dung":"A"},{"id":90,"chuong":2,"cauHoi":"Giá trị của tư tưởng Hồ Chí Minh đối với cách mạng Việt Nam là gì?","dapAn":["Đưa cách mạng giải phóng dân tộc Việt Nam đến thắng lợi và bắt đầu xây dựng một xã hội mới trên đất nước ta; góp phần mở ra cho các dân tộc thuộc địa con đường giải phóng dân tộc","Đưa cách mạng giải phóng dân tộc Việt Nam đến thắng lợi và bắt đầu xây dựng một xã hội mới trên đất nước ta; là nền tảng tư tưởng và kim chỉ nam cho cách mạng Việt Nam","Là nền tảng tư tưởng và kim chỉ nam cho cách mạng Việt Nam; góp phần mở ra cho các dân tộc thuộc địa con đường giải phóng dân tộc","Góp phần mở ra cho các dân tộc thuộc địa con đường giải phóng dân tộc và góp phần tích cực vào cuộc đấu tranh vì độc lập dân tộc, dân chủ, hòa bình, hợp tác và phát triển trên thế giới."],"dung":"B"},{"id":91,"chuong":2,"cauHoi":"Gía trị của tư tưởng Hồ Chí Minh đối với sự phát triển tiến bộ của nhân loại là gì? .","dapAn":["Góp phần mở ra cho các dân tộc thuộc địa con đường giải phóng dân tộc gắn với sự tiến bộ xã hội; góp phần tích cực vào cuộc đấu tranh vì độc lập dân tộc, dần chủ, hòa bình, hợp tác và phát triển trên thế giới","Là nền tảng, kim chỉ nam cho mọi hành động của Đảng; góp phần mở ra cho các dân tộc thuộc địa con đường giải phóng dân tộc gắn với sự tiến bộ xã hội","Đưa cách mạng giải phóng dân tộc Việt Nam đến thắng lợi và bắt đầu xây dựng một xã hội mới trên đất nước ta; góp phần mở ra cho các dân tộc thuộc địa con đường giải phóng dân tộc","Là nền tảng tư tưởng và kim chỉ nam cho cách mạng Việt Nam; góp phần mở ra cho các dân tộc thuộc địa con đường giải phóng dân tộc, dân chủ, hòa bình, phát triển"],"dung":"A"},{"id":92,"chuong":2,"cauHoi":"Chọn phương án đúng nhất với chặng đường hơn một nửa thế kỷ qua, tư tưởng Hồ Chí Minh trở thành:","dapAn":["Kim chỉ nam dẫn dắt cách mạng nước ta đi từ thắng lợi này đến thắng lợi khác","Ngọn cờ tư tưởng dẫn đường cách mạng nước ta đi từ thắng lợi này đến thắng lợi khác","Phương pháp dẫn đường cách mạng nước ta đi từ thắng lợi này đến thắng lợi khác","Giá trị dẫn dắt cách mạng nước ta đi từ thắng lợi này đến thắng lợi khác"],"dung":"B"},{"id":93,"chuong":3,"cauHoi":"Năm 1919, Nguyễn Ái Quốc đã nhân danh ai để gửi tới Hội nghị Vécxây bản Yêu sách của nhân dân An Nam?","dapAn":["Những người Việt Nam yêu nước tại Pháp","Những người Việt Nam yêu nước tại Anh","Những người Việt Nam yêu nước tại Trung Quốc","Những người Việt Nam yêu nước tại Việt Nam"],"dung":"A"},{"id":94,"chuong":3,"cauHoi":"Ngày 19/12/1946, trong Lời kêu gọi toàn quốc kháng chiến, Hồ Chí Minh đã thể hiện sự quyết tâm sắt đá, bảo vệ nền độc lập dân tộc mà nhân dân Việt Nam mới giành được là gì?","dapAn":["\"Không có gì quý hơn độc lập, tự do\"","\"Không! Chúng ta thà hy sinh tất cả, chứ nhất định không chịu mất nước, nhất định không chịu làm nô lệ\"","\"Người ta sinh ra tự do và bình đẳng về quyền lợi, và phải luôn được tự do và bình đẳng về quyền lợi\"","\"Nước độc lập mà dân không hưởng hạnh phúc tự do, thì độc lập cũng chẳng có nghĩa lý gì\""],"dung":"B"},{"id":95,"chuong":3,"cauHoi":"Theo Hồ Chí Minh, cách mạng giải phóng dân tộc ở Việt Nam muốn thắng lợi phải thi theo con đường nào?","dapAn":["Cách mạng tư sản","Cách mạng vô sản","Cách mạng bạo lực","Tất cả các đáp án"],"dung":"B"},{"id":96,"chuong":3,"cauHoi":"Sau khi đọc bản Sơ thảo lần thứ nhất những luận cương về vấn đề dân tộc và vấn đề thuộc địa của Lênin, Hồ Chí Minh đã tìm thấy con đường cứu nước, giải phóng dân tộc. Người đọc bản Sơ thảo này vào năm nào và ở đâu?","dapAn":["Năm 1911, ở Anh","Năm 1919, ở Nga","Năm 1920, ở Pháp","Năm 1925, ở Trung Quốc"],"dung":"C"},{"id":97,"chuong":3,"cauHoi":"Vai trò lãnh đạo của Đảng Cộng sản được Hồ Chí Minh khẳng định là đội tiên phong của giai cấp nào trong sự nghiệp cách mạng?","dapAn":["Tư sản, nhân dân lao động","Công nhân, nhân dân lao động","Đội ngũ trí thức, nhân dân lao động","Tất cả các đáp án"],"dung":"B"},{"id":98,"chuong":3,"cauHoi":"Muốn xây dựng chủ nghĩa xã hội, trước hết cần có những con người xã hội chủ nghĩa\". Hồ Chí Minh đã giải thích vấn đề này như thế nào?","dapAn":["Mỗi người cần bồi dưỡng cho mình có ý thức làm chủ, có tinh thần tập thể xã hội chủ nghĩa và tư tưởng \"mình vì mọi người, mọi người vì mình\"","Có quan điểm \"tất cả phục vụ sản xuất\"; có ý thức cần kiệm xây dựng nước nhà; có tinh thần tiến nhanh, tiến mạnh, tiến vững chắc...","Phải chống lại những tư tưởng, tác phong xấu là: Chủ nghĩa cá nhân; quan liêu, mệnh lệnh; tham ô, lãng phí; bảo thủ, rụt rè","Tất cả các đáp án"],"dung":"D"},{"id":99,"chuong":3,"cauHoi":"Trong thời kỳ đổi mới hiện nay, vận dụng tư tưởng Hồ Chí Minh về chủ nghĩa xã hội đã đạt được những thành tựu to lớn, tuy nhiên vẫn còn phải đổi diện với những thách thức, nguy cơ lớn nào?","dapAn":["Tụt hậu xa hơn về kinh tế so với các nước trong khu vực và trên thế giới","Âm mưu thực hiện \"diễn biến hòa bình\" của thế lực thù địch nhằm chống phá nước ta; sự tồn tại và những diễn biến phức tạp của tệ quan liêu, tham nhũng, lãng phí","Tình trạng suy thoái về tư tưởng chính trị, đạo đức, lối sống, những biểu hiện \"tự diễn biến\", \"tự chuyển hóa\" trong một bộ phận cán bộ, đảng viên, công chức, viên chứ","Tất cả các đáp án"],"dung":"D"},{"id":100,"chuong":3,"cauHoi":"Chủ nghĩa xã hội là chế độ xã hội có bản chất khác hẳn với các xã hội đã tồn tại trong lịch sử, do đó Hồ Chí Minh khăng định trong xã hội xã hội chủ nghĩa có những đặc trưng cơ bản trên các lĩnh vực gì?","dapAn":["Về chính trị; Về kinh tế","Về văn hóa, đạo đức và các quan hệ xã hội","Về chủ thể xây dựng chủ nghĩa xã hội","Tất cả các đáp án"],"dung":"D"},{"id":101,"chuong":3,"cauHoi":"Với tư cách làm chủ, nhân dân phải làm tròn nhiệm vụ để xây dựng thành công chủ nghĩa xã hội, theo Hồ Chí Minh trong đó mọi người có quyền gì?","dapAn":["Làm việc, nghỉ ngơi, học tập","Tự do thân thể, ngôn luận, báo chí, hội họp","Tự do tín ngưỡng hoặc không theo tôn giáo nào; có quyền bầu cử, ứng cử","Tất cả các đáp án"],"dung":"D"},{"id":102,"chuong":3,"cauHoi":"Để đạt được những mục tiêu của chủ nghĩa xã hội, theo Hồ Chí Minh hệ thống động lực thúc đẩy tiến trình cách mạng xã hội chủ nghĩa ở Việt Nam là gì?","dapAn":["Trong quá khứ, hiện tại và tương lai,","Vật chất và tinh thần,","Nội lực và ngoại lực, v.v... ở tất cả các lĩnh vực như kinh tế, chính trị, văn hóa, khoa học, giáo dục","Tất cả các đáp án"],"dung":"D"},{"id":103,"chuong":3,"cauHoi":"Đặc điểm của thời kỳ quá độ lên chủ nghĩa xã hội ở Việt Nam được Hồ Chí Minh khẳng định là gì?","dapAn":["Từ một nước công nghiệp tiên tiến đi lên CNXH, không trải qua giai đoạn tư bản chủ nghĩa","Từ một nước nông nghiệp lạc hậu tiến thăng lên CNXH, không trải qua giai đoạn phát trên tư bản chủ nghĩa","Từ một nước có nền kinh tế cao tiến thẳng lên CNXH, không trải qua giai đoạn tư bản chủ nghĩa","Từ một nước có khoa học - kỹ thuật tiên tiến lên CNXH, không trải qua giai đoạn tư bản chủ nghĩa"],"dung":"B"},{"id":104,"chuong":3,"cauHoi":"Nhiệm vụ lịch sử của thời kỳ quá độ lên chủ nghĩa xã hội ở Việt Nam được Hồ Chí Minh xác định như thế nào?","dapAn":["Cải tạo, xóa bỏ tàn tích của chế độ xã hội cũ, xây dựng các yếu tố mới phù hợp với quy luật tiến lên CNXH","Thực hiện xây dựng nền văn hóa xã hội chủ nghĩa, phù hợp với nguyện vọng của nhân dân","Xây dựng con người mới của chủ nghĩa xã hội, phù hợp với quy luật tiến lên CNXH","Tất cả các đáp án"],"dung":"A"},{"id":105,"chuong":3,"cauHoi":"Theo Hồ Chí Minh, nguyên tắc xây dựng chủ nghĩa xã hội trong thời kỳ quá độ là gì?","dapAn":["Mọi tư tưởng, hành động phải được thực hiện trên nền tảng chủ nghĩa Mác- Lênin","Phải giữ vững độc lập dân tộc; phải đoàn kết, học tập kinh nghiệm của các nước anh em","Xây phải đi đôi với chống","Tất cả các đáp án"],"dung":"D"},{"id":106,"chuong":3,"cauHoi":"Năm 1960, Hồ Chí Minh khẳng định: \"Chỉ có chủ nghĩa xã hội, chủ nghĩa cộng sản mới giải phóng được (...) bị áp bức và những (...) trên thế giới khỏi ách (...)\"I!. Xác định cụm từ còn thiếu?","dapAn":["Các giai cấp/ người lao động/ nô lệ","Các dân tộc/ người lao động/ nô lệ","Các xã hội/ người lao động/ nô lệ","Các cá nhân/ người lao động/ nô lệ"],"dung":"B"},{"id":107,"chuong":3,"cauHoi":"Theo Hồ Chí Minh, cần có những điều kiện cơ bản nào để bảo đảm độc lập dân tộc gắn liền với chủ nghĩa xã hội?","dapAn":["Phải bảo đảm vai trò lãnh đạo tuyệt đối của đảng cộng sản trong suốt tiến trình cách mạng","Phải củng cố và tăng cường khối đại đoàn kết dân tộc mà nền tảng là khối liên minh công - nông","Phải đoàn kết, gắn bó chặt chẽ với cách mạng thế giới","Tất cả các đáp án"],"dung":"D"},{"id":108,"chuong":3,"cauHoi":"Mục tiêu về văn hóa trong xây dựng CNXH ở Việt Nam, Hồ Chí Minh cho rằng mối quan hệ giữa văn hóa với chính trị và kinh tế là mối quan hệ biện chứng. Do đó, chế độ chính trị và kinh tế của xã hội là:","dapAn":["Nền tảng và quyết định tính chất của văn hóa; còn văn hóa góp phần thực hiện mục tiêu của chính trị và kinh tế","Nền tảng và quyết định tính chất của văn hóa; còn văn hóa góp phần soi đường cho quốc dân đi","Nền tảng và quyết định tính chất của văn hóa; còn văn hóa góp phần nâng cao trình độ văn hóa của nhân dân","Nền tảng và quyết định tính chất của văn hóa; còn văn hóa phát triển là điều kiện cho nhân dân tiến bộ"],"dung":"A"},{"id":109,"chuong":3,"cauHoi":"Chọn phương án trả lời đúng nhất với tư tưởng Hồ Chí Minh về động lực của chủ nghĩa xã hội ở Việt Nam?","dapAn":["Sức mạnh đại đoàn kết toàn dân","Sức mạnh của nhân dân lao động","Sức mạnh của địa vị nhân dân và các tầng lớp trong xã hội","Sức mạnh lao động sáng tạo của hàng triệu quần chúng nhân dân"],"dung":"A"},{"id":110,"chuong":3,"cauHoi":"Trong bối cảnh nền kinh tế của nước ta còn nghèo nàn, lạc hậu Hồ Chí Minh đã xác định nhiệm vụ quan trọng nhất của thời kỳ quá độ là gì?","dapAn":["Xây dựng cơ sở vật chất và phát huy thế mạnh của nền kinh tế gắn công công nông nghiệp hiện đại","Huy động sức mạnh của nhân dân trong cải tạo nền kinh tế sau cuộc cách mạng giải phóng dân tộc","Cải tạo nền kinh tế cũ, xây dựng nền kinh tế mới có công nghiệp và nông nghiệp hiện đại","Phát huy hết tài năng, sức lực, của cải của nhân dân vào xây dựng nền kinh tế mới với khoa học kỹ thuật hiện đại"],"dung":"C"},{"id":111,"chuong":3,"cauHoi":"Chọn phương án trả lời đúng với tư tưởng Hồ Chí Minh về độc lập dân tộc và chủ nghĩa xã hội có môi quan hệ như thế nào?","dapAn":["Chủ nghĩa xã hội quyết định giải phóng dân tộc; giải phóng dân tộc là điều kiện đảm bảo thắng lợi chủ nghĩa xã hội","Độc lập dân tộc là cơ sở, tiền đề để tiến lên CNXH; CNXH là điều kiện đảm bảo nên độc lập dân tộc vững chắc","Độc lập dân tộc và chủ nghĩa xã hội là ngọn cờ dẫn dắt cách mạng giải phóng dân tộc thắng lợi","Chủ nghĩa xã hội là cơ sở, tiền đề để giải phóng dân tộc; giải phóng dân tộc là điều kiện đảm bảo xây dựng chủ nghĩa xã hội"],"dung":"B"},{"id":112,"chuong":3,"cauHoi":"Khi đề cao mục tiêu độc lập dân tộc, Hồ Chí Minh đã không coi đó là mục tiêu cuối cùng của cách mạng, mà là tiền đề cho:","dapAn":["Cuộc cách mạng xã hội chủ nghĩa","Cuộc cách mạng giải phóng dân tộc","Cách mạng tư sản chủ nghĩa","Cách mạng dân tộc dân chủ nhân dân"],"dung":"A"},{"id":113,"chuong":3,"cauHoi":"Đầu năm 1930, trong Chánh cương vắn tắt của Đảng, Người đã xác định mục tiêu chính trị của Đảng và cách mạng Việt Nam là gì?","dapAn":["Đánh đổ bọn phong kiến và để quốc chủ nghĩa; Làm cho nước Nam bình đẳng. hạnh phúc","Đánh đồ để quốc chủ nghĩa Pháp và bọn phong kiến; Làm cho nước Nam hoàn toàn độc lập","Đánh đổ cai cấp địa chủ và chủ nghĩa đế quốc Pháp; Làm cho nước Nam hòa bình thống nhất","Đánh đổ đế quốc chủ nghĩa Pháp và bè lũ tay sai; Làm cho nước Nam hòa bình, phồn thịnh"],"dung":"B"},{"id":114,"chuong":3,"cauHoi":"Trong bản Tuyên ngôn Độc lập (1945), Hồ Chí Minh thay mặt Chính phủ lâm thời tuyên bố trước quốc dân đồng bào và thế giới vấn đề gì?","dapAn":["Nước Việt Nam thực sự đã trở thành một nước tự do và độc lập","Nước Việt Nam thực sự đã trở thành một nước thái bình và thịnh trị","Nước Việt Nam thực sự đã trở thành một nước độc lập và tự quyết","Nước Việt Nam thực sự đã trở thành một nước tự do, ấm no, hạnh phúc"],"dung":"A"},{"id":115,"chuong":3,"cauHoi":"Với ý chí quyết tâm thực hiện cuộc kháng chiến chống Pháp và chống Mỹ, trong thư gửi Liên hợp quốc (1946), Hồ Chí Minh đã khẳng định nội dung nào sau đây?","dapAn":["Nhân dân chúng tôi cũng kiên quyết chiến đấu đến cùng để bảo vệ những quyền thiêng liêng nhất: hòa bình, thống nhất và độc lập cho dân tộc","Nhân dân chúng tôi cũng kiên quyết chiến đấu đến cùng để bảo vệ những quyền thiêng liêng nhất: hạnh phúc cho dân tộc và độc lập cho quê hương","Nhân dân chúng tôi cũng kiên quyết chiến đấu đến cùng để bảo vệ những quyền thiêng liêng nhất: toàn vẹn lãnh thổ cho Tổ quốc và độc lập cho đất nước","Nhân dân chúng tôi cũng kiên quyết chiến đấu đến cùng để bảo vệ những quyền thiêng liêng nhất: độc lập cho dân tộc và hạnh phúc cho nhân dân"],"dung":"C"},{"id":116,"chuong":3,"cauHoi":"Khi Mỹ tăng cường mở rộng chiến tranh, Hồ Chí Minh đã nêu lên một chân lý thời đại, một tuyên ngôn bất hủ của các dân tộc khao khát nền độc lập, tự do trên thế giới là gì?","dapAn":["\"Nhân dân chúng tôi kiên quyết chiến đấu đến cùng để bảo vệ những quyền thiêng liêng nhất: Toàn vẹn lãnh thổ cho Tổ quốc và độc lập cho đất nước\"","\"Nước Việt Nam có quyền hưởng tự do và độc lập, và sự thật đã thành một nước tự do và độc lập\"","\"Không! Chúng ta thà hy sinh tất cả chứ nhất định không chịu mất nước, nhất định không chịu làm nô lệ\"","\"Không có gì quý hơn độc lập, tự do\""],"dung":"D"},{"id":117,"chuong":3,"cauHoi":"Khi viện dẫn bản Tuyên ngôn Nhân quyền và Dân quyền của Cách mạng Pháp (1791), \"người ta sinh ra tự do và bình đẳng về quyền lợi, và phải luôn được tự do và bình đẳng về quyền lợi\"16 Hồ Chí Minh đã kết luận thế nào?","dapAn":["Đó là lẽ phải thuộc về quyền của mỗi người","Đó là lẽ phải không ai chối cãi được","Đó là lẽ phải thuộc về quyền độc lập, tự do của các dân tộc","Đó là lẽ phải mà tất cả các dân tộc đều được hưởng"],"dung":"B"},{"id":118,"chuong":3,"cauHoi":"Hồ Chí Minh khẳng định: \"Nước độc lập mà (..), thì độc lập cũng chẳng có nghĩa lý gìl?. Xác định cụm từ còn thiều?","dapAn":["Dân không làm những điều mình muốn","Dân không hưởng hạnh phúc tự do","Dân không được quyền thực hiện tự do ngôn luộn","Dân không hưởng quyền bình đẳng tự do"],"dung":"B"},{"id":119,"chuong":3,"cauHoi":"Hồ Chí Minh nhấn mạnh: Độc lập mà người dân không có quyền tự quyết về ngoại giao, không có quân đội riêng, không có nền tài chính riêng..., thì độc lập đó chẳng có ý nghĩa gì, nhằm khẳng định độc lập phải như thế nào?","dapAn":["Độc lập hoàn toàn, độc lập triệt để và tự quyết trên tất cả các lĩnh vực","Độc lập thật sự, độc lập thống nhất và bình đẳng trên tất cả các lĩnh vực","Độc lập chủ quyền, toàn vẹn lãnh thổ và liên hiệp trên tất cả các lĩnh vực","Độc lập thật sự, độc lập hoàn toàn và triệt để trên tất cả các lĩnh vực"],"dung":"D"},{"id":120,"chuong":3,"cauHoi":"Khi thực dân Pháp bày ra cái gọi là \"Nam kỳ tự trị\" hòng chia cắt đất nước ta một lần nữa, trong hoàn cảnh đó, Hồ Chí Minh đã khẳng định điều gì?","dapAn":["Đồng bào Nam bộ là dân nước Việt Nam, sông có thể cạn, núi có thể mòn, song chân lý đó không bao giờ thay đổi","Đồng bào Nam bộ là dân nước Việt Nam, sông có thể rộng, núi có thể cao, song chân lý đó không bao giờ thay đổi","Đồng bào Nam bộ là dân nước Việt Nam, sông có thể bồi lấp, núi có thể sạt lở, song chân lý ấy không bao giờ thay đổi","Đồng bào Nam bộ là dân nước Việt Nam, sông có thể sâu, núi có thể cao, song chân lý ấy là mãi mã"],"dung":"A"},{"id":121,"chuong":3,"cauHoi":"Thành công của cuộc cách mạng tháng 10 Nga (1917) đã ảnh hưởng sâu sắc tới Hồ Chí Minh trong việc lựa chọn con đường cứu nước, giải phóng dân tộc. Người đã nhận định như thế nào về cuộc cách mạng này?","dapAn":["Đây là cuộc cách mạng thành công đến nơi, nghĩa là dân chúng được hướng quyền tự quyết, bình đẳng, dân chủ thật sự...","Đây là cuộc cách mạng thành công đến nơi, nghĩa là dân chúng được quyền trao đổi, giao lưu, học hỏi, bình đắng thật sự ...","Đây là cuộc cách mạng thành công đến nơi, nghĩa là dân chúng được hưởng hạnh phúc, tự do, bình đắng thật sự...","Đây là cuộc cách mạng thành công đến nơi, nghĩa là dân chúng được hưởng quyền sung sướng, tự do, hạnh phúc thật sự..."],"dung":"C"},{"id":122,"chuong":3,"cauHoi":"Trong bài viết Con đường dẫn tôi đến chủ nghĩa Lênin (1960), Hồ Chí Minh đã nhận định như thế nào về Luận cương của Lênin?","dapAn":["Đây là cái cần thiết, là con đường dẫn chúng ta đi tới thắng lợi","Đây là cái cần thiết cho chúng ta, là con đường giải phóng chúng ta","Đây là cái cần thiết, là mục tiêu giải phóng dân tộc ta","Đây là cái cần thiết, là con đường thành công của cách mạng"],"dung":"B"},{"id":123,"chuong":3,"cauHoi":"Trong Chánh cương vắn tắt của Đảng năm 1930, Hồ Chí Minh khẳng định phương hướng chiến lược của cách mạng Việt Nam là gì?","dapAn":["Làm tư sản dân quyền cách mạng và những vấn đề của cách mạng để đi tới xã hội chủ nghĩa","Làm cuộc cải cách ruộng đất cho dân cày nghèo và tập trung nguồn lực xây dựng chủ nghĩa xã hội","Làm tư sản dân quyền cách mạng và giải phóng các giai tầng trong xã hội để đi tới xã hội cộng sản","Làm tư sản dân quyền cách mạng và thổ địa cách mạng để đi tới xã hội cộng sản"],"dung":"D"},{"id":124,"chuong":3,"cauHoi":"Trong bản Yêu sách của nhân dân An Nam, Hồ Chí Minh đã đề nghị cho người An Nam cũng được hưởng quyền lợi gì như người dân ở Châu Âu?","dapAn":["Quyền tự quyết về chế độ dân chủ và các quyền tự do, ngôn luận của nhân dân","Quyền độc lập về mặt pháp lý và các quyền tự do, hạnh phúc của nhân dân","Quyền bình đăng về mặt pháp lý và các quyền tự do, dân chủ của người dân","Quyền liên hiệp về mặt pháp lý và các quyền tự dơ hội họp của người dân"],"dung":"C"},{"id":125,"chuong":3,"cauHoi":"Khi tiếp thu bản Tuyên ngôn Độc lập của Mỹ (1776), Tuyên ngôn Nhân quyền và Dân quyền của Pháp (1791), Hồ Chí Minh đã khẳng định giá trị thiêng liêng, bất biến về quyền dân tộc như thế nào?","dapAn":["\"Trong lúc này quyền lợi dân tộc giải phóng cao cao hơn hết thảy\"","\"Dù phải hy sinh tới đâu, dù phải đốt cháy cả dãy Trường sơn cũng phải kiên quyết giành cho được độc lập\"","\"Nước Việt Nam có quyền hưởng tự do và độc lập, và sự thật đã thành một nước tự do và độc lập'\"","\"Tất cả các dân tộc trên thế giới đều sinh ra bình đắng, dân tộc nào cũng có quyền sống, quyền sung sướng và quyền tự do\""],"dung":"D"},{"id":126,"chuong":3,"cauHoi":"Theo Hồ Chí Minh, cách mạng giải phóng dân tộc trong điều kiện của Việt Nam muốn giành được thắng lợi phải do tố chức nào lãnh đạo?","dapAn":["Đảng Cộng sản lãnh đạo","Đảng nhân dân cách mạng","Đảng Công nhân xã hội dân chủ","Đảng vô sản kiểu mới"],"dung":"A"},{"id":127,"chuong":3,"cauHoi":"Khi kế thừa tư tưởng của các nhà lý luận Mác-Lênin về cách mạng là sự nghiệp của quần chúng nhân dân, Hồ Chí Minh đã khẳng định như thế nào?","dapAn":["\"Chỉ có giải phóng giai cấp vô sản thì mới giải phóng được dân tộc\"","\"Công cuộc giải phóng anh em chỉ có thể thực hiện được bằng sự nỗ lực tự của bản thân anh em'","\"Sự giải phóng của giai cấp công nhân phải là sự nghiệp của bản thân giai cấp công nhân'\"","\"Cách mệnh là việc chung cả dân chúng chứ không phải việc một hai người\""],"dung":"D"},{"id":128,"chuong":3,"cauHoi":"Trong Lời kêu gọi toàn quốc kháng chiến (12-1946), Hồ Chí Minh viết: \"Bất kỳ đàn ông, đàn bà, (...). Hễ là người Việt Nam thì phải đứng lên đánh thực dân Pháp để cứu Tổ quốc\"26. Xác định cụm từ còn thiếu?","dapAn":["Bất kỳ người già, người trẻ, không chia tôn giáo, đảng phái","Bất kỳ người già, thanh niên, phân chia tôn giáo, bè phái","Bất kỳ người già, trẻ nhỏ, không phân chia tôn giáo, đảng phái","Bất kỳ người già, phụ nữ, không phân chia tôn giáo, đảng phái"],"dung":"A"},{"id":129,"chuong":3,"cauHoi":"Khi khẳng định về mối quan hệ bình đẳng trong cuộc cách mạng ở thuộc địa và chính quốc, Hồ Chí Minh đã lấy hình tượng nào sau đây để miêu tả về chủ nghĩa tư bản?","dapAn":["Con chim đại bàng","Con sam","Con bạch tuộc","Con đỉa có hai vòi"],"dung":"D"},{"id":130,"chuong":3,"cauHoi":"Tại Đại hội V của Quốc tế Cộng sản (1924), Hồ Chí Min đã phát biểu để \"thức tỉnh... về vấn đề thuộc địa\"27 và Người cho rằng:","dapAn":["Nọc độc và sức sống của con rắn độc tư bản chủ nghĩa đang tập trung ở các nước thuộc địa","Sức sống mãnh liệt của các nước tư bản chủ nghĩa đều tập trung ở các nước thuộc địa","Chủ nghĩa tư bản là con đại bàng chuyên đi xâm chiếm, khai thác vơ vét các nước thuộc địa","Nọc độc và sức sống của chủ nghĩa tư bản đang tập trung ở chính các nước chính quốc"],"dung":"A"},{"id":131,"chuong":3,"cauHoi":"Việc xác định hình thức đấu tranh phải \"tuỳ tình hình cụ thể mà quyết định những hình thức đấu tranh cách mạng thích hợp, sử dụng (...) các hình thức đấu tranh vũ trang và đấu tranh chính trị để (....)28. Xác định cụm từ còn thiếu?","dapAn":["Nhanh và triệt để/ giành thắng lợi cho cách mạng","Linh hoạt và khéo/ giành thắng lợi cho cách mạng","Đúng và khéo kết hợp/ giành thắng lợi cho cách mạng","Hiệu quả và nhanh/ giành thắng lợi cho cách mạng"],"dung":"C"},{"id":132,"chuong":3,"cauHoi":"Tiến lên chủ nghĩa xã hội là một tất yếu khách quan, tuy nhiên ngay từ năm 1953 Hồ Chí Minh đã khẳng định phải tùy thuộc vào hoàn cảnh mà các dân tộc phát triển theo con đường khác nhau là gì?","dapAn":["Có nước đi thẳng lên chủ nghĩa xã hội; có nước phải phát triển qua con đường tư bản rồi mới tiến lên chủ nghĩa xã hội","Có nước thì đi thẳng lên chủ nghĩa xã hội; có nước thì phải kinh qua chế độ dân chủ mới rồi mới tiến lên chủ nghĩa xã hội","Có nước đi thẳng lên chủ nghĩa xã hội; có nước phải kinh qua con đường phong kiến rồi mới tiến lên chủ nghĩa xã hội","Có nước đi thẳng lên chủ nghĩa xã hội; có nước phải kinh qua con đường chiếm hữu nô lệ rồi mới tiến lên chủ nghĩa xã hội"],"dung":"B"},{"id":133,"chuong":3,"cauHoi":"Luận điểm nào sau đây thể hiện quan điểm của Hồ Chí Minh về thời Kỳ quá độ lên chủ nghĩa xã hội ở Việt Nam?","dapAn":["\"Chủ nghĩa xã hội là làm sao cho dân giàu nước mạnh\"29","\"Chủ nghĩa xã hội là mọi người cùng ra sức lao động sản xuất để được ăn no mặc ấm và có nhà ở sạch sẽ\"","Đảng phải \"lãnh đạo toàn dân thực hiện dân chủ mới, xây dựng điều kiện để tiến lên chủ nghĩa xã hội\"31","\"Chủ nghĩa xã hội là mọi người dân được áo ấm cơm no, nhà ở tử tế, được học hành '32"],"dung":"C"},{"id":134,"chuong":3,"cauHoi":"Dựa trên các nguyên tắc có tính chất phương pháp luận về xây dựng chủ nghĩa xã hội, Hồ Chí Minh đã chỉ đạo biện pháp cơ bản nào?","dapAn":["Đem của dân, tài dân, sức dân làm lợi cho dân","Đem sức mạnh văn hóa làm động lực cơ bản","Đem sức mạnh kinh tế làm động lực cơ bản","Tận dụng tối đa sức mạnh đoàn kết quốc tế để xây dựng chủ nghĩa xã hội"],"dung":"A"},{"id":135,"chuong":3,"cauHoi":"Chọn phương án sai với quan điểm Hồ Chí Minh về phương thức tiến lên chủ nghĩa xã hội?","dapAn":["Những nước nông nghiệp, công nghiệp lạc hậu, khoa học kỹ thuật kém phát triển","Những nước có nền kinh tế nghèo nàn, lạc hậu tiến thẳng lên CNXH không qua giai đoạn phát triển tư bản chủ nghĩa","Những nước đã qua giai đoạn phát triển tư bản chủ nghĩa sẽ \"đi thẳng\" lên CNXH;","Những nước chưa qua giai đoạn phát triển tư bản chủ nghĩa có thể đi lên CNXH sau khi đã \"đánh đồ để quốc và phong kiến\" dưới sự lãnh đạo của Đảng và tư tưởng của Mác - Lênin dẫn đường"],"dung":"A"},{"id":136,"chuong":3,"cauHoi":"Đặc trưng trên lĩnh vực chính trị được Hồ Chí Minh khẳng định là chế độ xã hội như thế nào?","dapAn":["Do giai cấp nông dân làm chủ","Do nhân dân làm chủ","Do giai cấp công nhân làm chủ","Do tầng lớp trí thức làm chủ"],"dung":"B"},{"id":137,"chuong":3,"cauHoi":"Hồ Chí Minh khẳng định trong CNXH, mọi quyền lợi, quyền lực, quyền hạn thuộc về nhân dân và mọi hoạt động (...) cũng thuộc về nhân dân. Xác định cụm từ còn thiếu?","dapAn":["Xây dựng, bảo vệ đất nước, bảo vệ chế độ xã hội","Xây dựng, phát triển kinh tế, bảo vệ chủ quyền","Xây dựng, phát triển văn hóa, bảo vệ độc lập","Xây dựng, phát triển xã hội, bảo vệ nền tảng tư tưởng"],"dung":"A"},{"id":138,"chuong":3,"cauHoi":"Theo Hồ Chí Minh, CNXH là chế độ xã hội có nền kinh tế phát triển cao dựa trên lực lượng sản xuất hiện đại và:","dapAn":["Chế độ công hữu về tư liệu sản xuất chủ yếu","Chế độ tư hữu về tư liệu sản xuất chủ yếu","Chế độ công hữu và tư hữu về tư liệu sản xuất chủ yếu","Chế độ công hữu về tư liệu sản xuất không chủ yếu"],"dung":"A"},{"id":139,"chuong":3,"cauHoi":"Mục tiêu về chế độ chính trị trong xây dựng chủ nghĩa xã hội ở Việt Nam theo Hồ Chí Minh là gì?","dapAn":["Phải xây dựng được chế độ dân chủ","Phải xây dựng được Mặt trên dân chủ","Phải xây dựng được nền văn hóa dân chủ","Phải xây dựng được hệ thống chính trị dân chủ"],"dung":"A"},{"id":140,"chuong":3,"cauHoi":"Khi khái quát về mục tiêu kinh tế của chủ nghĩa xã hội ở Việt Nam, Hồ Chí Minh xác định phải là:","dapAn":["Có nền kinh tế phát triển cao dựa trên lực lượng sản xuất và quan hệ sản xuất tiến bộ, khoa học kỹ thuật hiện đại","Có nền kinh tế phát triển cao với công nghiệp và nông nghiệp hiện đại, khoa học kỹ thuật tiên tiến","Có nên kinh tế phát triển gắn với việc thực hiện đầy đủ quyền làm chủ của nhân dân","Có nền kinh tế hiện đại với chế độ công hữu về tư liệu sản xuất tiên tiến"],"dung":"B"},{"id":141,"chuong":3,"cauHoi":"Trong hoàn cảnh một nước thuộc địa, Hồ Chí Minh khẳng định mục tiêu hàng đầu của cuộc cách mạng giải phóng dân tộc là gì?","dapAn":["Đấu tranh giải phóng giai cấp, giải phóng dân tộc, thành lập nhà nước dân tộc độc lập","Đấu tranh chống chủ nghĩa thực dân, giành độc lập dân tộc, thành lập nhà nước dân tộc độc lập","Đấu tranh chống lại các thế lực thù địch, giành quyền tự quyết cho dân tộc, thành lập nhà nước dân tộc độc lập","Đấu tranh, lên án chế độ khai thác thuộc địa của chế độ thực dân, đòi quyền dân chủ cho nhân An Nam"],"dung":"B"},{"id":142,"chuong":3,"cauHoi":"Hồ Chí Minh đặc biệt quan tâm đến vấn đề độc lập dân tộc ở các nước thuộc địa, vì độc lập, tự do có giá trị như thế nào?","dapAn":["Là quyền thiêng liêng, bất khả xâm phạm của tất cả các dân tộc","Là quyền tự quyết dân tộc, bất khả xâm phạm của tất cả các dân tộc","Là quyền bình đẳng dân tộc, bất khả xâm phạm của tất cả các dân tộc","Là quyền liên hiệp dân tộc, bất khả xâm phạm của tất cả các dân tộc"],"dung":"A"},{"id":143,"chuong":3,"cauHoi":"Hồ Chí Minh đã thể hiện khát vọng lớn lao nào trong quá trình tìm con đường cứu nước, giải phóng dân tộc?","dapAn":["Hạnh phúc cho đồng bào, cơm no áo ấm cho nhân dân","Quyền tự quyết cho dân tộc","Tự do cho đồng bào, độc lập cho Tổ quốc","Quyền bình đẳng dân tộc, dân chủ cho nhân dân"],"dung":"C"},{"id":144,"chuong":3,"cauHoi":"Hồ Chí Minh đã vận dụng sáng tạo con đường cách mạng vô sản ở châu Âu vào điều kiện cách mạng của Việt Nam như thế nào?","dapAn":["Đó là người đặt nhiệm vụ giải phóng giai cấp lên trên hết, trước hết","Đó là người đặt nhiệm vụ giành ruộng đất cho người cày lên trên hết","Đó là người đặt nhiệm vụ đánh đổ phong kiến lên trên hết","Đó là Người đặt nhiệm vụ giải phóng dân tộc lên trên hết, trước hết"],"dung":"D"},{"id":145,"chuong":3,"cauHoi":"Trong các luận điểm sau, luận điểm nào là của Hồ Chí Minh phân tích về cách mạng giải phóng dân tộc?","dapAn":["\"Sự đoàn kết giữa lực lượng các nước xã hội chủ nghĩa và sự đoàn kết nhất trí giữa các đảng cộng sản và công nhân tất cả các nước có ý nghĩa quan trọng bậc nhât'33","\"Phàm làm việc gì cũng vậy, bất kỳ lớn bé, khó dễ, nếu không ra sức thì chắc không thành công.... việc giải phóng gông cùm nô lệ cho đồng bào, cho nhân loại\"34","Phải \"cụ thế hóa chủ nghĩa Mác-Lênin cho thích hợp với điều kiện hoàn cảnh từng lúc và từng nơi\"35","\"Muốn được dân yêu, muốn được lòng dân, trước hết phải yêu dân, phải đặt quyền lợi của dân trên hết thảy, phải có một tinh thần chí công vô tư 36"],"dung":"B"},{"id":146,"chuong":3,"cauHoi":"Cách mạng giải phóng dân tộc cần chủ động, sáng tạo, có khả năng giành thắng lợi trước cách mạng vô sản ở chính quốc được Hồ Chí Minh khẳng định dựa trên cơ sở nào?","dapAn":["Thuộc địa là nơi cung cấp nguồn nhựa sống duy nhất cho chủ nghĩa để quốc","Người dân thuộc địa có sức sống mãnh liệt, có thể giành chiến thắng trước bất cứ kẻ thù xâm lược nào","Thuộc địa là nơi duy trì sự tồn tại, phát triển của chủ nghĩa đế quốc; tinh thần đấu tranh quyết liệt của các dân tộc thuộc địa","Quốc tế cộng sản đánh giá cao vai trò của các nước thuộc địa trong cuộc đấu tranh tự giải phóng"],"dung":"C"},{"id":147,"chuong":3,"cauHoi":"Khi cách mạng tháng Tám (1945) thành công, để bảo vệ nền độc lập thực sự mới giành được, Hồ Chí Minh đã ký với đại diện Chính phủ Pháp Hiệp định sơ bộ ngày 6/3/1946 nhằm khẳng định nội dung gì?","dapAn":["Chính phủ Pháp công nhận Việt Nam là một quốc gia độc lập, tự chủ, có Đảng riêng, pháp luật riêng","Chính phủ Pháp công nhận Việt Nam là một quốc gia tự do, có Chính phủ, có quân đội, có tài chính...","Chính phủ Pháp công nhận Việt Nam bình đăng với Pháp trong quan hệ ngoại giao, quan hệ kinh tế, chính trị","Chính phủ Pháp công nhận Việt Nam là cường quốc, có vị trí, vai trò to lớn trong quan hệ quốc tế"],"dung":"B"},{"id":148,"chuong":3,"cauHoi":"Giành được độc lập, tự do cho dân tộc Hồ Chí Minh tiếp tục khẳng định phương hướng phát triển của dân tộc trong bối cảnh thời đại mới là gì?","dapAn":["Quá độ đi lên chủ nghĩa xã hội","Tiến lên thực hiện công nghiệp hóa, hiện đại hóa đất nước","Tiến lên chủ nghĩa cộng sản từ một nước tư bản phát triển cao","Tến liên chủ nghĩa xã hội, chủ nghĩa cộng sản"],"dung":"D"},{"id":149,"chuong":3,"cauHoi":"Trong bối cảnh hiện nay, chúng ta cần phải làm gì để bảo vệ chủ quyền dân tộc như Hồ Chí Minh mong đợi?","dapAn":["Phát triển đất nước một cách hài hòa và bền vững","Tận dụng tối đa sự ủng hộ, giúp đỡ từ bên ngoài","Phát huy sức mạnh của đại đoàn kết dân tộc, của cả hệ thống chính trị, trong đó thế hệ trẻ là lực lượng nòng cốt","Phát huy tối đa sức mạnh của đoàn kết quốc tế, nhất là đoàn kết với các nước có chung mục tiêu tiến lên chủ nghĩa xã hội"],"dung":"C"},{"id":150,"chuong":3,"cauHoi":"Vấn đề dân tộc trong tư tưởng Hồ Chí Minh là sự kết hợp nhuần nhuyễn vấn đề gì?","dapAn":["Đối nội với vấn đề đối ngoại","Độc lập dân tộc với chủ nghĩa xã hội","Lợi ích dân tộc với vẫn đề lợi ích quốc tế","Vấn đề tăng trưởng kinh tế với vấn đề bảo vệ môi trường"],"dung":"B"},{"id":151,"chuong":3,"cauHoi":"Theo Hồ Chí Minh, chú nghĩa xã hội, chủ nghĩa cộng sản là chế độ xã hội như thế nào?","dapAn":["Không còn nghèo khổ, nạn đói, nạn dốt, xã hội do nhân dân làm chủ","Không còn áp bức, bóc lột, xã hội do nhân dân lao động làm chủ","Không còn chiến tranh, hòa bình, phát triển, xã hội do nhân dân làm chủ","Không còn áp bức, bọc lột, có quan hệ hữu nghị với các nước trên thế giới"],"dung":"B"},{"id":152,"chuong":3,"cauHoi":"Tiến lên chủ nghĩa xã hội, rồi đến chủ nghĩa cộng sản là mục đích của cách mạng Việt Nam, vì vậy, theo Hồ Chí Minh hai giai đoạn này giống nhau ở điểm gì?","dapAn":["Sức sản xuất đã phát triển cao; nền tảng kinh tế thì tư liệu sản xuất đều là của chung; không có giai cấp áp bức bóc lột","Sức sản xuất đều phát triển; nền tảng kinh tế phát triển cân đối và hiện đại","Chủ nghĩa xã hội vẫn còn vết tích xã hội cũ; xã hội cộng sản thì hoàn toàn không còn sự áp bức bóc lột","Xã hội chủ nghĩa là công bằng, bình đăng, mọi ngời được sống ẩm no, tự do, hạnh phúc"],"dung":"A"},{"id":153,"chuong":3,"cauHoi":"Hồ Chí Minh nhận định, tiến lên chủ nghĩa xã hội là một quá trình tất yếu, tuân theo những quy luật khách quan, trước hết là:","dapAn":["Những quy luật trong phát triển xã hội","Những quy luật của đời sống xã hội","Những quy luật trong phát triển kinh tế","Những quy luật trong sản xuất vật chất"],"dung":"D"},{"id":154,"chuong":3,"cauHoi":"Hồ Chí Minh cho rằng: Chỉ có CNXH mới \"chú ý xem xét những lợi ích cá nhân đúng đắn và bảo đảm cho nó được thỏa mãn\"37 và chỉ có trong xã hội chủ nghĩa thì mỗi người dân mới có điều kiện làm gì?","dapAn":["Nâng cao chất lượng sống, phát huy các sở trường của riêng mình","Cải thiện đời sống, phát huy tính cách riêng và sở trường riêng của mình","Thực hiện đời sống mới, lốpi sống mới hạnh phúc, ấm no, tự do phát triển theo sở trường của riêng mình","Hoàn thành tốt vai trò của mình trong môi trường xã hội, phát huy năng lực và trách nhiệm của bản thân"],"dung":"B"},{"id":155,"chuong":3,"cauHoi":"Theo Hồ Chí Minh, CNXH đảm bảo tính công bằng và hợp lý, ai cũng được hưởng thành quả lao động của mình trên nguyên tắc nào?","dapAn":["Làm theo năng lực, hưởng theo nhu cầu, không làm thì không hưởng","Làm theo trách nhiệm, năng lực của mỗi bản thân, không ngừng sáng tạo trong công việc","Làm nhiều thì hưởng nhiều, làm ít thì hưởng ít, không làm thì không hưởng","Làm nhiều thì hưởng nhiều, làm ít cũng hưởng nhiều, không làm cũng hưởng"],"dung":"C"},{"id":156,"chuong":3,"cauHoi":"Theo Hồ Chí Minh, cách mạng giải phóng dân tộc ở các nước cần được tiến hành như thế nào?","dapAn":["Chủ động, sáng tạo, có khả năng giành thắng lợi trước cách mạng vô sản ở chính quôc","Thụ động, ỷ lại, không có khả năng giành thắng lợi trước cách mạng vô sản ở chính quốc","Trông chờ vào thắng lợi cách mạng vô sản ở các nước chính quốc sẽ trả lại độc lập cho các nước thuộc địa","Thỏa hiệp, cải lương và mong chờ vào sự thắng lợi của cách mạng vô sản ở chính quốc sẽ giúp cách mạng vô sản ở thuộc địa giành thắng lợi"],"dung":"A"},{"id":157,"chuong":3,"cauHoi":"Vì sao trong đấu tranh giải phóng dân tộc, Hồ Chí Minh lại chỉ bàn đến vấn đề dân tộc ở các nước thuộc địa?","dapAn":["Vì ở các nước thuộc địa đều có quyền tự quyết dân tộc, quyền bình đẳng, tự do và hạnh phúc","Vì ở các nước thuộc địa phong trào đấu tranh giải phóng dân tộc diễn ra mạnh mẽ và từng bước giành được thắng lợi","Vì ở các nước thuộc địa đều bị mất quyền tự quyết dân tộc trên tất cả các lĩnh vực của đời sống","Vì phong trào giải phóng dân tộc ở các nước thuộc địa chịu sự ảnh hưởng, chi phối của phong trào cách mạng vô sản ở chính quốc"],"dung":"C"},{"id":158,"chuong":3,"cauHoi":"Theo Hồ Chí Minh, vấn đề độc lập dân tộc được hiểu như thế nào trong lịch sử dựng nước và giữ nước của dân tộc?","dapAn":["Là quyền tất nhiên, bất biến tất cả các dân tộc","Là quyền thiêng liêng, bất khả xâm phạm của tất cả các dân tộc","Là quyền tiên quyết, bất khả chiến bại của tất cả các dân tộc","Là quyền tự chủ, bất khả xâm lược của tất cả các dân tộc"],"dung":"B"},{"id":159,"chuong":3,"cauHoi":"Tiếp nối truyền thống của dân tộc, điều mà Hồ Chí Minh mong muốn nhất trên đời đối với dân tộc ta khi ở dưới chế độ thực dân, phong kiến là gì?","dapAn":["Mọi người dân được tự do, hạnh phúc","Nhân dân thoát khỏi ách áp bức bóc lột của chủ nghĩa thực dân","Đồng bào được tự do, Tổ quốc được độc lập","Đồng bào ai cũng có cơm ăn áo mặc, được học hành"],"dung":"C"},{"id":160,"chuong":3,"cauHoi":"Độc lập dân tộc là mục tiêu chiến đấu, là khát vọng của các dân tộc; tuy nhiên, theo Hồ Chí Minh, độc lập dân tộc trước hết phải gắn với điều gì?","dapAn":["Hạnh phúc, bình đăng và bảo đảm quyền lợi cho nhân dân","Tự do, hội họp, ngôn luận và đoàn kết dân tộc","Tự do, cơm no, áo ấm và hạnh phúc của nhân dân","Bình đẳng, cơm no, áo ấm và hòa bình cho nhân dân"],"dung":"C"},{"id":161,"chuong":3,"cauHoi":"Để vận dụng học thuyết về cách mạng vô sản của chủ nghĩa Mác - Lênin vào điều kiện của Việt Nam, Hồ Chí Minh đã khẳng định con đường cách mạng vô sản Việt Nam phải là gì?","dapAn":["Giải phóng giai cấp - giải phóng con người - giải phóng xã hội - giải phóng dân tộc","Giải phóng dân tộc - giải phóng xã hội - giải phóng giai cấp - giải phóng con người","Giải phóng xã hội - giải phóng dân tộc - giải phóng giai cấp - giải phóng các tầng lớp lao động giai cấp tư sản","Giải phóng con người - giải phóng giai cấp - giải phóng dân tộc - giải phóng"],"dung":"B"},{"id":162,"chuong":3,"cauHoi":"Khi có tổ chức Đảng Cộng sản, Hồ Chí Minh đã khẳng định vai trò to lớn của Đảng đối với cách mạng giải phóng dân tộc là gì?","dapAn":["Sợi chỉ đỏ, dẫn dắt cách mạng đến thắng lợi cho dân tộc, liên hiệp với các dân tộc khác trên thế giới và vô sản giai cấp ở mọi nơi","Nhân tố thành công của các cuộc cách mạng điển hình của dân tộc, khăng định đoàn kết với các dân tộc khác trên thế giới","Tổ chức, tập hợp dân chúng, liên lạc với các dân tộc bị áp bức và vô sản giai cấp mọi nơi","Lựa chọn con đường, tập hợp dân chúng, lãnh đạo các cuộc cách mạng thắng lợi và đoàn kết với các dân tộc khác"],"dung":"C"},{"id":163,"chuong":3,"cauHoi":"Chọn câu trở lời đúng theo tư tưởng Hồ Chí Minh về cách mạng giải phóng dân tộc: Lực lượng giải phóng dân tộc bao gồm:","dapAn":["Công nhân, nông dân","Nông dân, trí thức và tiểu tư sản dân tộc","Toàn dân tộc, lấy liên minh công - nông làm nền tảng","Các lực lượng tiến bộ"],"dung":"C"},{"id":164,"chuong":3,"cauHoi":"Khi xác định lực lượng cách mạng là toàn dân, Hồ Chí Minh lưu ý và nhắc không được quên lực lượng nào là gốc của cách mạng?","dapAn":["Nông dân, doanh nhân","Công nhân, nông dân","Công nhân, doanh nhân","Công nhân, địa chủ phong kiến"],"dung":"B"},{"id":165,"chuong":3,"cauHoi":"Mối quan hệ của cuộc cách mạng giải phóng dân tộc ở các nước thuộc địa với các nước chính quốc được Hồ Chí Minh khẳng định là gì?","dapAn":["Là mối quan hệ chính - phụ, nghĩa là cuộc cách mạng ở thuộc địa phải phụ thuộc vào cuộc cách mạng ở chính quốc","Là mối quan hệ khắng khít, tác động qua lại lẫn nhau, không lệ thuộc, phụ thuộc vào nhau","Là mối quan hệ không bình đẳng, không lệ thuộc vào nhau mà phải thực hiện lần lượt từng cuộc cách mạng một","Tất cả các đáp án"],"dung":"B"},{"id":166,"chuong":3,"cauHoi":"Là người nghiên cứu rất kỹ về chủ nghĩa đế quốc và hiểu sâu sắc về cách mạng ở các nước thuộc địa, Hồ Chí Minh đã đưa ra nhận định nào về vấn đề này?","dapAn":["Cách mạng ở chính quốc giành thắng lợi trước cách mạng ở thuộc địa","Cách mạng ở thuộc địa phải phụ thuộc vào cách mạng ở các nước chính quốc","Cách mạng ở thuộc địa có thể giành thắng lợi trước cách mạng ở các nước chính quốc","Cách mạng ở chính quốc và ở thuộc địa có mối quan hệ bất bình đẳng"],"dung":"C"},{"id":167,"chuong":3,"cauHoi":"Theo Hồ Chí Minh, tại sao cuộc cách mạng giải phóng dân tộc ở các nước thuộc địa phải được tiến hành bằng con đường bạo lực cách mạng?","dapAn":["Vì sử dụng bạo lực cách mạng để chống lại bạo lực phản cách mạng là giải pháp bắt buộc cuối cùng","Vì sử dụng bạo lực cách mạng để chống lại bạo lực phản cách mạng là giải pháp tình thế","Vì sử dụng bạo lực cách mạng để chống lại bạo lực phản cách mạng là giải pháp hiệu quả","Vì sử dụng bạo lực cách mạng để chống lại bạo lực phản cách mạng là giải pháp mang tính tạm thời"],"dung":"A"},{"id":168,"chuong":3,"cauHoi":"Bạo lực cách mạng trong cách mạng giải phóng dân tộc, theo Hồ Chí Minh có những hình thức nào?","dapAn":["Đấu tranh ngoại giao và đấu tranh chính trị","Đấu tranh chính trị và đấu tranh vũ trang","Đấu tranh vũ trang và đấu tranh tư tưởng văn hóa","Đấu tranh quân sự và đấu tranh kinh tế"],"dung":"B"},{"id":169,"chuong":3,"cauHoi":"Khi so sánh các chế độ đã tồn tại trong lịch sử để thấy sự khác nhau về bản chất giữa chủ nghĩa xã hội với chế độ khác, Hồ Chí Minh đã khẳng định điều gì?","dapAn":["Chế độ xã hội chủ nghĩa, cộng sản chủ nghĩa hướng đến một thế giới hòà bình, không có chiến tranh","Chế độ xã hội chủ nghĩa, cộng sản chủ nghĩa có nền kinh tế phát triển cao hơn hàng triệu lần kinh tế tư bản chủ nghĩa","Chế độ xã hội chủ nghĩa, cộng sản chủ nghĩa là chế độ do nhân dân lao động làm chủ","Chế độ xã hội chủ nghĩa, cộng sản chủ nghĩa trình độ dân trí của người dân cao hơn rất nhiều các chế độ chính trị khác"],"dung":"C"},{"id":170,"chuong":3,"cauHoi":"Xây dựng chủ nghĩa xã hội là sự nghiệp cách mạng toàn diện, Hồ Chí Minh xác định rõ trong mục tiêu về chế độ chính trị là gì?","dapAn":["Dân làm chủ và dân là chủ","Ôn định chính trị và phát huy quyền làm chủ của người dân","Phát huy vai trò làm chủ của giai cấp công nhân, nông dân","Đấu tranh giải phóng dận tộc, đem lại tự do cho người dân"],"dung":"A"},{"id":171,"chuong":3,"cauHoi":"Nét độc đáo trong tư duy của Hồ Chí Minh là bên cạnh việc chỉ ra các nguồn động lực phát triển của chủ nghĩa xã hội, Người còn lưu ý, cảnh báo điều gì?","dapAn":["Ngăn ngừa âm mưu diễn biến hòa bình, bạo loạn lật đố của các thế lực thù địch","Ngăn ngừa các yếu tố kìm hãm, triệt tiêu nguồn lực vốn có của chủ nghĩa xã hội","Ngăn ngừa suy thoái về đạo đức, lối sống, tự diễn biến, tự chuyển hóa trong cán bộ, đảng viên","Ngăn ngừa tham nhũng, lãng phí, quan liêu; bè phái, mất đoàn kết, chạy chức, chạy quyền"],"dung":"B"},{"id":172,"chuong":3,"cauHoi":"Do đặc điểm và tính chất quy định, quá độ lên chủ nghĩa xã hội là một quá trình khó khăn, phức tạp hơn cả việc đánh giặc38, Hồ Chí Minh đã xác định phương châm thực hiện bước đi như thế nào?","dapAn":["Phát triển nhanh về kinh tế, văn hóa để nâng cao đời sống vật chất và tinh thần của nhân dân","Tiến nhanh, tiến mạnh, từ thấp đến cao, phải luôn dựa vào điều kiện khách quan thế giới để đề ra mục tiêu xây dựng chủ nghĩa xã hội","Dần dần, thận trọng từng bước một, từ thấp đến cao, không chủ quan nôn nóng và phải luôn căn cứ vào điều kiện khách quan quy định","Tiến nhanh, tiến mạnh, tiến vững chắc lên chủ nghĩa xã hội"],"dung":"C"},{"id":173,"chuong":3,"cauHoi":"Thực hiện khát vọng Hồ Chí Minh xây dựng nước Việt Nam hùng cường, sánh vai với cường quốc năm châu, Đại hội XIII (2021) của Đảng xác định khát vọng Việt Nam đến năm 2045 như thế nào?","dapAn":["Là nước đang phát triên, có công nghiệp theo hướng hiện đại, vượt qua mức thu nhập trung bình thấp","Là nước đang phát triển, có công nghiệp hiện đại, thu nhập trung bình cao","Trở thành nước phát triển, có thu nhập cao","Cơ bản trở thành nước công nghiệp theo hướng hiện đại, có thu nhập cao"],"dung":"C"},{"id":174,"chuong":3,"cauHoi":"Trong quan niệm của Hồ Chí Minh, chủ nghĩa xã hội được tiếp cận ở các góc độ như thế nào?","dapAn":["Ở nhiều góc độ khác nhau bằng cách chỉ ra nhân tố đặc trưng trên các lĩnh vực chính trị","Ở nhiều góc độ khác nhau bằng cách chỉ ra đặc trưng trên các lĩnh vực kinh tế, chính trị, văn hóa, khoa học kỹ thuật...","Ở nhiều góc độc khác nhau bằng cách chỉ ra đặc trưng trên lĩnh vực kinh tế","Ở nhiều góc độc khác nhau bằng cách chỉ ra đặc trưng trên lĩnh vực văn hóa, xã hội"],"dung":"B"},{"id":175,"chuong":3,"cauHoi":"Hồ Chí Minh khẳng định: \"Nói một cách tóm tắt, mộc mạc, chủ nghĩa xã hội trước hết nhằm (...), được ẩm no và sống một đời hạnh phúc\", là làm sao cho dân giàu, nước mạnh\". Xác định nội dung còn thiếu?","dapAn":["Làm cho nhân dân lao động thoát nạn bần cùng, làm cho mọi người có công ăn việc làm","Làm cho mọi người có cuộc sống hạnh phúc, vui tươi","Làm cho nhân dân lao động không còn áp bức bóc lột, cuộc sống hạnh phúc","Làm cho các giai tầng trong xã hội thoát khỏi nạn bần cồng, đời sống vui tươi, hạnh phúc"],"dung":"A"},{"id":176,"chuong":3,"cauHoi":"Theo Hồ Chí Minh, trong chế độ xã hội chủ nghĩa nhân dân làm chủ, lợi ích cá nhân gắn liền với lợi ích của chế độ, do đó chủ thể xây dựng chủ nghĩa xã hội là:","dapAn":["Công nhân, là lực lượng tiên quyết trong xây dựng và phát triển xã hội","Nông dân, là lực lượng tiên phong, đi đầu trong cách mạng xã hội chủ nghĩa","Các tầng lớp, là lực lượng tiên quyết đối với việc xây dựng và phát triển xã hội","Nhân dân, là lực lượng quyết định tốc độ xây dựng và phát triển xã hội"],"dung":"D"},{"id":177,"chuong":3,"cauHoi":"Trong các luận điểm sau, luận điểm nào Hồ Chí Minh nói về mục tiêu kinh tế gắn bó mật thiết với mục tiêu về chính trị?","dapAn":["Nền kinh tế phát triển cao \"với công nghiệp và nông nghiệp hiện đại, khoa học kỹ thuật tiên tiến*40","\"Một nền kinh tế thuần nhất, dựa trên chế độ sở hữu toàn dân và sở hữu tập thể\"41","\"Chế độ kinh tế và xã hội của chúng ta nhằm thực hiện đầy đủ quyền dân chủ của nhân dân, trên cơ sở kinh tế xã hội chủ nghĩa ngày càng phát triển\"42","Chỉ có chủ nghĩa xã hội mới là nguồn gốc của tự đo, bình đẳng, bác ái, xóa bò những bức tường dài ngăn cản con người yêu đoàn kết, yêu thương nhau43"],"dung":"C"},{"id":178,"chuong":3,"cauHoi":"Hồ Chí Minh từng nói: \"Muốn tiến lên chủ nghĩa xã hội phải phát triển (...) và văn hóa. Vì sao không nói phát triển (...) và kinh tế. Tục ngữ ta có câu: có thực mới vực được đạo, vì thế kinh tế phải đi trước\"44. Xác định cụm từ còn thiếu?","dapAn":["Chính trị/ quân sự","Văn hóa/ khoa học","Kinh tế/ văn hóa","Ngoại giao/ văn hóa"],"dung":"C"},{"id":179,"chuong":3,"cauHoi":"Luận điểm của Hồ Chí Minh: \"Để phục vụ sự nghiệp cách mạng xã hội chủ nghĩa thì văn hóa... phải triệt để tẩy trừ (...) và ảnh hưởng nô dịch của văn hóa để quốC. Đồng thời, phát triển (...) và hấp thụ những cái mới của văn hóa tiến bộ thế giới\"45. Xác định cụm từ còn thiếu?","dapAn":["Mọi phong tục lạc hậu/ những truyền thống tốt đẹp của văn hóa dân tộc","Mọi di tích thuộc địa/ những truyền thống tốt đẹp của văn hóa dân tộc","Mọi tàn tích của chiến tranh/ những truyền thống tốt đẹp của văn hóa dân tộc","Mọi định kiến của xã hội/ những truyền thống tốt đẹp của văn hóa dân tộc"],"dung":"B"},{"id":180,"chuong":3,"cauHoi":"Mục tiêu về các mối quan hệ xã hội trong chế độ xã hội chủ nghĩa, theo Hồ Chí Minh phải đảm bảo điều gì?","dapAn":["Dân chủ, bình đắng, lợi ích","Dân chủ, công bằng, văn minh","Văn minh, tiên tiến, hiện đại","Dân chủ, bình đẳng, nhu cầu, nguyện vọng"],"dung":"B"},{"id":181,"chuong":3,"cauHoi":"Theo Hồ Chí Minh, tất cả các động lực đều rất quan trọng và có mối quan hệ biện chứng với nhau nhưng giữ vai trò quyết định nhất là:","dapAn":["Là ngoại lực của dân tộc, là nhân dân lao động","Là vật chất và tinh thần, là giai cấp công nhân","Là nội lực của dân tộc, là nhân dân","Là mổi quan hệ đổi nội và đối ngoại của dân tộc, là lực lao động"],"dung":"C"},{"id":182,"chuong":3,"cauHoi":"Để thúc thẩy quá trình xây dựng CNXH, theo Hồ Chí Minh những động lực hàng đầu phải đảm bảo là gì?","dapAn":["Quyền lợi và nghĩa vụ của dân, đoàn kết toàn dân","Lợi ích của dân, dân chủ của dân, sức mạnh đoàn kết toàn dân","Nguồn thu nhập của dân, dân chủ của dân và đoàn kết các giai tầng trong xã","Quyền lực và quyền lợi của dân, thực hành dân chủ của dân và đoàn kết nhân hội dân"],"dung":"B"},{"id":183,"chuong":3,"cauHoi":"Hồ Chí Minh luôn quan tâm đến lợi ích của cộng đồng và lợi ích của những con người cụ thể trong xây dựng chủ nghĩa xã hội. Do đó, Người dạy; \"việc gì (...)cho dân phải hết sức làm, việc gì (...) cho dân phải hết sức tránh\", \"phải đặt (...) của dân lên trên hết 46. Xác định cụm từ còn thiếu?","dapAn":["Có ích/ có hại/ quyền lợi","Có lợi/ có hại/quyền lợi","Có niềm vui/ có nỗi buồn/ quyền lợi","Có hạnh phúc/ có niềm vui/ quyền lợi"],"dung":"B"},{"id":184,"chuong":3,"cauHoi":"Dân chủ trong chủ nghĩa xã hội là dân chủ của nhân dân, là của quý báu nhất của nhân dân*. Vậy, theo Hồ Chí Minh có dân chủ thì mới đảm bảo điều gì?","dapAn":["Lợi ích vì dân","Lợi ích vì tập thể","Lợi ích vì nông dân","Lợi ích vì từng cá nhân"],"dung":"A"},{"id":185,"chuong":3,"cauHoi":"Chọn phương án trả lời đúng nhất với tư tưởng Hồ Chí Minh: Muốn xây dựng chủ nghĩa xã hội, trước hết cần có:","dapAn":["Con người có đạo đức","Con người xã hội chủ nghĩa","Con người có tài năng","Con người có tính sáng tạo, dám nghĩ, dám làm"],"dung":"B"},{"id":186,"chuong":3,"cauHoi":"Cùng với việc xác định và định hướng phát huy sức mạnh của những động lực xây dựng CNXH, Hồ Chí Minh luôn nhắc nhở phải ngăn chặn điều gì?","dapAn":["Những tư tưởng, tác phong xấu là: Bài xích cá nhân; hủ hóa, tư túng, kiêu ngạo cộng san","Những tư tưởng, tác phong xấu là: Chủ nghĩa vị kỷ, nuôi dưỡng tính hám lợi, hiếu danh, ích kỷ, hẹp hòi; hành vi vụ lợi","Những tư tưởng, tác phong xấu là: Không quan tâm đến lợi ích chung của tập thể; dễ sa ngã vào chủ nghĩa cá nhân","Những tư tưởng, tác phong xấu là: Chủ nghĩa cá nhân; quan liêu, mệnh lệnh; tham ô, lãng phí; bảo thủ.."],"dung":"D"},{"id":187,"chuong":3,"cauHoi":"Theo Hồ Chí Minh, tính chất của thời kỳ quá độ lên chủ nghĩa xã hội ở Việt Nam là gì?","dapAn":["Là thời kỳ có nhiều biến động sâu sắc nhưng vượt qua một cách lâu dài, khó khăn, phúc tạp","Là thời kỳ có nhiều thách thức nhất nhưng thay đổi triệt để những nếp sống, thói quen cũ","Là thời kỳ cải biến sâu sắc nhất nhưng phức tạp, lâu dài, khó khăn, gian khổ","Là thời kỳ xóa bỏ giai cấp bóc lột nhưng khó khăn, phức tạp phải vượt lên trước"],"dung":"C"},{"id":188,"chuong":3,"cauHoi":"Kiên định mục tiêu và con đường cách mạng mà Hồ Chí Minh đã lựa chọn, Đảng Cộng cộng sản Việt Nam đã rút ra những bài học đầu tiên là gì?","dapAn":["Nêu rõ phương châm dương cao ngọn cờ hòa bình trong công lý","Nắm vững ngọn cờ độc lập dân tộc và chủ nghĩa xã hội","Làm cho mọi người dân hạnh phúc","Xây dựng một nước Việt Nam hòa bình, thống nhất, độc lập, giàu mạnh"],"dung":"B"},{"id":189,"chuong":3,"cauHoi":"Để vận dụng tư tưởng Hồ Chí Minh vào phát huy sức mạnh dân chủ xã hội chủ nghĩa là phát huy sức mạnh bản chất ưu việt của chế độ xã hội xã hội chủ nghĩa trong bối cảnh hiện nay theo phương châm nào?","dapAn":["Dân biết, dân bàn, dân làm, dân tham mưu","Đoàn kết, dân chủ, kỷ cương, sáng tạo, phát triển","Dân biết, dân bàn, dân làm, dân kiêm tra, dân giám sát, dân hưởng thụ","Dân giám sát, dân thụ hưởng, dân phản biện"],"dung":"C"},{"id":190,"chuong":3,"cauHoi":"Củng cố, kiện toàn, phát huy sức mạnh và hiệu quả hoạt động của toàn bộ hệ thống chính trị theo tư tưởng Hồ Chí Minh cần phải như thế nào?","dapAn":["Nhất nguyên về chính trị, về tổ chức, về tư tưởng và thốngnhất dưới sự lãnh đạo của Nhà nước, thống nhất về mục tiêu kinh tế","Nhất nguyên về chính trị, về tổ chức, về tự tưởng và thống nhất dưới sự lãnh đạo của Đảng Cộng sản Việt Nam, thống nhất về mục tiêu chính trị","Nhất nguyên về chính trị, về tổ chức, về tư tưởng và thốngnhất dưới sự lãnh đạo của Mặt trận tổ quốc, thống nhất về mục tiêu xã hội","Tất cả các đáp án"],"dung":"B"},{"id":191,"chuong":3,"cauHoi":"Vận dụng tư tưởng Hồ Chí Minh về độc lập dân dân tộc và chủ nghĩa xã hội trong giai hiện nay cần phải thực hiện những vấn đề gì?","dapAn":["Có hiệu quả những chính sách của Đảng, trong đó các chính sách về công tác xây dựng bộ máy chính quyền giữ vị trí quan trọng...","Có hiệu quả những điều lệ của Đảng, trong đó các điều lệ về những điều đảng viên không được làm có vai trò quan trọng đối với đội ngũ cán bộ đảng viên","Có hiệu quả những chỉ thị của Đảng, trong đó các chỉ thị về cây dựng đảng vai trò quan trọng ...•","Có hiệu quả những nghị quyết của Đảng, trong đó các nghị quyết về xây dựng Đảng giữ vị trí cực kỳ quan trọng vì xây dựng Đảng là nhiệm vụ then chốt trong sự nghiệp đổi mới"],"dung":"D"},{"id":192,"chuong":4,"cauHoi":"Luận điểm: \"Đảng muốn vững thì phải có chủ nghĩa làm cốt, trong đảng ai cũng phải hiểu, ai cũng phải theo chủ nghĩa ấy\"48, được Hồ Chí Minh khẳng định trong tác phẩm nào?","dapAn":["Bản án chế độ thực dân Pháp (năm 1925)","Đường cách mệnh (năm 1927)","Chính cương vắn tắc của Đảng (năm 1930)","Thường thức chính trị (năm 1953)"],"dung":"B"},{"id":193,"chuong":4,"cauHoi":"Khi xây dựng một đảng văn minh, chân chính theo Hồ Chí Minh cần phải có những nội dung gì?","dapAn":["Tiêu biểu cho lương tâm, trí tuệ và danh dự của dân tộc","Tất yếu, phù hợp với quy luật phát triển văn minh tiến bộ của dân tộc","Lãnh đạo giành độc lập cho Tổ quốc và đưa lại tự do, ấm no, hạnh phúc cho nhân dân","Tất cả các đáp án"],"dung":"D"},{"id":194,"chuong":4,"cauHoi":"Để hoạt động của Đảng Cộng sản Việt Nam luôn trong sạch, vững mạnh, Hồ Chí Minh đã yêu cầu phải xây dựng như thế nào?","dapAn":["Đảng là đạo đức, là văn minh","Những vấn đề nguyên tắc trong hoạt động của Đảng","Xây dựng đội ngũ cán bộ, đảng viên","Tất cả các đáp án"],"dung":"D"},{"id":195,"chuong":4,"cauHoi":"Hồ Chí Minh coi đạo đức cách mạng là gốc, là nền tảng của người cách mạng, theo đó đạo đức của Đảng được Người khắng định trên những quan điểm nào sau đây?","dapAn":["Mục đích hoạt động của đảng là lãnh đạo đấu tranh giải phóng dân tộc, giải phóng xã hội, giải phóng giai cấp, giải phóng con người","Cương lĩnh, đường lối, chủ trương và mọi hoạt động thực tiễn của Đảng đều phải nhằm mục đích giải phóng dân tộc, xã hội, giai cấp, con người","Đội ngũ đảng viên phải luôn thấm nhuần đạo đức cách mạng, ra sức tu dưỡng, rèn luyện, suốt đời phấn đấu cho lợi ích của dân, của nước.","Tất cả các đáp án"],"dung":"D"},{"id":196,"chuong":4,"cauHoi":"Theo Hồ Chí Minh, những vấn đề có tính nguyên tắc trong hoạt động của Đảng Cộng sản Việt Nam là gì?","dapAn":["Lấy chủ nghĩa Mác - Lênin làm nền tảng và kim chỉ nam cho hành động;","Tập trung dân chủ; tự phê bình và phê bình; kỷ luật nghiêm minh, tự giác; dân; Đoàn kết quốc tế","Thường xuyên tự chỉnh đồn; Đoàn kết, thống nhất; Liên hệ mật thiết với nhân","Tất cả các đáp án"],"dung":"D"},{"id":197,"chuong":4,"cauHoi":"Năm 1930, trong bản Chánh cương vắn tắt Hồ Chí Minh nêu lên mô hình nhà nước gì?","dapAn":["Dựng ra chính phủ dân chủ nhân dân","Dựng ra chính phú dân chủ xã hội chủ nghĩa","Dựng ra chính phủ đoàn kết dân tộc","Dựng ra chính phủ công nông binh"],"dung":"D"},{"id":198,"chuong":4,"cauHoi":"Để xây dựng đội ngũ cán bộ, đảng viên vừa có đức, vừa có tài, trong sạch, vững mạnh trong Đảng, Hồ Chí Minh nêu lên yêu cầu nào sau đây?","dapAn":["Trung thành; thực hiện đúng đường lối và các nguyên tắc xây dựng Đảng;","Tư dưỡng, trau dồi đạo đức cách mạng; có mối liên hệ mật thiết với nhân dân;","Học tập nâng cao trình độ; năng động, sáng tạo: luôn phòng và chống tiêu cục","Tất cả các đáp án"],"dung":"D"},{"id":199,"chuong":4,"cauHoi":"Để thực hiện đoàn kết, thống nhất trong Đảng, trước tiên Hồ Chí Minh yêu cầu phải thực hiện ở cấp nào trước?","dapAn":["Thực hiện trong cấp ủy, trong những cán bộ lãnh đạo chủ chốt....","Thực hiện trong cấp chính quyền, trong những cán bộ lãnh đạo chủ chốt...","Thực hiện trong cấp cơ sở, trong đội ngũ cán bộ lãnh đạo cấp cơ sở...","Tất cả các đáp án"],"dung":"A"},{"id":200,"chuong":4,"cauHoi":"Nhà nước Việt Nam Dân chủ Cộng hòa theo quan điểm của Hồ Chí Minh được hiện thực hóa vào năm nào?","dapAn":["1930","1945","1954","1975"],"dung":"B"},{"id":201,"chuong":4,"cauHoi":"Ngày 3/9/1945, Hồ Chí Minh đã nêu lên sáu vấn đề cấp bách, trong đó vấn đề liên quan đến nhà nước được Người yêu cầu là gì?","dapAn":["Mở một chiến dịch giáo dục lại tinh thần nhân dân bằng cách thực hiện: CÀN, KIỆM, LIÊM, CHÍNH.","Mở một chiến dịch để chống nạn mù chữ","Chính phủ tố chức càng sớm càng hay cuộc Tổng tuyển cử với chế độ phổ thông đầu phiếu","Chính phủ ta tuyên bố: TÍN NGƯỠNG TỰ DO và Lương Giáo đoàn kết"],"dung":"C"},{"id":202,"chuong":4,"cauHoi":"Hồ Chí Minh đã trực tiếp làm Trưởng Ban chỉ đạo soạn thảo những bản Hiếp pháp nào sau đây?","dapAn":["Hiến pháp năm 1946, 1959","Hiến pháp năm 1946, 1980","Hiến pháp năm 1946, 1992","Hiến pháp năm 1946, 2013"],"dung":"A"},{"id":203,"chuong":4,"cauHoi":"Trong quá trình lãnh đạo xây dựng nhà nước, Hồ Chí Minh nhắc nhở mọi người phòng, chống những tiêu cực nào?","dapAn":["Đặc quyền, đặc lợi","Tham ô, lãng phí, quan liêu","Tư túng, chia rẽ, kiêu ngạo","Tất cả các đáp án"],"dung":"D"},{"id":204,"chuong":4,"cauHoi":"Hồ Chí Minh luôn chú trọng xây dựng hệ thống pháp luật dân chủ, hiện đại. Sự ra đời của hệ thống pháp luật thể hiện rõ sự nỗ lực của Hồ Chí Minh và Nhà nước Việt Nam trong công tác nào?","dapAn":["Hành pháp","Tư pháp","Lập pháp","Tất cả các đáp án"],"dung":"C"},{"id":205,"chuong":4,"cauHoi":"Trong quan điểm của mình về nhà nước, Hồ Chí Minh luôn giải quyết hài hòa, thống nhất giữa bản giai cấp công nhân với tính nhân dân và tính dân tộc ở những điểm nào?","dapAn":["Nhà nước ra đời là kết quả của cuộc đấu tranh lâu dài, gian khổ của rất nhiều thế hệ người Việt, của toàn thể dân tộc","Nhà nước ra đời đã xác định rõ và luôn kiên trì, nhất quán mục tiêu vì quyền lợi của nhân dân, lấy quyền lợi của dân tộc làm nền tảng","Trong thực tế, Nhà nước đã đảm đương nhiệm vụ mà toàn thể dân tộc giao phó là tổ chức nhân dân tiến hành các cuộc kháng chiến để bảo vệ nền độc lập, tự do của Tố quốc...","Tất cả các đáp án"],"dung":"D"},{"id":206,"chuong":4,"cauHoi":"Bản chất giai cấp công nhân của nhà nước trong quan điểm Hồ Chí Minh được thể hiện trên các phương diện nào?","dapAn":["Đảng Cộng sản Việt Nam giữ vị trí và vai trò cầm quyền","Tính định hướng lên chủ nghĩa xã hội trong sự phát triển đất nước","Nguyên tắc tổ chức và hoạt động là nguyên tắc tập trung dân chủ","Tất cả các đáp án"],"dung":"D"},{"id":207,"chuong":4,"cauHoi":"Biểu hiện tiêu cực nào trong hoạt động của Nhà nước được Hồ Chí Minh xem là \"giặc nội xâm\", \"giặc ở trong lòng\", thứ giặc nguy hiểm hơn giặc ngoại xâm là gì?","dapAn":["Tham ô, lãng phí, quan liêu","Đặc quyền, đặc lợi","Tư túng\", \"chia rễ\", \"kiêu ngạo\"","Tất cả đáp án"],"dung":"A"},{"id":208,"chuong":4,"cauHoi":"Theo Hồ Chí Minh, căn bệnh nào trong hoạt động của Nhà nước gây mất đoàn kết, gây rối cho công tác ?","dapAn":["Tham ô, lãng phí, quan liêu","Đặc quyền, đặc lợi","Tư túng\", \"chia rễ\", \"kiêu ngạo\"","Tất cả đáp án"],"dung":"C"},{"id":209,"chuong":4,"cauHoi":"Phòng, chống tiêu cực trong bộ mày nhà nước là nhiệm vụ hết sức khó khăn, Hồ Chí Minh đã lên những biện pháp cơ bản nào?","dapAn":["Nâng cao trình độ dân chủ trong xã hội và thực hành dân chủ rộng rãi, phát huy quyền làm chủ của nhân dân","Pháp luật của Nhà nước, kỷ luật của Đảng phải nghiêm minh; nghiêm khắc xử phạt đúng người đúng tội; cán bộ phải đi trước làm gương","Phải huy động sức mạnh của chủ nghĩa yêu nước vào cuộc chiến chống lại tiêu cực trong con người, trong xã hội và trong bộ máy Nhà nước","Tất cả các đáp án"],"dung":"D"},{"id":210,"chuong":4,"cauHoi":"Đảng Cộng sản Việt Nam ra đời là nhu cầu tất yếu của xã hội Việt Nam từ đầu năm 1930. Theo Hồ Chí Minh, Đảng đã được dân tộc trao cho sứ mệnh gì?","dapAn":["Lãnh đạo đất nước trong sự nghiệp giải phóng dân tộc và đi lên chủ nghĩa xã hội","Lãnh đạo nhân dân bị áp bức bóc lột ở ba nước Đông Dương trong sự nghiệp giải phóng dân tộc và đi lên chủ nghĩa xã hội","Lãnh đạo giai cấp vô sản trong nước và trên thế giới đánh đồ để quốc, thực dân giành quyền lực nhà nước về tay mình","Lãnh đạo giai cấp công nhân thực hiện sứ mệnh lịch sử là đánh đồ chủ nghĩa tư bản để tiến lên xây dựng chủ nghĩa xã hội"],"dung":"A"},{"id":211,"chuong":4,"cauHoi":"Trong Đảng, Cương lĩnh, đường lối và mọi hoạt động thực tiễn của Đảng theo Hồ Chí Minh đều phải nhằm mục đích gì?","dapAn":["Dân tộc độc lập, nhân dân Việt Nam và nhân dân Lào, Campuchia có cuộc sống ấm no, tự do, hạnh phúc thực sự","Dân tộc độc lập, nhân dân Việt Nam và nhân dân thế giới chung sống hòa bình, hợp tác và cùng phát triển","Dân tộc độc lập, nhân dân có cuộc sống ấm no, tự do, hạnh phúc thực sự, đoàn kết hữu nghị với các dân tộc khác trên thế giới","Dân tộc độc lập, nhân dân các nước trên thế giới thoát khỏi ách áp bức, bóc lột, bất công"],"dung":"C"},{"id":212,"chuong":4,"cauHoi":"Xây dựng một Đảng văn minh (một Đảng cách mạng chân chính), trong giai đoạn cầm quyền Hồ Chí Minh yêu cầu Đảng phải hoạt động trong khuôn khổ nào?","dapAn":["Hiến pháp và pháp luật của Nhà nước","Điều lệ, nghị quyết của Đảng","Điều lệ của Mặt trận Tổ quốc Việt Nam","Hiến Chương Liên hợp quốc"],"dung":"A"},{"id":213,"chuong":4,"cauHoi":"Hồ Chí Minh chỉ ra từ rất sớm và nêu rõ những tiêu cực của cán bộ, đảng viên, đồng thời nghiêm khắc nhắc nhỏ, \"chúng ta không sợ sai lầm, nhưng đã nhận biết sai lầm thì phải ra sức (...). Vậy nên, ai không phạm những lầm lỗi ... thì nên chú ý tránh đi, và găng sức cho (...)\"4). Xác định cụm từ còn thiếu?","dapAn":["Giúp đỡ/ thêm tiến bộ","Sửa chữa/ thêm tiến bộ","Bào chữa/ thêm tiến bộ","Cố gắng/ thêm tiền bộ"],"dung":"B"},{"id":214,"chuong":4,"cauHoi":"Năm 1969, bản Di chúc, Hồ Chí Minh viết: \"Mỗi dảng viên và cản bộ phải thật sự thấm nhuần (...), thật sự cần kiệm liêm chính, chí công vô tư. Phải giữ gìn Đảng ta (...), phải xứng đáng là (..), là người đầy tớ thật trung thành của nhân dân\". Xác định cụm từ còn thiếu?","dapAn":["Năng lực làm chủ của bản thân/ thật văn minh tiến bộ/ người lãnh đạo","Sự nghiệp cách mạng/ thật là tấm gương/ người lãnh đạo","Đạo đức cách mạng/ thật trong sạch/ người lãnh đạo","Bản chất cách mạng/ thật trong sáng/ người lãnh đạo"],"dung":"C"},{"id":215,"chuong":4,"cauHoi":"Nhà nước của nhân dân là nhà nước mà tất cả mọi quyền lực trong nhà nước và trong xã hội đều thuộc về nhân dân. Quan điểm này của Hồ Chí Minh được thể hiện trong bản Hiến pháp nào?","dapAn":["Hiến pháp năm 1946 và 1959","Hiến pháp năm 1959 và 1980","Hiến pháp năm 1980 và 1992","Hiến pháp năm 1992 và 2013"],"dung":"A"},{"id":216,"chuong":4,"cauHoi":"Trong tác phẩm Đường cách mệnh (1927), Hồ Chí Minh đã khẳng định: Cách mạng trước hết phải có đảng cách mệnh để trong thì vận động và tổ chức dân chúng, ngoài thì (...). Đảng có vững, cách mệnh mới thành công, cũng như người cầm lái có vững thuyền mới chạy\"S0. Xác đinh cụm từ còn thiếu?","dapAn":["Liên lạc với dân tộc bị áp bức và vô sản giai cấp ở mọi nơi","Đối ngoại với các nước trên thế giới và vô sản giai cấp ở mọi nơi","Hợp tác với các nước trong khu vực và vô sản giai cấp ở mọi nơi","Đa dạng hóa các với các dân tộc bị áp bức và vô sản giai cấp ở mọi nơi"],"dung":"A"},{"id":217,"chuong":4,"cauHoi":"Khi thực dân Pháp xâm lược, Việt Nam trở thành một nước nửa thuộc địa nửa phong kiến, mâu thuẫn cơ bản nào đã xảy ra mà Hồ Chí Minh gọi đó mâu thuẫn không thể điều hòa được?","dapAn":["Mâu thuẫn giữa giai cấp nông dân với địa chủ phong kiến","Mâu thuẫn giữa công nhân Việt Nam với giai cấp công tư sản","Mâu thuẫn giữa toàn thể nhân dân Việt Nam với các thế lực đế quốc và tay sai","Mâu thuẫn giữa toàn thể nhân dân Việt Nam với tư sản mại bản"],"dung":"C"},{"id":218,"chuong":4,"cauHoi":"Vai trò của Đảng Cộng sản Việt Nam được Hồ Chí Minh khẳng định như thế nào trong suốt quá trình lãnh đạo cách mạng Việt Nam?","dapAn":["\"Như người cầm lái\"; là một đặc thù, xuất phát từ yêu cầu phát triển của dân tộc","\"Như người cầm lái\"; là một tất yếu, xuất phát từ yêu cầu phát triển của dân tộc","\"Như người cầm lái\"; là một quy chuẩn, xuất phát từ yêu cầu phát triển của dân tộc","\"Như người cầm lái\"; là một kiểu mẫu, xuất phát từ yêu cầu phát triển của dân tộc"],"dung":"B"},{"id":219,"chuong":4,"cauHoi":"Đảng Cộng sản Việt Nam được Hồ Chí Minh sáng lập và rèn luyện là một đảng chính trị tồn tại và phát triển theo quan điểm của ai?","dapAn":["Của các nhà sáng lập Đảng kiểu mới ở trên thế giới","Của C.Mác - Ăngghen về đảng kiểu mới","Của V.I .Lênin về đảng kiểu mới của giai cấp vô sản","Của Quốc tế cộng sản về đảng kiểu mới"],"dung":"C"},{"id":220,"chuong":4,"cauHoi":"So với học thuyết Mác - Lênin, Hồ Chí Minh đã đưa thêm yếu tố thứ ba vào khẳng định sự ra đời của Đảng Cộng sản Việt Nam, đó là yếu tố nào?","dapAn":["Phong trào nông dân Chủ nghĩa Mác - Lênin","Phong trào yêu nước","Phong trào tư sản dân tộc Phong trào công nhân","Phong trào trí thức"],"dung":"B"},{"id":221,"chuong":4,"cauHoi":"Trong Đảng, Hồ Chí Minh nhấn mạnh mỗi đảng viên và cán bộ phải thật sự thấm nhuần điều gì?","dapAn":["Cương lĩnh của đảng, thật sự công bằng, chính trực, chí công vô tư","Những điều Đảng viên không được làm, thật sự trong sáng, giản dị","Đạo đức cách mạng, thật sự cần kiệm liêm chính, chí công vô tư","Đường lối, chủ trương của Đảng, thật sự giác ngộ lý tưởng cách mạng"],"dung":"C"},{"id":222,"chuong":4,"cauHoi":"Xây dựng Đảng trở thành một Đảng có đạo đức cách mạng, cũng tức la xây dựng Đảng trở thành một Đảng văn minh hay Hồ Chí Minh còn gọi đó là một đảng như thế nào?","dapAn":["Một đảng cách mạng chân chính","Một đảng cách mạng kiểu mới của giai cấp vô sản","Một đảng cách mạng thấm nhuần đạo đức cần kiệm liêm chính","Một đảng cách mạng lão thành"],"dung":"A"},{"id":223,"chuong":4,"cauHoi":"Theo Hồ Chí Minh, nguyên lý dân là chủ nhằm khẳng định địa vị chủ thể tối cao của mọi quyền lực thuộc về ai?","dapAn":["Nhà nước","Nông dân","Công dân","Nhân dân"],"dung":"D"},{"id":224,"chuong":4,"cauHoi":"Theo Hồ Chí Minh, Nhà nước Việt Nam là nhà nước dân chủ mang bản chất của giai cấp nào?","dapAn":["Giai cấp công nhân","Giai cấp nông dân","Giai cấp tư sản","Các tầng lớp khác trong xã hội"],"dung":"A"},{"id":225,"chuong":4,"cauHoi":"Đối với mỗi cán bộ, đảng viên phải tuyệt đối trung thành với Đảng, suốt đời phấn đấu cho lợi ích của Đảng, vì mục tiêu lý tưởng của Đảng. Hồ Chí Minh khẳng định những người đặt lợi ích của Đảng lên trên hết, trước hết, vì lợi ích của Đảng tức là lợi ích (...). Xác định cụm từ còn thiếu?","dapAn":["Của giai cấp, của đảng phái","Của dân tộc, của Tổ quốc","Của nhân dân, của đất nước","Của quốc gia, của dân tộc"],"dung":"B"},{"id":226,"chuong":4,"cauHoi":"Trong tác phẩm Sửa đổi lối làm việc, Hồ Chí Minh nêu lên 12 Điều về tư cách của một Đảng cách mạng chân chính, trong đó Người yêu cầu Đảng phải lựa chọn những người như thế nào?","dapAn":["Rất nhiệt huyết và năng động","Rất trung thành và rất hăng hải","Rất năng động và sáng tạo","Rất cẩn thận và dám chịu trách nhiệm"],"dung":"B"},{"id":227,"chuong":4,"cauHoi":"Hình thức dân chủ trực tiếp trong thực thi quyền lực của nhân dân theo Hồ Chí Minh hiểu như thế nào?","dapAn":["Nhân dân trực tiếp quyết định những vấn đề liên quan đến vận mệnh quốc gia, dân tộc và quyền lợi của dân chúng","Nhân dân trực tiếp quyết định những vấn đề liên quan đến quốc kế, dân sinh, hợp tác với các nướC.","Nhân dân trực tiếp quyết định những vấn đề liên quan đến đời sống vật chất và tinh thần của dân chúng.","Nhân dân trực tiếp quyết định những đề quyền lực Nhà nước thuộc về nhân dân, hợp tác với các nước, các tổ chức quốc tế."],"dung":"A"},{"id":228,"chuong":4,"cauHoi":"Ngay từ rất sớm, Hồ Chí Minh đã thấy rõ tầm quan trọng của Hiến pháp và pháp luật trong đời sống chính trị - xã hội. Do đó, trong bản Yêu sách của nhân dân An Nam (năm 1919), Hồ Chí Minh đã nêu lên yêu cầu gì?","dapAn":["Đổi mới cơ chế quản lý; thay thế chế độ ra các sắc lệnh bằng ra các đạo luật","Xây dựng bộ máy quản lý; thay đổi chế độ ra sắc lệnh bằng ra các đạo luật","Cải cách nền pháp lý; thay thế chế độ ra các sắc lệnh bằng chế độ ra các đạo luật ở Đông Dương","Xóa bỏ các tòa án đặc biệt; thay thế chế độ cai trị bằng chế độ nhân quyền"],"dung":"C"},{"id":229,"chuong":4,"cauHoi":"\"Nước ta là nước dân chủ, nghĩa là nước nhà do nhân dân làm chủ\"5l, theo Hồ Chí Minh, dân làm chủ nhấn mạnh vấn đề gì?","dapAn":["Quyền lợi và nghĩa vụ của nhân dân với tư cách là người chủ","Quyền kiểm tra và giám sát của nhân dân đối với Đảng và nhà nước","Năng lực và trách nhiệm của nhân dân với tư cách là người giám sát hoạt động của bộ máy nhà nước","Vai trò và năng lực của nhân dân với tư cách là chủ"],"dung":"A"},{"id":230,"chuong":4,"cauHoi":"Hồ Chí Minh khẳng định: \"Nhân dân có quyền lợi làm chủ, thì phải có nghĩa vụ làm tròn bổn phận công dân, giữ đúng đạo đức công dân\"52. Nghĩa là nhân dân làm chủ thì phải tuân theo quy định như thế nào của nhà nước?","dapAn":["Tuân theo pháp luật của nhà nước; tuân theo nghĩa vụ và quyền lợi của mỗi người dân....","Tuân theo pháp luật của nhà nước; tuân theo kỷ luật lao động, giữ gìn trật tự chung, đóng thuế đúng kỳ...","Tuân theo cơ chế hoặt động của nhà nước; tuân theo luật lao động và giữ gìn trật tự chung...","Tuân theo cơ chế giám sát của Đảng với nhà nước; tuân theo kỷ luật lao động và chính sách của nhà nước, đóng thuế đúng kỳ hạn..."],"dung":"B"},{"id":231,"chuong":4,"cauHoi":"Trong phiến họp đầu tiên của Chính phú lâm thời (ngày 3/9/1945), Hồ Chí Minh đã đề nghị Chính phủ thực hiện vấn đề cấp bách nào?","dapAn":["Tổ chức càng sớm càng tốt cuộc Tổng tuyển cử với chế độ bỏ phiếu theo từng khu vực","Tổ chức cuộc Tổng tuyển cử với chế độ bỏ phiếu trực tiếp từ các địa phương","Tổ chức càng sớm càng hay cuộc Tổng tuyển cử với chế độ phổ thông đầu phiêu","Tổ chức cuộc Tổng tuyển cử và thực hiện xây dựng chế độ xã hội chủ nghĩa trên đất nước ta"],"dung":"C"},{"id":232,"chuong":4,"cauHoi":"Ngày 2/3/1946 Quốc hội khóa I nước Việt Nam dân chủ Cộng hòa đã họp phiên đầu tiên, lập ra các tổ chức, bộ máy và các chức vụ chính thức của Nhà nướC. Hồ Chí Minh được bầu làm Chủ tịch Chính phủ liên hiệp đầu tiên. Đây là một Chính phủ như thế nào?","dapAn":["Có đầy đủ hệ thống tổ chức và cách thức để quản lý bộ máy nhà nước trong công tác đối nội và đối ngoại ở nước ta","Có đầy đủ tư cách pháp lý để giải quyết một cách có hiệu quả những vấn đề đối nội và đối ngoại ở nước ta","Có hệ thống tổ chức từ cấp Trung ương đến địa phương có đủ tư cách pháp lý để thực hiện công tác đối nội và đổi ngoại của nước ta","Có đầy đủ các cấp các ngành và cách thức triển khai hệ thống tổ chức trong công tác đối nội và đối ngoại ở nước ta"],"dung":"B"},{"id":233,"chuong":4,"cauHoi":"Ở cương vị Chú tịch nước, Hồ Chí Minh đã tham gia vào quá trình soạn thảo Hiến pháp nào và ký ban hành bao nhiêu đạo luật?","dapAn":["Hiến pháp năm 1946, năm 1959 và công bố 16 đạo luật","Hiến pháp năm 1959, năm 1980 và công bố nhiều đạo luật","Hiến pháp năm 1946, năm 1992 và công bố 613 sách lệnh","Hiến pháp năm 1992, năm 2001 và công bố nhiều sắc lệnh về hoạt động của bộ máy nhà nước"],"dung":"A"},{"id":234,"chuong":4,"cauHoi":"Nhà nước quản lý xã hội bằng bộ máy và bằng nhiều biện pháp khác nhau, nhưng theo Hồ Chí Minh quan trọng nhất là quản lý bằng gì?","dapAn":["Cơ chế và bộ máy","Giám sát và kiểm tra","Hiến pháp và pháp luật","Pháp luật và các mối quan hệ của pháp luật"],"dung":"C"},{"id":235,"chuong":4,"cauHoi":"Hồ Chí Minh luôn nêu cao tính nghiêm minh của pháp luật. Người tuyên bố: \"Pháp luật Việt Nam tuy khoan hồng với những người biết cải tà quy chính, nhưng sẽ thẳng tay trừng trị những tên Việt gian đầu sỏ đã bán nước buôn dân\"53. Như vậy, Hồ Chí Minh đòi hỏi hệ thống pháp luật phải như thế nào?","dapAn":["Đúng và phải đủ","Công khai và minh bạch","Dân chủ và nghiêm minh","Trở thành cán cân công lý"],"dung":"A"},{"id":236,"chuong":4,"cauHoi":"Theo Hồ Chí Minh, trong Đảng thực hành dân chủ rộng rãi, thường xuyên và nghiêm chỉnh tự phê bình và phê bình là cách tốt nhất để củng cố vấn đề gì?","dapAn":["Kỷ luật trong Đảng","Dân chủ trong Đảng","Nghiêm minh, tự giác trong Đảng","Sự đoàn kết thống nhất trong Đảng"],"dung":"D"},{"id":237,"chuong":4,"cauHoi":"Dân chủ và tập trung là hai mặt có quan hệ gắn bó và thống nhất biện chứng với nhau trong một nguyên tắc. Dân chủ để đi đến tập trung, tập trung trên nền tảng (...). Xác định cụm từ còn thiếu?","dapAn":["Dân quyền","Dân chủ","Dân chính","Dân quân"],"dung":"B"},{"id":238,"chuong":4,"cauHoi":"Kỷ luật của Đảng là kỷ luật tự giác, theo Hồ Chí Minh \"do lòng tự giác cua đảng viên về nhiệm vụ của họ đối với Đảng\"54, khi đã tự giác thì kỷ luật của Đảng mới nghiêm và bền lâu, thực sự tạo nên điều gì?","dapAn":["Sức mạnh cho mỗi tổ chức cơ sở Đảng","Sức mạnh cho mỗi đảng viên trong Đảng","Sức mạnh cho hệ thống chính trị","Sức mạnh cho Đảng"],"dung":"D"},{"id":239,"chuong":4,"cauHoi":"Chọn phương án trã lời đúng với tư tưởng Hồ chí Minh về Đảng Cộng sản Việt Nam có mối liên hệ như thế nào với nhân dân?","dapAn":["Hữu nghị","Mật thiết","Bình đăng","Đa dạng"],"dung":"B"},{"id":240,"chuong":4,"cauHoi":"Hồ Chí Minh đặc biệt coi trọng công tác cán bộ, coi cán bộ là cái gốc của mọi công việc, vì vậy muôn việc thành công hoặc thất bại đều do cán bộ:","dapAn":["Tốt hoặc kém","Tốt hoặc xấu","Giỏi hoặc dốt","Có kinh nghiệm hoặc không có kinh nghiệm"],"dung":"A"},{"id":241,"chuong":4,"cauHoi":"Hồ Chí Minh đặc biệt coi trọng hình thức dân chủ trực tiếp trong thực thi quyền lực của nhân dân, bởi đây là hình thức dân chủ:","dapAn":["Hoàn hảo nhất","Hoàn bị nhất","Giá trị nhất","Cốt lõi nhất"],"dung":"B"},{"id":242,"chuong":4,"cauHoi":"Trong thư gửi Hội nghị tư pháp toàn quốc, Hồ Chí Minh viết: \"Các bạn là những người (...). Lẽ tất nhiên các bạn cần phải nêu cao (...) \"phụng công, thủ pháp. chí công, vô tư\" cho nhân dân noi theo\"5. Xác định cụm từ còn thiếu?","dapAn":["Ý thức trách nhiệm trước pháp luật/ cái gương","Hiểu biết việc thi hành pháp luật/ nêu gương","Phụ trách thi hành pháp luật/ cái gương","Phụng sự thi hành pháp luật/ cái gương"],"dung":"C"},{"id":243,"chuong":4,"cauHoi":"Điểm đặc sắc nhất trong tư tưởng Hồ Chí Minh về nhà nước pháp quyền là gì?","dapAn":["Pháp luật có tính nghiêm minh, khuyến thiện","Pháp luật có tính nhân văn, khuyến thiện","Pháp luật có tính hài hòa, khuyến thiện","Pháp luật có tính công bằng, khuyến thiện"],"dung":"B"},{"id":244,"chuong":4,"cauHoi":"Trong pháp quyền nhân nghĩa Hồ Chí Minh, nhà nước trước hết phải tôn trọng, bảo đảm thực hiện đầy đủ các quyền con người, chăm lo đến lợi ích của mọi người. Ở luận điểm này, Hồ Chí Minh đã tiếp cận quyền con người như thế nào?","dapAn":["Một cách phiến diện","Một cách nghiêm khác","Một cách hoàn toàn mới","Một cách toàn diện"],"dung":"D"},{"id":245,"chuong":4,"cauHoi":"Vấn đề kiểm soát quyền lực nhà nước dựa trên cách thức tổ chức bộ máy nhà nước và việc phân công nhiệm vụ giữa các cơ quan thực thi quyền lực nhà nước được Hồ Chí Minh khẳng định trong bản Hiến pháp nào?","dapAn":["Hiến pháp năm 1946","Hiến pháp năm 1959","Hiến pháp năm 1980","Hiến pháp năm 1992"],"dung":"A"},{"id":246,"chuong":4,"cauHoi":"Tại sao Hồ Chí Minh khẳng định sự ra đời của Đảng Cộng sản năm 1930 là một quy luật đặc thù của Việt Nam?","dapAn":["Vì hoàn toàn phù hợp với xã hội một nước phụ thuộc","Vì hoàn toàn phù hợp với xã hội thuộc địa và phong kiến","Vì hoàn toàn phù hợp với xã hội hoàn toàn độc lập, tự do","Tất cả các đáp án"],"dung":"B"},{"id":247,"chuong":4,"cauHoi":"Hoạt động của Đảng trên cơ sở những nguyên tắc nhất định, trong đó nguyên tắc tự phê bình và phê bình được Hồ Chí Minh khẳng định là gì?","dapAn":["Là phương cách tốt nhất để mỗi người ngày càng hoàn thiện nhân cách của bản thân","Đề cán bộ, đảng viên hoàn thành sứ mệnh mà Đảng và nhân dân giao phó","\"Là cách tốt nhất để củng cố sự đoàn kết và thống nhất trong Đảng \"56","Là cách tốt nhất để Đảng ta thống nhất về mục tiêu, ý chí, hành động"],"dung":"C"},{"id":248,"chuong":4,"cauHoi":"Hồ Chí Minh yêu cầu tự phê bình và phê bình trong Đảng phải trên tinh thần như thế nào?","dapAn":["\"Phải có tình bạn bè yêu thương lẫn nhau\"","\"Phải có tình đồng chí thương yêu lẫn nhau\"5?","\"Phải có tình anh, chị, em yêu thương lẫn nhau\"","\"Phải có tình huynh đệ yêu thương lẫn nhau\""],"dung":"B"},{"id":249,"chuong":4,"cauHoi":"Trong các luận điểm sau, luận điểm nào sau đây là của Hồ Chí Minh về xây dựng một đảng cách mạng chân chính?","dapAn":["Hoạt động trong khuôn khố Hiển pháp và đường lối lãnh đạo của Đảng; có mối quan hệ đa phương hóa trong quan hệ kinh tế quốc tế","Hoạt động trong khuôn khổ Hiến pháp và pháp luật; có quan hệ quốc tế trong sáng; vì hòa bình, hữu nghị, hợp tác cùng phát triển","Hoạt động trong khuôn khổ Hiến pháp và chính sách của Đảng; tôn trọng các mối quan hệ, vì mục tiêu hòa bình, hợp tác, phát triển","Hoạt động trong khuân khổ Hiến pháp và pháp luật; có mối quan hệ hữu nghị, bình đẳng, đôi bên cùng có lợi"],"dung":"B"},{"id":250,"chuong":4,"cauHoi":"Hồ Chí Minh từng cảnh báo trong Đảng nếu không có đạo đức, văn mình thì Đảng sẽ như thế nào?","dapAn":["Không mất quyền lãnh đạo và khi đó Đảng chứng tô là một tổ chức tiên phong dẫn đường, đội ngũ cán bộ có phẩm chất trong sáng","Bị mất quyền lãnh đạo và khi đó Đảng chứng tỏ là một tổ chức bị dao động, tự chuyển hóa, đội ngũ cán bộ, đảng viên rơi vào giáo điều _","Bị mất quyền lãnh đạo và khi đó Đảng chứng tỏ là một tố chức không trong sạch, vững mạnh, đội ngũ cán bộ, đảng viên thoái hóa biến chất","Không trở thành lực lượng tiên phong dẫn đường và mất đoàn kết nội bộ"],"dung":"C"},{"id":251,"chuong":4,"cauHoi":"Hồ Chí Minh coi tập thể lãnh đạo là dân chủ, cá nhân phụ trách là tập trung để nhằm lưu ý điều cần tránh trong hoạt động của Đảng là gì?","dapAn":["Quan liêu, bao biện, coi trọng lợi ích cá nhân; dựa dẫm tập thể, không dám quyết đoán quyết đoán","Độc đoán, chuyên quyền, coi thường tập thể; dựa dẫm tập thể, không dám","Tham ô, lãng phí, óc địa phương chủ nghĩa; dựa dẫm tập thể, không dám quyết đoán","Tham nhũng, chuyên quyền, lôi kéo bè phái; dựa dẫm tập thể, không dám quyết đoán"],"dung":"B"},{"id":252,"chuong":4,"cauHoi":"Tự phê bình và phê bình trong quan điểm của Hồ Chí Minh là thang thuốc tốt nhất để làm cho điều gì tốt lên?","dapAn":["Làm cho phần tốt trong mỗi tổ chức, mỗi con người nẩy nở như hoa mùa xuân và phần xấu bị mất dần đi","Làm cho phần tốt trong mỗi cơ quan, đơn vị tốt lên, nảy nở như hoa mùa xuân và phần xấu bị đẩy lùi","Làm cho phần tốt trong mỗi quốc gia, dân tộc tốt lên, nẩy nở như hoa mùa xuân và phần xấu dần biến mất","Làm cho phần tốt trong mỗi địa phương, đất nước tốt lên, nảy nở như hoa mùa xuân và phần xấu bị biến mất"],"dung":"A"},{"id":253,"chuong":4,"cauHoi":"Theo Hồ Chí Minh, Đảng không có mục đích tự thân, không phải là tổ chức để làm quan phát tài mà Đảng từ trong xã hội mà ra, hoạt động của Đảng vì?","dapAn":["Nhân danh hạnh phúc, ấm no, đồng bào sung sưởng","Tô quốc giàu mạnh, đồng bào sung sướng","Sự tự do, âm no, hạnh phúc của nhân dân, ai cũng sung sướng","Đất nước giàu mạnh, đời sống vui tươi hạnh phúc"],"dung":"B"},{"id":254,"chuong":4,"cauHoi":"Khi đứng trước những thử thách lớn, trong quá trình hoạt động của Đảng, Hồ Chí Minh yêu cầu cần phải làm gì trước tiên?","dapAn":["Chỉnh đốn lại tổ chức của Đảng, làm cho mỗi đảng viên,... ra sức hoàn thành tốt nhiệm vụ được nhân dân giao phó","Chỉnh đốn lại đạo đạo đức đảng viên, làm cho mỗi đảng viên,... ra sức thực hiện trao dồi đạo đức cách mạng, toàn tâm phục vụ nhân dân","Chỉnh đốn lại Đảng, làm cho mỗi đảng viên,... ra sức làm tròn nhiệm vụ đảng giao phó, toàn tâm toàn ý phục vụ nhân dân","Chỉnh đốn lại Nhà nước, làm cho cán bộ, đảng viên trong bộ máy nhà nước,... ra sức phục vụ nhân dân, hoàn thành tốt nhiệm vụ được giao phó"],"dung":"C"},{"id":255,"chuong":4,"cauHoi":"Theo Hồ chí Minh, nhờ thực hiện đoàn kết chặt chẽ, một lòng một dạ phục vụ giai cấp, phục vụ nhân dân, phục vụ Tổ quốc. Cho nên, từ khi thành lập đến nay Đảng ta đã thực hiện đoàn kết, tổ chức lãnh đạo nhân dân như thế nào?","dapAn":["Nhân dân hăng hải thi đua tiến lên giành thắng lợi cho cách mạng dân tộc","Nhân dân hăng hái tiến lên xây dựng thành công chủ nghĩa xã hội","Nhân dân hăng hái đấu tranh tiến từ thẳng lợi này đến thắng lợi khác","Nhân dân hăng hái thực hiện khôi phục lại hậu quả sau chiến tranh"],"dung":"C"},{"id":256,"chuong":4,"cauHoi":"Trong mối quan hệ khăng khít, máu thịt giữa Đảng với giai cấp công nhân và nhân dân Việt Nam, Hồ Chí Minh yêu cầu mối quan hệ này phải hướng đích như thế nào?","dapAn":["Xây dựng một nhà nước Việt Nam tươi đẹp, dân giàu, nước mạnh, dân chủ, văn minh","Thành lập một nhà nước hòa bình thống nhất, góp phần vào sự nghiệp cách mạng chung của thê giới","Xây dựng một nước Việt Nam hòa bình, thống nhất, độc lập, dân chủ và giàu mạnh, và góp phần xứng đáng vào sự nghiệp cách mạng thế giới","Xây dựng một nước Việt Nam phát triển toàn diện về kinh tế, chính trị, văn hóa, giáo dục, an inh - quốc phòng"],"dung":"C"},{"id":257,"chuong":4,"cauHoi":"Hồ Chí Minh quan niệm Đảng Cộng sản nhất thiết phải là hiện thân của văn hóa dân tộc là vì lí do gì?","dapAn":["Đảng là đội tiên phong của giai cấp công nhân, nhân dân lao động và tất cả các nước trên thế giới","Đảng là đội tiền phong của giai cấp công nhân, nhân dân lao động và của cả dân tộc Việt Nam","Đảng là kết quả của sự kết hợp giữa chủ nghĩa Mác - Lênin với phong trào công nhân và phong trào yêu nước","Đảng là sợi chỉ đỏ lãnh đạo phong trào cách mạng đi đến thành công"],"dung":"B"},{"id":258,"chuong":4,"cauHoi":"Khi mỗi cán bộ, đảng viên có trách nhiệm, năng động, sáng tạo, thì trong mọi tình huống khó khăn sẽ không dao động, lười biếng mà là những người \"thắng không kiêu, bại không nản\". Do đó, Hồ Chí Minh luôn đòi hỏi mỗi cán bộ, đảng viên trong Đảng phải rèn luyện, tu dưỡng như thế nào?","dapAn":["Luôn trau dồi chuyên môn nghiệp vụ; luôn nỗ lực không ngừng để rèn luyện bản thân 65","Luôn chú trọng, phát huy ý thức trách nhiệm; luôn học tập để nâng cao trình độ về mọi phương diện","Luôn tu dưỡng đạo đức cách mạng; luôn học tập để nâng cao trình độ về mọi mặt","Luôn quan tâm, rèn luyện bản lĩnh chính trị; luôn học tập để nâng cao trình độ bản thân"],"dung":"C"},{"id":259,"chuong":4,"cauHoi":"Việc phòng và chống các tiêu cực trong tổ chức bộ máy, Hồ Chí Minh lưu ý phải đặc biệt phòng và chống tham ô, lãng phí, quan liêu vì Người cho đó là:","dapAn":["Giặc nội xâm, là những kẻ địch bên trong","Giặc ngoại xâm, là những kẻ địch bên ngoài","Sự tha hóa, biến chất của đội ngũ cán bộ","Giặc nội xâm, là những kẻ địch phản cách mạng"],"dung":"A"},{"id":260,"chuong":4,"cauHoi":"Chọn phương án trả lời sai với tư tưởng Hồ Chí Minh về công tác cán bộ trong Đảng?","dapAn":["Phải hiểu và đánh giá đúng cán bộ","Phải chú trọng huấn luyện cán bộ, huấn luyện một cách thiết thực, có hiệu quả","Phải được tập trung lãnh đạo, chỉ đạo toàn diện, đồng bộ và đạt một số kết quả trong công tác cán bộ","Phải đề bạt đúng cán bộ; phải sắp xếp, sử dụng cán bộ cho đúng; phải kết hợp \"cán bộ cấp trên phái đến và cán bộ địa phương\"s8"],"dung":"C"},{"id":261,"chuong":4,"cauHoi":"Trong hành trình tìm đường cứu nước, Hồ Chí Minh đã nghiên cứu những mô hình nhà nước nào?","dapAn":["Nhà nước quân chủ chuyên chế; nhà nước quân chủ lập hiến","Chế độ Đại nghị; Tổng thống chế","Nhà nước phong kiên; nhà nước tư sản; nhà nước kiểu mới","Chế độ độc tài quân phiệt; chế độ phát xít; chế độ cộng sản"],"dung":"C"},{"id":262,"chuong":4,"cauHoi":"Theo Hồ Chí Minh, pháp luật là công cụ quyền lực của nhân dân, vì thế điều quan trọng là phải:","dapAn":["\"Làm sao cho nhân dân biết hưởng quyền dân chủ, biết dùng quyền dân chủ của mình, đám nói, dám làm\"","Làm sao cho dân hiêu pháp luật và thực thi đúng pháp luật","Làm sao cho pháp luật đi vào cuộc sống, người dân thực hiện đúng pháp","Làm sao cho pháp luật trở thành cán cân của công lý, xét xử đúng người, đúng tội, tránh oan sai"],"dung":"A"},{"id":263,"chuong":4,"cauHoi":"Theo Hồ Chí Minh căn cứ để Đảng có quyền và có trách nhiệm kiểm soát quyền lực Nhà nước?","dapAn":["Đảng là đội tiên phong của giai cấp công nhân, của nhân dân lao động, của dân tộc, Đảng quản lý Nhà nước và toàn xã hội","Đảng là đội tiên phong của giai cấp công nhân, của nhân dân lao động, của dân tộc, Đảng tổ chức, tập hợp Nhà nước và xã hội","Đảng là đội tiền phong của giai cấp công nhân, của nhân dân lao động và của dân tộc, là Đảng cầm quyền, lãnh đạo Nhà nước và xã hội","Đảng là đội tiên phong của giai cấp công nhân, của nhân dân lao động, của dân tộc, Đảng tuyên truyền, giáo dục Nhà nước và xã hội"],"dung":"C"},{"id":264,"chuong":4,"cauHoi":"Theo Hồ Chí Minh, tại sao nhân dân có quyền kiểm soát quyền lực Nhà nước?","dapAn":["Nhân dân luôn giúp đỡ, ủng hộ Nhà nước","Nhân dân luôn kiểm tra, giám sát, phê bình Nhà nước","Nhân dân là chủ thể tối cao của quyền lực Nhà nước","Nhân dân thực hiện tốt chính sách, pháp luật Nhà nước"],"dung":"C"},{"id":265,"chuong":4,"cauHoi":"Hồ Chí Minh chỉ ra nguyên nhân chủ quan dẫn đến những tiêu cực trong hoạt động của Nhà nước, bắt nguồn từ căn \"bệnh mẹ\" là:","dapAn":["Chủ nghĩa cá nhân, tự sự thiếu tu dưỡng, rèn luyện của bản thân cán bộ","Sự chống phá của các thế lực thù địch trong và ngoài nước","Tàn dư của chế độ thực dân, phong kiến để lại","Mặt trái của kinh tế thị trường, hội nhập quốc tế"],"dung":"A"},{"id":266,"chuong":4,"cauHoi":"Trong quan điểm về nhà nước dân chủ, nhà nước do nhân dân là người chủ nắm chính quyền, Hồ Chí Minh đã nhấn mạnh nòng cốt của nhân dân là liên minh giai cấp nào","dapAn":["Công - Nông - Trí, do giai cấp công nhân mà đội tiên phong là Nhà nước lãnh đạo","Công -Nông - Trí, do giai cấp công nhân mà đội tiên phong là Đảng Cộng sản Việt Nam lãnh đạo","Công - Nông - Trí, do giai cấp công nhân mà đội tiên phong là Mặt trận Tổ quốc và các tổ chức chính trị lãnh đạo","Công - Nông - Trí, do giai cấp công nhân mà đội tiên phong là hệ thống chính trị lãnh đạo"],"dung":"B"},{"id":267,"chuong":4,"cauHoi":"Nhà nước dân chủ do Đảng lãnh đạo bằng phương thức thích hợp. Trong thời kỳ Hồ Chí Minh, nước ta vừa kháng chiến chống giặc ngoại xâm, giải phóng và bảo vệ Tổ quốc, vừa lãnh đạo nhân dân xây dựng chế độ mới. Vậy, phương thức lãnh đạo chung cho thời kỳ này, đó là gì?","dapAn":["Bằng chủ trương, quan điểm; bằng công tác kiểm tra mọi hoạt động của nhà nước","Bằng quan điểm, phương hướng; bằng công tác cán bộ trong bộ máy nhà nước","Bằng đường lối, quan điểm, chủ trương; bằng hoạt động của tổ chức đảng và đảng viên; bằng công tác kiểm tra","Bằng định hướng đi lên chủ nghĩa xã hội; bằng sự giám sát hoạt động của tổ chức đàng và đảng viên"],"dung":"C"},{"id":268,"chuong":4,"cauHoi":"Bản chất giai cấp công nhân của Nhà nước thể hiện ở nguyên tắc tổ chức và hoạt động của nó là nguyên tắc tập trung dân chủ, Hồ Chí Minh đã nhấn mạnh nguyên tắc này nhằm đảm bảo thống nhất điều gì?","dapAn":["Quyền lực trong bộ mày nhà nước đều thuộc về giai cấp nông dân","Quyền lực trong nhà nước đều thuộc về nhân dân","Pháp luật trong nhà nước đều thuộc về nhân dân","Nghĩa vụ và trách nhiệm của nhân dân trong bộ máy nhà nước"],"dung":"B"},{"id":269,"chuong":4,"cauHoi":"Dân chủ gián tiếp hay dân chủ đại diện là hình thức dân chủ được sử dụng rộng rãi nhằm thực thi quyền lực của nhân dân. Theo Hồ Chí Minh, trong hình thức dân chủ này quyền lực của nhà nước từ đâu mà có?","dapAn":["Là \"thừa ủy quyền\" của giai cấp công nhân ủy thác cho","Là \"thừa ủy quyền\" của giai cấp nông dân ủy thác cho","Là \"thừa ủy quyền\" của nhân dân hay do nhân dân ủy thác cho","Là \"thừa ủy quyền\" của các tâng lớp tiểu tư sản ủy thác cho"],"dung":"C"},{"id":270,"chuong":4,"cauHoi":"Nhân dân có quyền kiểm soát, phê bình, bãi miễn những đại biểu mà họ đã lựa chọn, bầu ra và có quyền giải tán những thiết chế quyền lực đã lập nên. Đây là quan điểm rõ ràng, kiên quyết của Hồ Chí Minh nhằm đảm bảo cho điều gì?","dapAn":["Mọi quyền lực luôn nằm trong tay nhân dân","Mọi quyền hành luôn thuộc về nhân dân","Mọi quyền lợi nằm trong tay nhân dân","Mọi nghĩa vụ đều thuộc về nhân dân"],"dung":"A"},{"id":271,"chuong":4,"cauHoi":"Một nhà nước thực sự của dân, theo Hồ Chí Minh luôn \"mong đồng bào giúp đỡ, (...), (...) và phê bình để làm trọn nhiệm vụ của mình là người đầy tớ trung thành tận tuy của nhân dân\"60. Xác định cụm từ còn thiếu?","dapAn":["Kiểm tra/ giám sát","Nhắc nhở/ kiểm soát","Chia sẻ/ đôn đốc","Đôn đốc/ kiểm soát"],"dung":"D"},{"id":272,"chuong":4,"cauHoi":"Hồ Chí Minh khẳng định sự khác biệt của luật pháp trong Nhà nước Việt Nam mới với luật pháp chế độ tư sản, phong kiến là gì?","dapAn":["Vì pháp luật trong nhà nước của dân phản ánh được tinh thần của nhân dân","Vì pháp luật trong nhà nước của dân bảo vệ quyền lợi chính đáng của giai cấp nông dân","Vì luật pháp trong nhà nước của dân phản ánh được ý nguyện và bảo vệ quyền lợi của dân chúng","Vì pháp luật trong nhà nước của dân khẳng định quyền lợi hợp pháp của nhân dân"],"dung":"C"},{"id":273,"chuong":4,"cauHoi":"Nhà nước do dân trước hết là nhà nước do dân lập nên sau thắng lợi của sự nghiệp cách mạng của toàn dân tộc dưới sự lãnh đạo của Đảng. Do đó, theo Hồ Chí Minh, nhân dân cử ra, tổ chức nên nhà nước dựa trên nền tảng nào?","dapAn":["Nền tảng dân chủ xã hội chủ nghĩa","Bộ máy quản lý phù hợp với chế độ dân chủ","Cơ chế hoạt động của chế độ dân chủ","Pháp lý của chế độ dân chủ"],"dung":"D"},{"id":274,"chuong":4,"cauHoi":"Nhà nước do nhân dân làm chủ, nghĩa là nhà nước phải tạo mọi điều kiện để nhân dân được thực thi những quyền mà Hiếp pháp và pháp luật quy định. Hồ Chí Minh đã yêu cầu đội ngũ cán bộ, đảng viên phải thật sự tôn trọng điều gì?","dapAn":["Nghĩa vụ làm chủ của nhân dân","Ý thức làm chủ của nhân dân","Quyền làm chủ của nhân dân","Trách nhiệm làm chủ của nhân dân"],"dung":"C"},{"id":275,"chuong":4,"cauHoi":"Trong nhà nước do dân làm chủ, Hồ Chí Minh coi trọng việc giáo dục nhân dân, đồng thời yêu cầu nhân dân cũng phải tự giác phấn đấu để có điều gì?","dapAn":["Có đủ kiến thức thực hiện quyền dân chủ của mình","Có đủ hiểu biết thực hiện quyền dân chủ của mình","Có đủ phẩm chất thực hiện quyền dân chủ của mình","Có đủ năng lực thực hiện quyền dân chủ của mình"],"dung":"D"},{"id":276,"chuong":4,"cauHoi":"Nhà nước vì dân là nhà nước phục vụ lợi ích và nguyện vọng của nhân dân, không có đặc quyền đặc lợi,... do đó, Hồ Chí Minh đã yêu cầu các cơ quan nhà nước, các cán bộ nhà nước đều phải làm gì?","dapAn":["Vì mọi người phục vụ","Vì chế độ xã hội phục vụ","Vì nhân dân phục vụ","Vì giai cấp công - nông - binh phục vụ"],"dung":"C"},{"id":277,"chuong":4,"cauHoi":"Thước đo của một Nhà nước vì dân là phải được lòng dân. Hồ Chí Minh đặt vấn đề với cán bộ Nhà nước: \"muốn được dân yêu, muốn được lòng dân, trước hết phải yêu dân, phải đặt (...), phải có một tinh thần chí công vô tư361. Xác định cụm từ còn thiếu?","dapAn":["Quyền lợi của dân trên hết thảy","Quyền tự quyết của dân tộc đặt lên hàng đầu","Quyền dân chủ của nhân dân trên hết thảy","Quyền bình đắng của dân trên hết thảy"],"dung":"A"},{"id":278,"chuong":4,"cauHoi":"Trong nhà nước pháp quyền của dân, do dân, vì dân, Hồ Chí Minh luôn chú trọng vấn đề gì?","dapAn":["Xây dựng nền tảng chính trị cho nước Việt Nam mới","Xây dựng nền tảng pháp lý cho nhà nước Việt Nam mới","Xây dựng nền tảng đạo đức cho nước Việt Nam mới","Xây dựng nền tảng kinh tế cho nước Việt Nam mới"],"dung":"B"},{"id":279,"chuong":4,"cauHoi":"Khi trở thành người đứng đầu Nhà nước Việt Nam mới, Hồ Chí Minh quan tâm sâu sắc hơn việc đảm bảo cho Nhà nước được tổ chức và vận hành phù hợp với điều gì?","dapAn":["Các mối quan hệ xã hội, đồng thời căn cứ vào pháp luật để điều hành xã hội","Sự giám sát quyền lực của nhà nước, đồng thời căn cứ vào pháp luật để điều hành xã hội","Công tác kiểm tra, giám sát của Đảng với Nhà nước, đồng thời căn cứ vào pháp luật để điều hành xã hội","Pháp luật, đồng thời, căn cứ vào pháp luật để điều hành xã hội"],"dung":"D"},{"id":280,"chuong":4,"cauHoi":"Cùng với công tác lập pháp, Hồ Chí Minh cũng rất chú trọng đưa pháp luật vào (...) và có cơ chế giám sát việc thi hành pháp luật. Xác định cụm từ còn thiếu?","dapAn":["Trong các mối quan hệ xã hội, bảo đảm cho pháp luật được thi hành đúng","Trong cuộc sống, bảo đảm cho pháp luật được thi hành","Trong bộ máy nhà nước, đảm bảo cho pháp luật có hiệu lực","Trong cơ chế giám sát hoạt động nhà nước của nhân dần, đảm bảo cho pháp luật được thực thi nghiêm minh"],"dung":"B"},{"id":281,"chuong":4,"cauHoi":"Để pháp luật đi vào cuộc sống, Hồ Chí Minh yêu cầu mỗi người dân phải thế nào để có ý thức tôn trọng và tuân thủ pháp luật?","dapAn":["Có trình độ hiểu biết và năng lực sử dụng pháp luật","Có trình độ nhận thức và khả năng sử dụng pháp luật","Có trình độ chuyên môn và tư duy phát hiện trong sử dụng pháp luật","Có kỹ năng và sáng tạo trong sử dụng pháp luật"],"dung":"A"},{"id":282,"chuong":4,"cauHoi":"Trong công tác giáo dục pháp luật cho mọi người dân, Hồ Chí Minh đặc biệt chú trọng giáo dục pháp luật cho đối tượng nào?","dapAn":["Cho thế hệ lão thành cách mạng","Cho thế hệ trẻ","Cho thế hệ mầm non","Cho thế hệ thanh niên xung kính"],"dung":"B"},{"id":283,"chuong":4,"cauHoi":"Hồ Chí Minh luôn khuyến khích nhân dân phê bình, giám sát quá trình nhà nước thực thi pháp luật, đồng thời không ngừng nhắc nhở cán bộ các cấp, các ngành điều gì?","dapAn":["Phải gương mẫu trong việc tuân thủ pháp luật, trước hết là các cán bộ thuộc ngành tài chính ngân hàng","Phải gương mẫu trong việc tuân thủ pháp luật, trước hết là các cán bộ thuộc ngành hành pháp và tư pháp","Phải gương mẫu trong việc tuân thủ pháp luật, trước hết là các cán bộ thuộc ngành hàng hải, hàng không","Phải gương mẫu trong việc tuân thủ pháp luật, trước hết là các cán bộ thuộc lực lượng vũ trang"],"dung":"B"},{"id":284,"chuong":4,"cauHoi":"Để giữ vững bản chất của nhà nước, bảo đảm cho nhà nước hoạt động có hiệu quả, phòng chống thoái hóa biến chất trong đội ngũ cán bộ, Hồ Chí Minh đặc biệt chú trọng vân đề gì trong bộ máy nhà nước?","dapAn":["Giám sát thực hiện quyền lực nhà nước","Kiểm tra bộ máy quyền lực nhà nước","Kiểm soát quyền lực nhà nước","Bao tre quyền lực nhà nước"],"dung":"C"},{"id":285,"chuong":4,"cauHoi":"Theo Hồ Chí Minh, tại sao phải kiểm soát quyền lực nhà nước?","dapAn":["Để đảm bảo quyền lực nhà nước thuộc về nhân dân","Để đảm bảo sự trong sạch của Nhà nước","Để đảm bảo pháp luật của Nhà nước được thực thi","Để đảm bảo chính sách của Nhà nước được thực hiện"],"dung":"A"},{"id":286,"chuong":4,"cauHoi":"Để kiểm soát quyền lực tốt nhà nước tốt, theo Hồ Chí Minh cần phải có điều kiện gì?","dapAn":["Kiểm soát phải có hệ thống và người đi kiểm soát phải là những người lãnh đạo giỏi","Kiểm soát phải có hệ thống và người đi kiểm soát phải là những người rất có uy tín","Kiểm soát phải có hệ thống và người đi kiểm soát phải là những người thừa ủy quyền của các cấp lãnh đạo","Kiểm soát phải có hệ thồng và người đi kiểm soát phải là những người có trách nhiệm cao, năng động, sáng tạo"],"dung":"B"},{"id":287,"chuong":4,"cauHoi":"Về cách kiềm soát quyền lực nhà nước, Hồ Chí Minh yêu cầu phải kiểm soát như thế nào?","dapAn":["Từ dưới lên trên và từ trên xuống dưới, đặc biệt phải có nhiều hình thức kiểm soát","Từ trong ra ngoài và từ ngoài vào trong, đặc biệt phải có nhiệu biện pháp kiểm soát","Từ trên xuống dưới và từ dưới lên trên, đặc biệt phải khéo kiểm soát","Từ nhiều biên độ khác nhau, đặc biệt là phải khéo kiểm soát từ bên trên xuống bên dưới"],"dung":"C"},{"id":288,"chuong":4,"cauHoi":"Hiện nay, việc vận dụng tư tưởng Hồ Chí Minh vào công tác xây dựng Đảng trong sạch, vững mạnh cần phải thực hiện như thế nào?","dapAn":["Đề ra đường lối, chủ trương đúng đắn; tổ chức thực hiện đúng và thường xuyên chú trọng công tác chỉnh đốn Đảng","Đề ra nhiệm vụ, giải pháp phù hợp; tổ chức thực hiện tốt và chú trọng vào nâng cao chất lượng đội ngũ làm công tác tổ chức của Đảng","Đề ra các quan điểm, phướng hướng phù hợp; tổ chức thực hiện đúng và thường xuyên chỉnh đốn, đổi mới công tác xây dựng Đảng","Đề ra nội dung, định hướng đúng đắn; tổ chức thực hiện hiệu quả và thường xuyên đổi mới công tác tổ chức của Đảng"],"dung":"A"},{"id":289,"chuong":4,"cauHoi":"Theo Hồ Chí Minh, để xây dựng nhà nước pháp quyền xã hội chủ nghĩa hiện nay cần phải chú trọng những nội dung nào?","dapAn":["Xây dựng nhà nước thật sự trong sạch, vững mạnh và thường xuyên đổi mới","Xây dựng nhà nước thật sự trong sạch, vững mạnh và đổi mới, tăng cường sự lãnh đạo của Đảng đối với Nhà nước","Xây dựng nhà nước thật sự trong sạch, vững mạnh và tăng cương công tác kiểm tra, giám sát của Đảng","Xây dựng nhà nước thật sự trong sạch, vững mạnh và đổi mới, quán triệt theo đường lối lãnh đạo của Đảng"],"dung":"B"},{"id":290,"chuong":5,"cauHoi":"Theo Hồ Chí Minh, đại đoàn kết dân tộc là vấn đề như thế nào?","dapAn":["Có ý nghĩa chiến lược, quyết định thành công cách mạng","Có ý nghĩa sách lược, quyết định thành công cách mạng","Có ý nghĩa lịch sử, quyết định thành công cách mạng","Có ý nghĩa đặc biệt quan trọng, quyết định thành công của cách mạng"],"dung":"A"},{"id":291,"chuong":5,"cauHoi":"Trong liên minh giữa giai cấp công nhân, nông dân với các giai cấp, tầng lớp khác, Hồ Chí Minh chú trọng nhất đến giai cấp, tầng lớp nào?","dapAn":["Đội ngũ trí thức","Tư sản Việt Nam","Địa chủ","Tất cả đáp án"],"dung":"A"},{"id":292,"chuong":5,"cauHoi":"Đề Mặt trận dân tộc thống nhất hoạt động có hiệu quả, theo Hồ Chí Minh cần phải có nguyên tắc xây dựng và hoạt động như thế nào?","dapAn":["Phải được xây dựng trên nền tảng liên minh công nhân - nông dân - trí thức được đặt dưới lãnh đạo của Đảng","Phải xuất phát từ mục tiêu vì nước, vì dân và phải hoạt động trên nguyên tắc hiệp thương dân chủ","Phải đoàn kết lâu dài, chặt chẽ, đoàn kết thực sự, chân thành, thân ái giúp đỡ nhau cùng tiến bộ","Tất cả các đáp án"],"dung":"D"},{"id":293,"chuong":5,"cauHoi":"Theo Hồ Chí Minh, hình thức tổ chức của khối đại đoàn kết dân tộc là gì?","dapAn":["Mặt trận dân tộc thống nhất","Mặt trận dân tộc Việt Nam","Mặt trận dân tộc giải phóng","Mặt trận dân tộc dân chủ"],"dung":"A"},{"id":294,"chuong":5,"cauHoi":"Điều kiện để thực hiện xây dựng khối đại đoàn dân tộc theo Hồ Chí Minh là gì?","dapAn":["Phải kế thừa truyền thống yêu nước, nhân nghĩa, đoàn kết của dân tộc","Phải có lòng khoan dung độ lượng với con người","Phải có niềm tin với nhân dân","Tất cả các đáp án"],"dung":"D"},{"id":295,"chuong":5,"cauHoi":"Câu nói nào sau đây thể hiện quan điểm mang tính chân lý của Chủ tịch Hồ Chí Minh về vai trò và sức mạnh của đại đoàn kết dân tộc?","dapAn":["Đoàn kết là sức mạnh của chúng ta","Đoàn kết là sức mạnh, là then chốt của thành công","Đoàn kết, đoàn kết, đại đoàn kết","Thành công, thành công, đại thành công"],"dung":"D"},{"id":296,"chuong":5,"cauHoi":"Xác định đại đoàn kết dân tộc là mục tiêu, nhiệm vụ hàng đầu, theo Hồ Chí Minh nhiệm vụ này cần phải quán triệt như thế nào?","dapAn":["Trong lãnh đạo đấu tranh giành chính quyền và bảo vệ chính quyền của","Trong lãnh đạo thực hiện đồng thời hai nhiệm vụ xây dựng chủ nghĩa xã hội ở Miền Bắc và đấu tranh thống nhất đất nước ở miền Nam","Trong tất cả lĩnh vực, từ đường lối, chủ trương, chính sách, tới hoạt động thực tiền của Đảng","Tất cả các đáp án"],"dung":"C"},{"id":297,"chuong":5,"cauHoi":"Năm 1947, trong trả lời các nhà báo, Hồ Chí Minh tuyên bố: Chính sách đối ngoại của nước Việt Nam là \"làm bạn với tất cả các nước (...) và không gây thù oán với một ai'2. Xác định cụm từ còn thiếu?","dapAn":["Trên thế giới","Cường quốc","Láng giềng","Dân chủ"],"dung":"D"},{"id":298,"chuong":5,"cauHoi":"Lực lượng đoàn kết quốc tế được Hồ Chí Minh xác định là gì?","dapAn":["Phong trào cộng sản và công nhân quốc tế","Phong trào đấu tranh giải phóng dân tộc","Lực lượng tiến bộ, những người yêu chuộng hòa bình, dân chủ, tự do và công lý","Tất cả các đáp án"],"dung":"D"},{"id":299,"chuong":5,"cauHoi":"Năm 1951, trong buổi ra mắt Đảng Lao động Việt Nam, Hồ Chí Minh đã tuyên bố mục đích của Đảng Lao động Việt Nam là gì?","dapAn":["Đoàn kết toàn dân, phụng sự Tổ quốc","Đoàn kết toàn dân, phụng vụ nhân dân","Đoàn kết toàn dân, phụng sự giai cấp","Đoàn kết toàn dân, phụng vụ đoàn thể"],"dung":"A"},{"id":300,"chuong":5,"cauHoi":"Luận điểm của Hồ Chí Minh: \"Sử dạy ta bài học này: Lúc nào dân ta (...) muốn người như một thì nước ta độc lập, tự do. Trái lại lúc nào dân ta không (...) thì bị nước ngoài xâm lần \"63. Xác định cụm từ còn thiếu?","dapAn":["Đoàn kết.","Gắn kết","Liên kết","Hợp tác"],"dung":"A"},{"id":301,"chuong":5,"cauHoi":"Đại đoàn kết dân tộc trong tư tưởng Hồ Chí Minh được xác định là mục tiêu, nhiệm vụ hàng đầu của:","dapAn":["Cách mạng dân tộc dân chủ nhân dân","Cách mạng giải phóng dân tộc","Cách mạng xã hội chủ nghĩa","Cách mạng Việt Nam"],"dung":"D"},{"id":302,"chuong":5,"cauHoi":"Luận điểm của Hồ Chí Minh: \"Lực lượng chủ yếu trong khối đại đoàn kết dân tộc là (...), cho nên liên minh (...) là nền tảng của Mặt trận dân tộc thống nhất\"64. Xác định cụm từ còn thiếu?","dapAn":["Công nông thương - công nông thương","Công nông trí - công nông trí","Công nông - công nông","Công nông binh - công nông binh"],"dung":"C"},{"id":303,"chuong":5,"cauHoi":"Tùy theo từng thời kỳ, căn cứ vào yêu cầu và nhiệm vụ của cách mạng, Mặt trận dân tộc thống nhất có những tên gọi khác nhau. Năm 1941, 1976 có tên gọi là gì?","dapAn":["Mặt trận Việt Minh/ Mặt trận Tổ quốc Việt Nam","Mặt trận dân chủ/ Mặt trận Liên hiệp các nước thuộc địa","Mặt trận nhân dân phản đề/ Mặt trân giải phóng miền Nam","Mặt trận Liền Việt/ Mặt trận nhân dân phải đế đồng minh"],"dung":"A"},{"id":304,"chuong":5,"cauHoi":"Năm 1924, Hồ Chí Minh đã đưa ra quan điểm về thành lập mặt trận nào sau đây?","dapAn":["Mặt trận đoàn kết Việt Nam - Lào - Campuchia","Mặt trận thống nhất của nhân dân chính quốc và thuộc địa","Mặt trận nhân dân Á - Phi đoàn kết với Việt Nam","Mặt trận nhân dân thế giới đoàn kết với Việt Nam chống đế quốc xâm lược"],"dung":"B"},{"id":305,"chuong":5,"cauHoi":"Luận điểm của Hồ Chí Minh: \"Làm cho (...), từ trước đến nay vẫn cách biệt nhau, hiểu biết nhau hơn, đoàn kết nhau lại để đặt cơ sở cho một liên minh phương Đông tương lai*65. Xác định cụm từ còn thiếu?","dapAn":["Các dân tộc độc lập","Các dân tộc thuộc địa","Các dân tộc mất độc lập","Các dân tộc phụ thuộc"],"dung":"B"},{"id":306,"chuong":5,"cauHoi":"Theo Hồ Chí Minh, các đòn thể, tổ chức đoàn chúng cần được đoàn kết, tập hợp trong tổ chức nào?","dapAn":["Quốc hội","Đảng Cộng sản Việt Nam","Mặt trận dân tộc thống nhất","Chính phủ"],"dung":"C"},{"id":307,"chuong":5,"cauHoi":"Để đoàn kết ba nước Đông Dương, trong hai cuộc kháng chiến chống thực dân Pháp và đế quốc Mỹ, Hồ Chí Minh đã chỉ đạo thành lập mặt trận nào?","dapAn":["Mặt trận dân chủ ba nước Đông Dương","Mặt trận phản để ba nước Đông Dương","Mặt trận nhân dân ba nước Đông Dương","Mặt trận chống đế quốc ba nước Đông Dương"],"dung":"C"},{"id":308,"chuong":5,"cauHoi":"Để thực hiện tốt nhiệm vụ, mục tiêu hàng đầu của Đảng là đại đoàn kết dân tộc, theo Hồ Chí Minh, Đảng Cộng sản cần phải làm tốt công tác gì?","dapAn":["Nận động quần chúng","Quản lý quần chúng","Giám sát quần chúng","Đôn đốc quần chúng"],"dung":"A"},{"id":309,"chuong":5,"cauHoi":"Theo Hồ Chí Minh, lực lượng làm nền tảng của khối đại đoàn kết dân tộc là:","dapAn":["Công nhân, nông dân và trí thức","Công nhân, nông dân, tiếu tư sản trí thức","Công nhân, trí thức, tư sản dân tộc","Công nhân, nông dân, địa chủ phong kiến"],"dung":"A"},{"id":310,"chuong":5,"cauHoi":"Hồ Chí Minh chỉ rõ trong quá trình xây dựng khối đại đoàn kết toàn dân tộc, phải đứng vững trên lập trường của giai cấp nào?","dapAn":["Địa chủ phong kiến","Nông dân","Tư sản Việt Nam","Công nhân"],"dung":"D"},{"id":311,"chuong":5,"cauHoi":"Theo Hồ Chí Minh, yếu tố \"hạt nhân\" nào cần đoàn kết, thống nhất để tạo điều kiện cho đoàn kết ngoài xã hội?","dapAn":["Quốc hội","Mặt trận Tổ quốc Việt Nam","Đảng Cộng sản Việt Nam","Đoàn thanh niên Cộng sản Hồ Chí Minh"],"dung":"C"},{"id":312,"chuong":5,"cauHoi":"Theo Hồ Chí Minh, Đảng Cộng sản Việt Nam được xác định vị trí như thế nào trong quan hệ với Mặt trận dân tộc thống nhất?","dapAn":["Là thành viên, không là lực lượng lãnh đạo","Không là thành viên, là lực lượng lãnh đạo","Vừa là thành viên, vừa là lực lượng lãnh đạo","Không là thành viên, không là lực lượng lãnh đạo"],"dung":"C"},{"id":313,"chuong":5,"cauHoi":"Tại sao tư tưởng Hồ Chí Minh về đại đoàn kết dân tộc có sức sống trường tồn cùng cách mạng Việt Nam?","dapAn":["Tư tưởng đại đoàn kết dân tộc của Người trở thành quan điểm xuyên suốt đường lối chiến lược của Đảng Cộng sản Việt Nam trong các giai đoạn cách mạng","Tư tưởng của Người thấm sâu vào tư tưởng, tình cảm của tất cả người Việt Nam yêu nước","Tư tưởng đại đoàn kết dân tộc của Người đã biến thành hành động cách mạng của hàng triệu người dân, tạo thành sức mạnh vô địch trong xây dựng, bao vệ Tố quốc","Tất cả đáp án"],"dung":"D"},{"id":314,"chuong":5,"cauHoi":"Vận dụng tư tưởng Hồ Chí Minh về đoàn kết quốc tế, để nâng cao hiệu quả hợp tác quốc tế, chủ động hội nhập kinh tế khu vực và thế giới, Đảng, Nhà nước ta chủ trương phát huy sức mạnh nào sau đây?","dapAn":["Sức mạnh dân tộc - sức mạnh của chủ nghĩa yêu nước","Sức mạnh của người làm của người làm chủ","Sức mạnh đại đoàn kết toàn dân, trên cơ sở sức mạnh bên trong mà tranh thủ và tận dụng sự đồng tình, ủng hộ rộng rãi của lực lượng bên ngoài","Tất cả các đáp án"],"dung":"C"},{"id":315,"chuong":5,"cauHoi":"Theo Hồ Chí Minh, đại đoàn kết dân tộc không phải sách lược hay thủ đoạn chính trị, mà là:","dapAn":["Chiến lược ngắn hạn, nhất quán của cách mạng Việt Nam","Chiến lược lâu dài, có thể điều chỉnh phù hợp điều kiện cách mạng Việt Nam","Chiến lược lâu dài, nhất quán của cách mạng Việt Nam","Chiến lược ngắn hạn, có thể điều chỉnh phù hợp điều kiện cách mạng Việt Nam"],"dung":"C"},{"id":316,"chuong":5,"cauHoi":"Hồ Chí Minh xác định vấn đề mang tính sống còn cần được duy trì trong cách mạng dân tộc dân chủ và cách mạng xã hội chủ nghĩa là:","dapAn":["Hội nhập kinh tế quốc tế","Chống giặc ngoại xâm","Đổi mới đất nước","Đại đoàn kết toàn dân tộc"],"dung":"D"},{"id":317,"chuong":5,"cauHoi":"Trước những yêu cầu và nhiệm vụ khác nhau của từng giai đoạn cách mạng, Hồ Chí Minh đã khẳng định không được thay đổi chủ trương đại đoàn kết dân tộc là vì vấn đề gì?","dapAn":["Đại đoàn kết là nhân tố góp phần vào thành bại của cách mạng","Đại đoàn kết là nhân tố quyết định thành bại của cách mạng","Đại đoàn kết là nhân tố phụ góp phần vào thành bại của cách mạng","Đại đoàn kết là nhân tố duy nhất quyết định thành bại của cách mạng"],"dung":"B"},{"id":318,"chuong":5,"cauHoi":"Trong mỗi giai đoạn cách mạng, Hồ Chí Minh yêu cầu, chính sách và phương pháp tập hợp đại đoàn kết có thể và cần thiết phải:","dapAn":["Điều chỉnh cho phù hợp với từng đối tượng khác nhau","Điều chỉnh cho phù hợp với các lực lượng cách mạng","Đều chỉnh cho phù hợp với các tầng trong xã hội","Điều chỉnh cho phù hợp với điều kiện tiến lên chủ nghĩa xã hội"],"dung":"A"},{"id":319,"chuong":5,"cauHoi":"Đối với Hồ Chí Minh, đại đoàn kết dân tộc, không chỉ là khẩu hiệu chiến lược mà còn là:","dapAn":["Động lực vật chất và tinh thần của cách mạng Việt Nam","Mục tiêu lâu dài của cách mạng Việt Nam","Sách lược lâu dài của cách mạng Việt Nam","Động lực bên trong và bên ngoài của cách mạng Việt Nam"],"dung":"B"},{"id":320,"chuong":5,"cauHoi":"Cách mạng là sự nghiệp của quần chúng, do quần chúng và vì quần chúng. Do đó, theo Hồ Chí Minh, đại đoàn kết dân tộc là yêu cầu như thế nào?","dapAn":["Thực tế của sự nghiệp cách mạng, của giai cấp nông dân trong sự nghiệp tự giải phóng","Tất yếu của sự nghiệp cách mạng, của giai cấp công nhân trong cuộc đấu tranh tự giải phóng","Khách quan của sự nghiệp cách mạng, của quân chúng nhân dân trong cuộc đấu tranh tự giải phóng","Khách quan của sự nghiệp cách mạng, của các tầng lớp trí thức trong cuộc đấu tranh tự giải phóng"],"dung":"C"},{"id":321,"chuong":5,"cauHoi":"Trong sự nghiệp cách mạng giải phóng dân tộc, Hồ Chí Minh khẳng định chủ thể khối đại đoàn kết dân tộc là gì?","dapAn":["Toàn thể giai cấp, tất cả những người Việt Nam yêu nước","Toàn thể nhân dân, tất cả những người Việt Nam yêu nước","Toàn thể tầng lớp, tất cả những người Việt Nam yêu nước","Toàn thể cộng đồng, tất cả những người Việt Nam yêu nước"],"dung":"B"},{"id":322,"chuong":5,"cauHoi":"Cụm từ \"Nhân dân\" trong tư tưởng Hồ Chí Minh về đại đoàn kết dân tộc vừa được hiểu thế nào?","dapAn":["Là con người Việt Nam cụ thể, vừa là tập hợp đông đảo các tầng lớp trong xã hội","Là con người Việt Nam cụ thể, vừa là tập hợp đông đảo các giai cấp trong xã hội","Là con người Việt Nam cụ thế, vừa là tập hợp đông đảo quần chúng nhân dân","Là con người Việt Nam cụ thể, vừa là tập hợp đông đảo những người dân lao động trong xã hội"],"dung":"C"},{"id":323,"chuong":5,"cauHoi":"Khi thực hiện đại đoàn kết dân tộc, Hồ Chí Minh yêu cầu cần phải tiến hành như thế nào?","dapAn":["Phải tập hợp, đoàn kết tất cả mọi người dân vào một khối thống nhất","Phải tập hợp, đoàn kết tất cả mọi giai cấp vào khối thống thống nhất","Phải tập hợp, đoàn kết tất cả mọi lực lượng thành một khối thống nhất","Phải tập hợp, đoàn kết tất cả mọi tầng lớp vào một khối thống nhất"],"dung":"A"},{"id":324,"chuong":5,"cauHoi":"Theo Hồ Chí Minh, Mặt trận dân tộc thống nhất có vai trò như thế nào?","dapAn":["Là nơi quy tụ mọi tổ chức, cá nhân yêu nước, tập hợp mọi người dân nước Việt","Là nơi quy tụ, tập hợp người dân Việt Nam trong nước, có lòng yêu nước","Là nơi quy tụ, tập hợp người dân Việt Nam ngoài nước, có lòng yêu nước","Là nơi quy tụ mọi tổ chức, người dân Việt Nam ở nước ngoài có lòng yêu nước"],"dung":"A"},{"id":325,"chuong":5,"cauHoi":"Theo Hồ Chí Minh, nguyên tắc nào được xác định là nguyên tắc cốt lỗi trong chiến lược thực hiện đại đoàn kết dân tộc ở nước ta?","dapAn":["Phải được xây dựng trên nền tảng liên minh công nhân - nông dân - trí thức được đặt dưới lãnh đạo của Đảng","Phải xuất phát từ mục tiêu vì nước, vì dân dựa trên nền tảng liên minh công - nông - trí vững chắc","Phải hoạt động trên nguyên tắc bằng đẳng, đôi bên cùng có lợi và đặt dưới sự lãnh đạo của Đảng","Phải đoàn kết lâu dài, chặt chẽ, đoàn kết thực sự, chân thành, thân ái giúp đỡ nhau cùng tiến bộ"],"dung":"A"},{"id":326,"chuong":5,"cauHoi":"Nguyên tắc được Hồ Chí Minh xác định là bất di bất dịch trong thực hiện đại đoàn kết dân tộc là?","dapAn":["Phải lấy lợi ích tối cao của dân tộc, lợi ích căn bản của nhân dân làm mục tiêu phấn đầu","Phải lấy lợi ích của giai cấp, lợi ích căn bản của tầng lớp trí thức làm mục tiêu phấn đáu","Phải lấy lợi ích tối cao của dân tộc, lợi ích căn bản của giai cấp công nhân làm mục tiêu phấn đấu","Phải lấy lợi ích tối cao của dân tộc, lợi ích căn bản của giai cấp nông dân làm mục tiêu phấn đấu"],"dung":"A"},{"id":327,"chuong":5,"cauHoi":"Theo Hồ Chí Minh, sức mạnh thời đại được xác định là sức mạnh của những yếu tố nào?","dapAn":["Sức mạnh phong trào cách mạng thế giới, sức mạnh tư tưởng dần chủ tư sản","Sức mạnh phong trào cách mạng thế giới, sức mạnh văn hóa phương Đông","Sức mạnh phong trào cách mạng thế giới, sức mạnh chủ nghĩa Mác - Lênin","Sức mạnh phong trào cách mạng thế giới, sức mạnh văn hóa phương Tây"],"dung":"C"},{"id":328,"chuong":5,"cauHoi":"Trong hành trình tìm con đường cứu nước, Hồ Chí Minh xác định cách mạng Việt Nam chỉ có thể thành công khi thực hiện đoàn kết chặt chẽ với:","dapAn":["Phong trào cách mạng thế giới","Phong trào cách mạng vô sản trên thế giới","Phong trào cách mạng tư sản trên thế giới","Phong trào đấu tranh chống đế quốc trên thế giới"],"dung":"A"},{"id":329,"chuong":5,"cauHoi":"Theo Hồ Chí Minh, thực hiện đoàn kết quốc tế nhằm góp phần cùng nhân dân thế giới thực hiện thắng lợi gì?","dapAn":["Các mục tiêu giải phóng dân tộc trên thế giới","Các mục tiêu cách mạng của thời đại","Các mục tiêu giải phóng giai cấp trên thế giới","Các mục tiêu dân chủ, tiến bộ trên thế giới"],"dung":"B"},{"id":330,"chuong":5,"cauHoi":"Theo Hồ Chí Minh, thực hiện đoàn kết quốc tế nhằm thực hiện thắng lợi mục tiêu chung nào?","dapAn":["Hòa bình, độc lập dân tộc, dân chủ và tiến bộ xã hội","Hòa bình, thống nhất dân tộc, dân chủ và chủ nghĩa xã hội","Hòa bình, độc lập dần tộc, toàn vẹn lãnh thổ và chủ nghĩa xã hội","Hòa bình, bình đẳng dân tộc, chủ nghĩa xã hội, tiến bộ xã hội"],"dung":"A"},{"id":331,"chuong":5,"cauHoi":"Muốn tăng cường đoàn kết quốc tế trong cuộc đấu tranh chung, theo Hồ Chí Minh cần phải đầu tranh chống lại khuynh hướng nào làm suy yếu sức mạnh đoàn kết, thống nhất các lực lượng cách mạng thế giới?","dapAn":["Chủ nghĩa nước lớn, cực đoan, sô vanh","Chủ nghĩa cơ hội, vị kỷ dân tộc, sô vanh","Chủ nghĩa cơ hội, nước lớn, cực đoan","Chủ nghĩa dân tộc, nước lớn, cực đoan"],"dung":"B"},{"id":332,"chuong":5,"cauHoi":"Theo Hồ Chí Minh, đoàn kết với lực lượng nào là một đảm bảo vững chắc cho thắng lợi chủ nghĩa cộng sản?","dapAn":["Lực lượng tiền bộ, những người yêu chuộng hòa bình, dân chủ, tự do và công lý","Các nước trong phong trào đấu tranh giải phóng dân tộc","Phong trào cộng sản và công nhân quốc tế","Các nước láng giềng"],"dung":"C"},{"id":333,"chuong":5,"cauHoi":"Muốn thực hiện được nguyên tắc đoàn kết quốc tế trên cơ sở độc lập, tự chủ theo Hồ Chí Minh cần phải:","dapAn":["Có nội lực tốt; Đảng phải lãnh đạo nhân dân thực hiện đường lối đối ngoại","Có nội lực tốt; Đảng phải không ngừng mở rộng hợp tác quốc tế","Có nội lực tốt; Đảng phải có đường lối độc lập, tự chủ, đúng đắn","Có nội lực tốt; Đảng phải xây dựng đường lối hội nhập kinh tế quốc tế"],"dung":"C"},{"id":334,"chuong":5,"cauHoi":"Với các lực lượng tiến bộ trên thế giới, Hồ Chí Minh khẳng định mục tiêu chung trong đoàn kết là gì?","dapAn":["Giương cao ngọn cờ hình bình, hợp tác cùng phát triển","Giương cao ngọn cờ hòa bình, độc lập dân tộc","Giương cao ngọn cờ hòa bình, chống chiến tranh xâm lược","Giương cao ngọn cờ hòa bình, độc lập dân tộc và chủ nghĩa xã hội"],"dung":"C"},{"id":335,"chuong":5,"cauHoi":"Đối với phong trào cộng sản và công nhân quốc tế, Hồ Chí Minh xác định đoàn kết trên cơ sở giương cao ngọn cờ:","dapAn":["Mục tiêu giải phóng dân tộc; nền tảng chủ ngĩa Mác - Lênin; chủ nghĩa vô sản có lý, có tình","Độc lập dân tộc gắn liền với chủ nghĩa xã hội; nền tảng nghĩa Mác - Lênin; chủ nghĩa vô sản có lý, có tình","Mục tiêu hòa bình, tiến bộ xã hội; nền tảng chủ nghĩa Mác - Lênin; chủ nghĩa vô sản có lý, có tình","Mục tiêu độc lập, dân chủ, tiến bộ xã hội; nền tảng chủ nghĩa Mác - Lênin; chủ nghĩa vô sản có lý, có tình"],"dung":"B"},{"id":336,"chuong":5,"cauHoi":"Khi thực hiện đoàn kết với các dân tộc trên thế giới, Hồ Chí Minh xác định mục tiêu chung trong đoàn kết là gì?","dapAn":["Giương cao ngọn cờ độc lập tự do và quyền bình đẳng giữa các dân tộc","Giương cao ngọn cờ độc lập dân tộc gắn liền với chủ nghĩa xã hội","Giương cao ngọn cờ độc lập, tự do; chủ nghĩa vô sản có lý, có tình","Giương cao ngọn cờ độc lập, hòa bình, công lý, chồng chiên tranh xâm lược"],"dung":"A"},{"id":337,"chuong":5,"cauHoi":"Để thực hiện đoàn kết quốc tế trên cơ sở độc lập, tự chủ, trong dầu trành giành chính quyền, Hồ Chí Minh đã đề ra chủ trương gì?","dapAn":["Muốn người ta giúp cho, thì trước hết mình phải tự giúp mình đã","Tự lực cánh sinh, dựa vào sức mình là chính","Đem sức ta mà tự giải phóng cho ta","Dân tộc ngồi chờ dân tộc khác giúp đỡ dân tộc đó không xứng đáng độc lập"],"dung":"C"},{"id":338,"chuong":5,"cauHoi":"Theo Hồ Chí Minh, hoạt động theo nguyên tắc hiệp thương dân chủ sẽ quy tụ được lực lượng nào vào Mặt trận dân tộc thống nhất?","dapAn":["Các tầng lớp, giai cấp, nhân dân bị áp bức trên thế giới","Các tầng lớp, giai cấp, các dân tộc bị áp bức","Các tầng lớp, giai cấp, đảng phái, dân tộc, tôn giáo","Các tầng lớp, giai cấp, các lực lượng yêu chuộng hòa bình"],"dung":"C"},{"id":339,"chuong":5,"cauHoi":"Điều kiện đại đoàn kết dân tộc phải có niềm tin vào nhân dân trong quan điểm Hồ Chí Minh là sự tiếp nối truyền thống nào của dân tộc?","dapAn":["Yêu nước, kiên cường, bất khuất, tự tôn dân tộc","Nhân nghĩa, thương người như thể thương thân, lá lành đùm lá rách","Hòa hiếu, hữu nghị, bao dung","\"Nước lấy dân làm gốc\", \"Chở thuyền và làm lật thuyền cũng là dân\""],"dung":"D"},{"id":340,"chuong":5,"cauHoi":"Theo Hồ Chí Minh, mục đích của vận động quần chúng là gì?","dapAn":["Đoàn kết các tầng lớp, tạo ra động lực phát triển xã hội, hội nhấp quốc tế","Đoàn kết giai cấp, tạo động lực đánh thắng giặc ngoại xâm","Đoàn kết xã hội, tạo ra nội lực để hợp tác quốc tế","Đoàn kết mọi người, tạo ra động lực phát triển kinh tế, văn hóa, xã hội"],"dung":"D"},{"id":341,"chuong":5,"cauHoi":"Theo Hồ Chí Minh, mọi phương pháp tiếp cận và vận động quần chúng cần phải được thực hiện như thế nào?","dapAn":["Xuất phát từ tâm tư, nguyện vọng; thực tế trình độ dân trí, văn hóa của quần chúng","Xuất phát từ vai trò, vị trí; thực tế trình độ dân trí, văn hóa của quần chúng","Xuất phát từ điều kiện, khả năng; thực tế trình độ dân trí, văn hóa của quần chúng","Xuất phát từ nhu cầu, nguyện vọng, khả năng thực tế của quần chúng"],"dung":"A"},{"id":342,"chuong":5,"cauHoi":"Khi nói về sự cần thiết phải đoàn kết quốc tế, Hồ Chí Minh đã khẳng dịnh thực hiện đoàn kết quốc tế nhằm mục tiêu gì?","dapAn":["Kết hợp sức mạnh dân tộc với sức mạnh thời đại, tạo sức mạnh tổng hợp cho cách mạng","Kết hợp sức mạnh vật chất với sức mạnh tinh thần, tạo ra sức mạnh tổng hợp cho cách mạng","Kết hợp sức mạnh kinh tế với sức mạnh văn hóa, tạo ra sức mạnh tổng hợp cho cách mạng","Kết hợp sức mạnh truyền thống với sức mạnh hiện đại, tạo ra sức mạnh tổng hợp cho cách mạng"],"dung":"A"},{"id":343,"chuong":5,"cauHoi":"Thời đại Hồ Chí Minh sống và hoạt động là thời đại như thế nào?","dapAn":["Chấm dứt áp bức, bóc lột, bất công, mở ra quan hệ quốc tế sâu rộng","Chấm dứt chế độ nô lệ, mở ra quan hệ quốc tế sâu rộng","Chấm dứt sự tồn tại biệt lập giữa các quốc gia, mở ra quan hệ quốc tế sâu rộng","Châm dứt xâm lược, dành độc lập cho các dân tộc, mở ra quan hệ quốc tế sâu rộng"],"dung":"C"},{"id":344,"chuong":5,"cauHoi":"Chủ trương đoàn kết giai cấp công nhân quốc tế, đoàn kết các đảng cộng sản trong tư tưởng Hồ Chí Minh xuất phát từ lý do nào sau?","dapAn":["Từ tính tất yếu về vai trò của giai cấp công nhân trong giai đoạn hiện nay","Từ tính tất yếu về số lượng giai cấp công nhân trong giai đoạn hiện nay","Từ tính tất yếu về chất lượng giai cấp công nhân trong giai giai đoạn hiện nay","Từ tính tất yếu về đặc điểm của giai cấp công nhân trong giai đoạn hiện nay"],"dung":"A"},{"id":345,"chuong":5,"cauHoi":"Theo Hồ Chí Minh, phương châm \"cầu đồng tồn dị\" về thực hiện đại đoàn kết dân tộc được hiểu như thề nào?","dapAn":["Lấy cái chung để hạn chế cái riêng, cái khác biệt","Lấy cái riêng để hạn chế cái chung, cái khác biệt","Lấy cái chung để hạn chế cái riêng, cái đơn nhất","Lấy cái riêng để hạn chế cái chung, cái đơn nhất"],"dung":"A"},{"id":346,"chuong":5,"cauHoi":"Theo Hồ Chí Minh, tại sao đại đoàn kết dân tộc phải được xác định là nhiệm vụ hàng đầu của Đáng?","dapAn":["Vì Đảng là lực lượng tuyên truyền quần chúng nhân dân","Vì Đảng là lực lượng vận động quần chúng nhân dân","Vì Đảng là lực lượng lãnh đạo cách mạng Việt Nam","Vì Đảng là lực lượng giáo dục, giác ngộ quần chúng nhân dân"],"dung":"C"},{"id":347,"chuong":5,"cauHoi":"Vì sao Hồ Chí Minh xác dịnh đại đoàn kết dân tộc phải đứng vững trên lập trường giai cấp công nhân?","dapAn":["Để giải quyết hài hòa mối quan hệ giai cấp, dân tộc để tập hợp lực lượng","Để giải quyết hài hòa mối quan hệ lợi ích kinh tế để tập hợp lực lượng","Để giải quyết hài hòa mối quan hệ lợi ích chính trị để tập hợp lực lượng","Để giải quyết hài hòa mối quan hệ lợi ích văn hóa để tập hợp lực lượng"],"dung":"A"},{"id":348,"chuong":5,"cauHoi":"Theo Hồ Chí Minh, vì lợi ích của sự nghiệp cách mạng trong thực hiện đại đoàn kết dân tộc cần phải có:","dapAn":["Lòng khoan dung đại độ, trân trọng phần thiện dù nhỏ nhất ở mỗi người","Lòng khoan dung đại độ, trân trọng quyền dù nhỏ nhất ở mỗi người","Lòng khoan dung đại độ, trân trọng nhu cầu dù nhỏ nhất ở mỗi người","Lòng khoan dung đại độ, trân trọng nguyện vọng dù nhỏ nhất ở mỗi người"],"dung":"A"},{"id":349,"chuong":5,"cauHoi":"Theo Hồ Chí Minh, tại sao trong thực hiện đại đoàn kết dân tộc cần phải Khoan dung, độ lượng với con người?","dapAn":["Trong mỗi giai cấp, cũng như tầng lớp đều có những ưu điểm, khuyết điểm","Trong mỗi cá nhân, cũng như cộng đồng đều có những ưu điểm, khuyết điểm","Trong mỗi cá nhân, cũng như giai cấp đều có những ưu điểm, khuyết điểm","Trong mỗi giai cấp, cũng như tập thể đều có những ưu điểm, khuyết điểm"],"dung":"B"},{"id":350,"chuong":5,"cauHoi":"Chọn đáp án đúng nhất về vấn đề được xem là nguyên tắc tồi cao trong cuộc sống của Chủ tịch Hồ Chí Minh?","dapAn":["Yêu dân, tin dân, dựa vào dân, phấn đấu vì hạnh phúc nhân dân","Yêu dân, tin dân, dựa vào dân, phần đấu vì đời sống tinh thần của nhân dân","Yêu dân, tin dân, dựa vào dân, phấn đấu vì đời sống vật chất của nhân dân","Yêu dân, tin dân, dựa vào dân, phấn đấu giải phóng nhân dân khói áp bức, bóc lột"],"dung":"A"},{"id":351,"chuong":5,"cauHoi":"Vì sao trong sự nghiệp cách mạng Hồ Chí Minh khẳng định đại đoàn kết dân tộc phải tin vào nhân dân?","dapAn":["Dân có quyền hưởng những thành quả của sự nghiệp đổi mới đất nước","Dân biết, dân bàn, dân làm, dân kiểm tra và dân thụ hưởng","Dân là chỗ dựa vững chắc, nguồn sức mạnh, quyết định thắng lợi cách mạng","Dân cần không ngừng được nâng cao về đời sống về vật chất, tinh thần"],"dung":"C"},{"id":352,"chuong":5,"cauHoi":"Tại sao Hồ Chí Minh khăng định phải tiến hành thực hiện hiệp thương dân chủ trong xây dựng và hoạt động của Mặt trận dân tộc thông nhất?","dapAn":["Mặt trận dân tộc thông nhất là tổ chức chính trị - xã hội rộng lớn của giai cấp nông dân bao gồm người việt trong nước, ngoài nước..., nhiều tâm tư khác nhau","Mặt trận dân tộc thồng nhất là tổ chức chính trị - xã hội rộng lớn của giai cấp công nhân, bao gôm nhiều dân tộc, tôn giáo..., với nhiều nguyện vọng khác nhau","Mặt trận dân tộc trận dân tộc thông nhất là tố chức chính trị- xã hội rộng lớn của nhân dân, bao gồm nhiều giai cấp, tầng lớp..., với nhiều lợi ích khác nhau","Mặt trận dân tộc thống nhất là tổ chức chính trị - xã hội rộng lớn của tầng lớp trí thức, bao gồm nhiều đảng phái, giai cấp..., nhiều nhu cầu khác nhau"],"dung":"C"},{"id":353,"chuong":5,"cauHoi":"Vì sao từ rất sớm Hồ Chí Minh chủ trương đoàn kết với các nước trong phong trào đấu tranh giải phóng dân tộc?","dapAn":["Nhận thấy rõ âm mưu chống phá dân tộc của các nước đế quốc","Nhận thấy rõ âm mưu lợi dụng dân tộc của các nước đế quốc","Nhận thấy rõ âm mưu chia rẽ dân tộc của các nước để quốc","Nhận thấy rõ âm mưu xâm lược dân tộc của các nước đế quốc"],"dung":"C"},{"id":354,"chuong":5,"cauHoi":"Để tập hợp và tranh thủ sự ủng hộ của các lực lượng tiến bộ trên thế giới, Hồ Chí Minh đã nêu cao ngọn cờ gì?","dapAn":["Hòa bình, độc lập, chủ nghĩa xã hội","Hòa bình, dân chủ và chủ nghĩa xã hội","Hòa bình, hợp tác và phát triển","Hòa bình, tự do, công lý và bình đẳng"],"dung":"D"},{"id":355,"chuong":5,"cauHoi":"Theo Hồ Chí Minh, gắn cuộc đấu tranh vì độc lập của dân tộc với mục tiều hòa bình, tự do và công lý nhằm tạo ra tiềng nói ủng hộ từ lực lượng nào?","dapAn":["Các tổ chức quần chúng, nhân sĩ trí thức và từng con người trên hành tinh","Các nước, các tổ chức, từng con người trên hành tinh","Các tổ chức, chính phủ, cá nhân trên hành tinh","Các nước mất độc lập dân tộc và từng con người trên hành tinh."],"dung":"A"},{"id":356,"chuong":5,"cauHoi":"Đoàn kết quốc tế được Hồ Chí Minh xác định không phải là sách lược, thủ đoạn chính trị nhất thời, mà là:","dapAn":["Vấn đề có tính nguyên tắc, đòi hỏi chủ quan của cách mạng Việt Nam","Vấn đề có thể thay đổi cho phù hợp với thực tiễn khách quan Việt Nam","Vấn đề có tính nguyên tắc, đòi hồi khách quan của cách mạng Việt Nam","Vấn đề không có tính nguyên tắc, đòi hỏi khách quan của cách mạng Việt Nam"],"dung":"C"},{"id":357,"chuong":5,"cauHoi":"Tại sao trong quá trình đầu tranh chống giặc ngoại xôm, Hồ Chí Minh dành sự quan tâm đặc biệt đối với các dân tộc trên bán đảo Đông Dương?","dapAn":["Là láng giếng, cùng chung chế độ chính trị, kinh tế, xã hội, chung kè thù là thực dân Mỹ","Là láng giềng, cùng chung chế độ chính trị, chung kẻ thủ là thực dân Pháp","Là láng giềng, tương đồng về văn hóa, lịch sử, chung kẻ thủ là thực dân Anh","Là láng giềng, tương đồng về văn hóa, lịch sử, chung kẻ thù là thực dân Pháp"],"dung":"D"},{"id":358,"chuong":5,"cauHoi":"Xác định nguyên tắc đoàn kết quốc tế theo quan điểm Hồ Chí Minh?","dapAn":["Đoàn kết trên cơ sở thống nhất mục tiêu và lợi ích; có lý, có tình","Đoàn kết trên cơ sở thống nhất mục tiêu, lợi ích; hợp tác cùng phát triên","Đoàn kết trên cơ sở bình đẳng, tôn trọng độc lập, chủ quyền, thống nhất, toàn vẹn","Đoàn kết trên cơ sở hòa bình, hữu nghị, hợp tác, phát triền; độc lập, tự chủ"],"dung":"A"},{"id":359,"chuong":5,"cauHoi":"Theo Hồ Chí Minh, cơ sở để đoàn kết quốc tế trong cuộc đấu tranh chống chủ nghĩa đế quốc và các lực lượng phản động quốc tế là gì?","dapAn":["Tìm điểm tương đồng về mục tiêu đấu tranh giải phóng giữa các dân tộc","Tìm điểm tương đồng về lợi ích vật chất và tinh thần giữa các dân tộc, lực","Tìm điểm tương đồng về mục tiêu và lợi ích giữa các dân tộc, lực lượng tiến","Tìm điêm tương đồng về mục tiêu, nhiệm vụ giải quyết các vấn đề nhân loại lượng bộ đặt ra"],"dung":"C"},{"id":360,"chuong":5,"cauHoi":"Hồ Chí Minh xác định quan điểm có tính nguyên tắc trong thực hiện quan hệ giữa Việt Nam với các nước trên thế giới là gì?","dapAn":["Tôn trọng quyền tự quyết, quyền độc lập dân tộc, dân chủ và chủ nghĩa xã hội của tất cả các dân tộc, quốc gia trên thế giới và ngược lại","Tôn trọng hòa bình, độc lập dân tộc, dân chủ và chủ nghĩa xã hội của tất cả các dân tộc, quốc gia trên thế giới và ngược lại","Tôn trọng độc lập, chủ quyền, thống nhất, toàn vẹn lãnh thổ và quyền tự quyết của tất cả các dân tộc, quốc gia trên thế giới và ngược lại","Tôn trọng độc lập, chủ quyền, dân chủ, chủ nghĩa xã hội, quyền tự quyết của"],"dung":"C"},{"id":361,"chuong":5,"cauHoi":"Theo Hô Chí Minh, cơ sở đề giương cao ngọn cờ hòa bình, chống chiến tranh xâm lược trong đoàn kết với các lượng tiến bộ trên thế giới bắt nguồn từ đâu?","dapAn":["Truyền thống hòa hiếu của dân tộc, chủ nhĩa nhân đạo cộng sản, giá trị nhân văn nhân loại","Truyền thống đoàn kết của dân tộc, chủ nhĩa nhân đạo cộng sản, giá trị nhân văn nhân loại","Truyền thống yêu nước của dân tộc, chủ nhĩa nhân đạo cộng sản, giá trị nhân văn nhân loại","Truyền thống nhân nghĩa của dân tộc, chủ nhĩa nhân đạo cộng sản, giá trị nhân văn nhân loại"],"dung":"A"},{"id":362,"chuong":5,"cauHoi":"Quán triệt tư tưởng Hồ Chí Minh và nhận thức rõ tầm quan trọng của vấn đề đại đoàn kết toàn dân tộc, ngày 2-11-1993, Bộ Chính trị Trung ương Đảng khóa VII đã đưa ra Nghị quyết 07/NQ-TW về vấn đề gì?","dapAn":["\"Về đại đoàn kết dân tộc và tăng cường Mặt trận dân tộc thống nhất\"","\"Về đoàn kết quốc tế và tăng cường hội nhập kinh tế quốc tế\"","\"Về đại đoàn kết dân tộc và tăng cường đoàn kết quốc tế\"","\"Về đại đoàn kết dân tộc và tăng cường liên minh công - nông - trí\""],"dung":"A"},{"id":363,"chuong":5,"cauHoi":"Đại hội lần thứ XII của Đảng (2016) đã khẳng định: \"Đại đoàn kết dân tộc là đường lối chiến lược của cách mạng Việt Nam, là... to lớn trong xây dựng và bảo vệ Tổ quốc \"66. Xác định cụm từ còn thiếu?","dapAn":["Sức mạnh và nguồn lực","Động lực và sức mạnh","Động lực và nguồn lực","Động lực vật chất và tinh thần"],"dung":"C"},{"id":364,"chuong":5,"cauHoi":"Vận dụng tư tưởng Hồ Chí Minh, Đại hội XII của Đảng đã xác định điểm tương đồng nào để tăng cường khối đại đoàn kết toàn dân tộc trong giai đoạn hiện","dapAn":["Mục tiêu thực hiện thắng lợi đường lối đổi mới và hội nhập quốc tế thành công, \"dân giàu, nước mạnh, dân chủ, công bằng, văn minh\"","Mục tiêu xây dựng nền kinh tế phát triển cao, khoa học công nghệ hiện đại, \"dân giàu, nước mạnh, dân chủ, công bằng, văn minh\"","Mục tiêu giữ vững độc lập dân tộc, xây dựng chủ nghĩa xã hội, \"dân giâu, nước mạnh, dân chủ, công bằng, văn minh\"","Mục tiêu xây dựng nước Việt Nam hòa bình, độc lập, thống nhất, toản vẹn lãnh thổ, \"dân giàu, nước mạnh, dân chủ, công bằng, văn minh\""],"dung":"D"},{"id":365,"chuong":5,"cauHoi":"Bài học đầu tiên được Đảng ta rút ra từ chiến lược đoàn kết quốc tế của Hồ Chí Minh trong điều kiện mới của đất nước hiện nay là gì?","dapAn":["Đoàn kết quốc tế để thực hiện mục tiêu cách mạng hiện nay là dân giàu, nước mạnh, dân chủ, xã hội công bằng, văn minh","Đoàn kết quốc tế để thực hiện mục tiêu không ngừng nâng cao vị thế, uy tín của Việt Nam trên trường quốc tế","Đoàn kết quốc tế để thực hiện mục tiêu tận dụng nguồn vốn, khoa học công nghệ, kinh nghiệm quản lý quốc tế để phát triển đất nước","Đoàn kết quốc tế để thực hiện mục tiêu phát triển kinh tế, văn hóa, xã hội, an ninh - quốc phòng của đất nước"],"dung":"A"},{"id":366,"chuong":5,"cauHoi":"Tại sao Hồ Chí Minh khẳng định đại đoàn kết là yêu cầu khách quan của sự nghiệp cách mạng, là đòi hỏi khách quan của quần chúng nhân dân trong đấu tranh tự giải phóng?","dapAn":["Bởi vì nhờ đoàn kết quần chúng nhân dân trở thành người lãnh đạo sự nghiệp cách mạng Việt Nam","Bởi vì nhờ đoàn kết quần chúng nhân dân trở thành người quản lý sự nghiệp xây dựng, phát triến đất nước","Bởi vì nếu không đoàn kết quần chúng nhân dân sẽ thất bại trong cuộc đầu tránh vì lợi ích của chính mình cầm quyền lực nhà nước","Bởi vì nếu không đoàn kết quần chúng nhân dân sẽ không giữ vai trò"],"dung":"C"},{"id":367,"chuong":5,"cauHoi":"Từ nhận thức nào sau đây, Hồ Chí Minh xác định sứ mệnh của Đảng cần thức tỉnh, tập hợp, hướng dẫn quần chúng thành hiện thực có tổ chức trong khối đoàn kết, thành sức mạnh tổng hợp trong đấu tranh là gì?","dapAn":["Đoàn kết là yêu cầu khách quan của sự nghiệp đấu tranh giải phóng dân tộc, là đòi hỏi khách quan của quần chúng trong đoàn kết quốc tế","Đoàn kết là yêu cầu khách quan của sự nghiệp cách mạng, là đòi hồi khách quan của quần chúng nhân dân trong cuộc đấu tranh tự giải phóng","Đoàn kết là yêu cầu khách quan của sự nghiệp kháng chiến chống đế quốc Mỹ, là đòi hỏi khách quan của hội nhập kinh tế quốc tế","Đoàn kết là yêu cầu khách quan của sự nghiệp đổi mới đất nước, là yêu cầu khách quan trong thực hiện quan hệ quốc tế"],"dung":"B"},{"id":368,"chuong":5,"cauHoi":"Điều kiện đại đoàn kết dân tộc phải có niềm tin vào nhân dân trong quan điểm Hồ Chí Minh là sự tiếp nối truyền thống nào của dân tộc?","dapAn":["Yêu nước, kiên cường, bất khuất, tự tôn dân tộc","Nhân nghĩa, thương người như thể thương thân, lá lành đùm lá rách","Hòa hiếu, hữu nghị, bao dung","\"Nước lấy dân làm gốc\", \"Chở thuyền và làm lật thuyền cũng là dân\""],"dung":"D"},{"id":369,"chuong":5,"cauHoi":"Tại sao Hồ Chí Minh xác định lấy liên minh công nông làm nền tảng của Mặt trận dân tộc thống nhất?","dapAn":["Vì công nông là người trực tiếp sản xuất tất cả mọi tài phú; họ đông hơn hết, bị bóc lột nặng nề hơn hết; chí khí cách mạng chắc chắn, bền bi hơn mọi tầng lớp khác","Vì công nông là lực lượng lãnh đạo cách mạng; họ đông hơn hết, bị bóc lột nặng nề hơn hết; chí khí cách mạng chắc chắn, bền bỉ hơn mọi tầng lớp khác","Vì công nông là lược lượng đại diện cho phương thức sản xuất hiện đại; họ đông hơn hết, bị bóc lột nặng nề hơn hết; chí khí cách mạng chắc chắn, bền bi hơn mọi tầng lớp khác","Vì công nông không có tài sản, của cải của riêng; họ đông hơn hết, bị bóc lột nặng nề hơn hết; chí khí cách mạng chắc chắn, bền bỉ hơn mọi tầng lớp khác"],"dung":"A"},{"id":370,"chuong":5,"cauHoi":"Theo Hồ Chí Minh hoạt động của Mặt trận phải theo nguyên tắc nào mới quy tụ được các tầng lớp, giai cấp, đảng phái, dân tộc, tôn giáo vào Mặt trận dân tộc thống nhất?","dapAn":["Tập trung dân chủ","Hiệp thương dân chủ","Tự phê bình và phê bình","Đoàn kết thống nhất"],"dung":"B"},{"id":371,"chuong":5,"cauHoi":"Tại sao Hồ Chí Minh lại khẳng định thực hiện đoàn kết quốc tế góp phần thực hiện thắng lợi các mục tiêu của thời đại?","dapAn":["Vì nhân dân, Việt Nam không chỉ bảo vệ lợi ích sống còn của dân tộc mình mà còn vì mục tiêu thời đại là hòa bình độc lập dân tộc, dân chủ và chủ nghĩa xã hội","Vì nhân dân Việt Nam tích cực cùng nhân dân thế giới giải quyết những vấn biến đổi khí hậu và nước biển dâng","Vì nhân dân Việt Nam tích cực cùng nhân dân thế giới giải quyết những bất đồng, xung đột dân tộc, tôn giáo đề lập lại hòa bình trên thế giới","Vì nhân dân Việt Nam tích cực mở rộng giao lưu, hợp tác với nhân dân trên thế giới với tinh thần hợp tác cùng có lợi"],"dung":"A"},{"id":372,"chuong":5,"cauHoi":"Theo Hồ Chí Minh chỉ có sức mạnh của sự đoàn kết, nhất trí, sự đồng tình và ủng hộ lẫn nhau của lao động toàn thế giới theo tinh thần như thế nào mới có thể chống lại được những âm mưu thâm độc của chủ nghĩa để quốc thực dân?","dapAn":["\"Bốn phương vô sản đều là anh em\"","\"Không có gì quý hơn độc lập, tự do!\"","\"Dễ trăm lần không dân cũng chịu, khó vạn lần dân liệu cũng xong\"","\"Cho dù có phải đốt cháy cả dãy Trường Sơn cũng phải giành cho được độc lập!\""],"dung":"A"},{"id":373,"chuong":5,"cauHoi":"Quán triệt tư tưởng Hồ Chí Minh về đại đoàn kết dân tộc và đoàn kết quốc tế trong hoạch định chú trương, đường lối của Đảng hiện nay cần phải khơi dậy và phát huy đến mức cao nhất sức mạnh nào sau đây?","dapAn":["Sức mạnh kinh tế và sức mạnh chính trị","Sức mạnh dân tộc và sức mạnh khoa học công nghệ","Sức mạnh ngoại giao và sức mạnh quốc tế","Sức mạnh dân tộc và sức mạnh quốc tế"],"dung":"D"},{"id":374,"chuong":5,"cauHoi":"Quán triệt tư tưởng Hồ Chí Minh về đại đoàn kết dân tộc và đoàn kốt quốc tế trong hoạch định chủ trương, đường lối của Đảng cần phải khơi đậy và phát huy đến mức cao độ sức mạnh dân tộc và sức mạnh quốc tế, trong đó:","dapAn":["Đặt lợi ích dân tộc, đất nước lên hàng đầu, lấy. đó làm cơ sở để xây dựng các chủ trương, chính sách kinh tế - xã hội","Đặt lợi ích giai cấp, đối tác chiến lược lên hàng đầu, lấy đó làm cơ sở để xây dựng các chủ trương, chính sách kinh tế - xã hội","Đặt lợi ích quốc tế, bạn bè truyền thống lên hàng đầu, lầy đó làm cơ sở để xây dựng các chủ trương, chính sách kinh tế - xã hội","Đặt lợi ích phong trào cách mạng vô sản lên hàng đầu, lấy đó làm cơ sở để xây dựng các chủ trương, chính sách kinh tế - xã hội"],"dung":"A"},{"id":375,"chuong":5,"cauHoi":"Nghị quyết nào sau đây đã phản ánh tập trung nhất sự kế thừa và phát triển tư tưởng Hồ Chí Minh về đại đoàn kết trong sự nghiệp đổi mới?","dapAn":["Nghị quyết số 08-NQ/HNTW Hội nghị lần thứ tám BCHTW Đảng khóa VII về tiếp tục xây dựng và hoàn thiện Nhà nước Cộng hòa XHCN Việt Nam, trọng tâm là cải cách một bước nền hành chính, ngày 23/1/1995","Nghị quyết Hội nghị lần thứ hai Ban Chấp hành Trung ương Đảng (khóa VII) số 02-NQ/HNTW về nhiệm vụ và giải pháp ổn định, phát triển kinh tế - xã hội trong những năm 1992 - 1995, ngày 4-12-1991","Nghị quyết số 03- NQ/TW của Hội nghị lần thứ ba, Ban Chấp hành Trung ương Đảng (khóa VII) Về một số nhiệm vụ đổi mới và chinh đốn Đảng, ngày 26/6/1992","Nghị quyết 07/NQ-TW \"Về đại đoàn kết dân tộc và tăng cường Mặt trận dân tộc thống nhất\", ngày 2-11-1993"],"dung":"D"},{"id":376,"chuong":5,"cauHoi":"Qua 35 năm đổi mới, tư tưởng đoàn kết quốc tế của Chủ tịch Hồ Chí Minh đã được vận dụng sáng tạo trong hoạch định chủ trương, đường lối đối ngoại thể hiện trong Đại hội lần thứ XIII (1.2021) của Đảng như thế nào?","dapAn":["Việt Nam là bạn, là đối tác tin cậy và là thành viên tích cực, có trách nhiệm trong cộng đồng quốc tế","Việt Nam muốn là bạn với tất cả các nước","Việt Nam sẵn sàng là bạn với tất cả các nước","Việt Nam sẵn sàng là bạn và đối tác tin cậy với tất cả nước"],"dung":"A"},{"id":377,"chuong":5,"cauHoi":"Vận dụng tư tưởng Hồ Chí Minh về đại đoàn kết dân tộc, Tổng bí Thư, Chủ tịch nước Nguyễn Phú Trọng kêu gọi đoàn kết để chiến thắng đại dịch Covid-19 đã khẳng định yếu tố nào giúp nước ta thời gian quan ngăn ngừa và kiểm soát dịch bệnh bước đầu có hiệu quả?","dapAn":["Sự ủng của quốc tế","Ý thức tự giác, chủ động của tất cả người dân trong phòng, chống dịch","Sự phối hợp hiệu quả, kịp thời với các nước trong phòng, chống dịch","Toàn dân ta đã đồng lòng, cùng chung sức với Đảng, Nhà nước"],"dung":"D"},{"id":378,"chuong":5,"cauHoi":"Vận dụng tư tưởng Hồ Chí Minh trong giai đoạn hiện này đại đoàn kết dân tộc cần phải kết hợp với:","dapAn":["Phát triển kinh tế","Phát triển xã hội","Đoàn kết quốc tế","Ôn định chính trị"],"dung":"C"},{"id":379,"chuong":5,"cauHoi":"Trong giai đoạn hiện nay, việc phát huy bài học kết hợp sức mạnh dân tộc với sức mạnh thời đại theo tư tưởng Hồ Chí Minh, phải nhất quán coi cách mạng Việt Nam là:","dapAn":["Một bộ phận không thể tác rời của cách mạng thế giới, tiếp tục đoàn kết, ủng hộ phong trào cách mạng, các xu hướng và trào lưu tiến bộ của thời đại","Một phần quan trọng của quá trình phát triển của nhân loại, tiếp tục kiên định mục tiêu tiến lên chủ nghĩa xã hội","Một bộ phận không thể tách rời khỏi mục tiêu của nhân loại tiến bộ, tiếp tục cùng nhân dẫn các nước thực hiện các mục tiêu thời đại","Một bộ phận không thê tách rời của cộng cuộc xây dựng chủ nghĩa xã hội trên thế giới, tiếp tục vững bước tiến lên chủ nghĩa xã hội"],"dung":"A"},{"id":380,"chuong":5,"cauHoi":"Vận dụng tư tưởng Hồ Chí Minh về đoàn kết quốc tế. ', đê nâng cao kiệu quả hợp tác quôc tề, chủ động hội nhập kinh tế với khu vực và thể giới, Đảng, Nhà nước chủ trương nêu cao nguyên tắc nào sau đây?","dapAn":["Độc lập tự chủ, tự lực tự cường","Hợp tác cùng có lợi","Tích cực, chủ động hội nhập quốc tế","Đa phương hóa, đa dạng hóa quan hệ quốc tế"],"dung":"A"},{"id":381,"chuong":5,"cauHoi":"Vận dụng tư tưởng Hồ Chí Minh đoàn kết quốc tế, Tổng bí Thư, Chủ tịch nước Nguyễn Phú Trọng kêu gọi đoàn kết để chiến thắng đại dịch Covid-19 đã khẳng định yếu tố nào là cơ sở bảo đảm chắc chắn cho chiến thắng cuối cùng của thế giới trước đại dịch?","dapAn":["Sự đoàn kết và phối hợp hành động toàn cầu\"9","Sự giúp đỡ của các nước phát triển với các nước kém phát triển","Sự hợp tác giữa các tổ chức quốc tế, đặc biệt là phát huy vai trò của Tổ chức Y tế Thế giới (WHO)","Phát huy vai trò chủ động của mỗi quốc gia"],"dung":"A"},{"id":382,"chuong":6,"cauHoi":"Nghị quyết 24C/18.6,5 của Khóa họp 24 Đại hội đồng UNESCO đã khẳng đinh: Chủ tịch Hồ Chí Minh để lại một (...) trong quá trình phát triển của nhân loại vì hòa bình, độc lập dân tộc, dân chủ và tiến bộ xã hội. Xác định cụm từ còn thiếu?","dapAn":["Đấu ấn","Hình ảnh","Hình tượng","Án tượng"],"dung":"A"},{"id":383,"chuong":6,"cauHoi":"Theo Hồ Chí Minh, văn hóa có vai trò gì trong đời sống xã hội?","dapAn":["Văn hóa là mục tiêu, động lực của sự nghiệp cách mạng","Văn hóa là một mặt trận","Văn hóa phục vụ quần chúng nhân dân","Tất cả các đáp án"],"dung":"D"},{"id":384,"chuong":6,"cauHoi":"Theo Hồ Chí Minh, văn hóa là mục tiêu, nghĩa là hướng tới:","dapAn":["Quyền sống, quyền sung sướng, quyền tự do, quyền mưu cầu hạnh phúc","Khát vọng về các giá trị chân, thiện, mĩ","Xã hội dân chủ, công bằng, văn minh","Tất cà các đáp án"],"dung":"D"},{"id":385,"chuong":6,"cauHoi":"Theo Hồ Chí Minh, văn hóa phục vụ quần chúng nhân dân, nghĩa là:","dapAn":["Mọi hoạt động văn hóa phải trở về với cuộc sống thực tại của quần chúng, phản ánh được tư tưởng, khát vọng của quần chúng","Miêu tả cho hay, cho chân thật, hùng hồn cuộc sống thực tế của quần chúng, từ đó định hướng giá trị cho quần chúng","Hiểu và đánh giá đúng quần chúng","Tất cả các đáp án"],"dung":"D"},{"id":386,"chuong":6,"cauHoi":"Hồ Chí Minh yêu cầu về tính dân tộc của nền văn hóa cần phải:","dapAn":["Giúp phân biệt, không nhầm lẫn với văn hóa của dân tộc khác","Giữ gìn, kế thừa, phát huy và phát triển truyền thống tốt đẹp của văn hóa dân tộc phù hợp với điều kiện lịch sử của đất nước","\"Lột tả được tinh thần dân tộc\", \"cốt cách của dân tộc, đặc tính của dân tộc\", đó là truyền thống yêu nước, nhân nghĩa, đoàn kết, khát vọng độc lập, tự chủ, tự cường","Tất cả các đáp án"],"dung":"D"},{"id":387,"chuong":6,"cauHoi":"Tính khoa học của nền văn hóa theo quan điểm Hồ Chí Minh được thể hiện ở những nội dung nào?","dapAn":["Tính hiện đại, tiên tiến, thuận với trào lưu tiến hóa của thời đại","Truyền bá tư tưởng triết học mácxít, đấu tranh chống lại chủ nghĩa duy tâm, thần bí","Kế thừa truyền thống tốt đẹp của dân tộc, tiếp thu tinh hoa văn hóa nhân loại","Tất cả các đáp án"],"dung":"D"},{"id":388,"chuong":6,"cauHoi":"Có tinh thần quốc tế trong sáng là một trong những chuẩn mực đạo đức được Hồ Chí Minh coi trọng. Tinh thần quốc tế trong sáng đó là gì?","dapAn":["Đó là tinh thần đoàn kết với giai cấp vô sản toàn thế giới","Đó là tinh thần đoàn kết với tất cả các dân tộc và nhân dân các nước","Đó là tinh thần đoàn kết với tất cả những người tiến bộ trên toàn cầu","Tất cả các đáp án"],"dung":"D"},{"id":389,"chuong":6,"cauHoi":"Theo Hồ Chí Minh, chữ \"Chính\" có nghĩa là gì?","dapAn":["Không ham quyền lực","Siêng năng, chăm chỉ","Không tham danh vọng","Thẳng thắn, đứng đắn"],"dung":"D"},{"id":390,"chuong":6,"cauHoi":"Hồ Chí Minh đề cập đạo đức trong những quan hệ nào của con người ?","dapAn":["Đối với mình","Đối với việc","Đối với người","Tất cả các đáp án"],"dung":"D"},{"id":391,"chuong":6,"cauHoi":"Luận điểm: \"Người cán bộ phải có đạo đức cách mạng.... Mọi việc thành hay bại, chủ chốt là do cán bộ có thấm nhuần đạo đức cách mạng, hay là không\"70, được viết trong tác phẩm nào của Hồ Chí Minh ?","dapAn":["Đời sống mới (1947)","Cần, Kiệm, Liêm, Chính (1949)","Người cán bộ cách mạng (1955)","Đạo đức cách mạng (1958)"],"dung":"C"},{"id":392,"chuong":6,"cauHoi":"Luận điểm: \"Đảng cần chăm lo giáo dục đạo đức cách mạng cho đoàn viên và thanh niên, đào tạo họ thành những người thừa kế xây dựng chủ nghĩa xã hội, vừa \"hồng\" vừa \"chuyên\", được viết trong tác phẩm nào của Hồ Chí Minh?","dapAn":["Thư gửi thanh niên (1965)","Di chúc (1969)","Sửa đổi lối làm việc (1947)","Nâng cao đạo đức cách mạng, quét sạch chủ nghĩa cá nhân (1969)"],"dung":"B"},{"id":393,"chuong":6,"cauHoi":"Yếu tố cốt lỗi đầu tiên tạo nên nền tảng tư tưởng đạo đức Hồ Chí Minh là: •","dapAn":["Tình thương người, yêu đồng loại","Là ham muốn tột bậc làm sao cho nước ta được hoàn toàn độc lập, dân ta được hoàn toàn tự do, đồng bào ai cũng có cơm ăn, áo mặc, ai cũng được học hành","Yêu đất nước mình","Tất cả các đáp án"],"dung":"D"},{"id":394,"chuong":6,"cauHoi":"Trong tình yêu thương con người, Hồ Chí Minh đòi hỏi mỗi người phải:","dapAn":["Chặt chẽ và nghiêm khắc với mình; rộng rãi, độ lượng và giàu lòng vị tha với người khác","Rộng rãi độ lượng với mình, giàu lòng vị tha với người khác","Nghiêm khắc với mình, giàu lòng vị tha với người và dĩ hòa vi quý","Tất cả các đáp án"],"dung":"A"},{"id":395,"chuong":6,"cauHoi":"Hồ Chí Minh xem xét con người trong sự thống nhất của hai mặt đối lập nào?","dapAn":["Thiện và ác, hay và dở","Tốt và xấu, hiền và dữ","Mặt xã hội và mặt sinh học","Tất cả các đáp án"],"dung":"D"},{"id":396,"chuong":6,"cauHoi":"Để có những con người Việt Nam mới, theo Hồ Chí Minh phải có những phương pháp xây dựng con người như thế nào?","dapAn":["Nêu gương người tốt, việc tốt","Chú trọng đến giáo dục","Chú trọng vai trò của tổ chức Đảng, chính quyền, đoàn thể quần chúng","Tất cả các đáp án"],"dung":"D"},{"id":397,"chuong":6,"cauHoi":"Học tập theo tư tưởng Hồ Chí Minh về xây dựng con người, Hội nghị lần thứ 5 Ban chấp hành Trung ương khóa VIII (7/1998) đã nêu nhiệm vụ xây dựng con người Việt Nam trong thời kì đẩy mạnh công nghiệp hóa, hiện đại hóa với những phẩm chất nào?","dapAn":["Có tinh thần yêu nước, tự cường dân tộc","Có ý thức tập thể, đoàn kết, phấn đấu vì lợi ích chung","Có lối sống lành mạnh, nếp sống văn minh, cần kiệm, trung thực","Tất cả các đáp án"],"dung":"D"},{"id":398,"chuong":6,"cauHoi":"Tại sao phải học tập và làm theo đạo đức Hồ Chí Minh trong giai đoạn hiện nay?","dapAn":["Là đòi hỏi của sự nghiệp cách mạng, sự nghiệp đổi mới đất nước và hội nhập quốc tế","Nhằm làm cho mỗi người trở thành công dân tốt hơn, xứng đáng là những người làm chủ đất nước, biết trọng danh dự, lương tâm, trách nhiệm","Góp phần tích cực vào cuộc đấu tranh chống suy thoái về tư tưởng, chính trị, đạo đức, lối sống trong Đảng và trong xã hội","Tất cả đáp án"],"dung":"D"},{"id":399,"chuong":6,"cauHoi":"Học tập đạo đức cách mạng của Hồ Chí Minh về phẩm chất trung với nước, hiếu với dân là học ở Người về:","dapAn":["Một con người trọn đời vì nước vì dân","Khí phách anh hùng, ý chí độc lập tư cường","Kiên trì mục tiêu, lý tưởng, không chịu khuất phục trước mọi kẻ thủ","Tất cả các đáp án"],"dung":"D"},{"id":400,"chuong":6,"cauHoi":"Hồ Chí Minh khẳng định: \"Vì lẽ sinh tồn cũng như mục đích của cuộc sống, loài người mới sáng tạo và phát minh ra ngôn ngữ, chữ viết, đạo đức, pháp luật, v. v.. cho đến những phương thức sinh hoạt, v. v.. nhằm thích ứng những nhu cầu (...)\"71. Xác định cụm từ còn thiếu?","dapAn":["Đời sống và những khát vọng tự do","Đời sống và đòi hỏi của sự sinh tồn","Đời sống và hạnh phúc của con người","Đời sống và sự ấm no của nhân dân"],"dung":"B"},{"id":401,"chuong":6,"cauHoi":"Khi tiếp cận văn hóa ở nghĩa rộng, Hồ Chí Minh khẳng định văn hóa là gì?","dapAn":["Là tổng hợp mọi phương thức sinh hoạt của con người","Là tổng hợp mọi hoạt động giáo dục đào tạo của con người","Là tổng hợp mọi hoạt động văn nghệ, thể dục thể thao của con người","Là tổng hợp mọi hoạt động vui chơi, giải trí của con người"],"dung":"A"},{"id":402,"chuong":6,"cauHoi":"Từ sau Cách mạng tháng 8/1945, Hồ Chí Minh có bàn đến văn hóa nhưng theo ý nghĩa nào?","dapAn":["Văn hóa là hiện tượng thuần tuý của tinh thần xã hội","Đồng nhất văn hóa với văn học - nghệ thuật trong xã hội","Văn hóa là đời sống vật chất của xã hội","Văn hóa là kiến trúc thượng tầng, là toàn bộ đời sống tinh thần của xã hội"],"dung":"D"},{"id":403,"chuong":6,"cauHoi":"Trong bài thơ Lịch sử nước tà, Hồ Chí Minh viết: \"Dân ta phải biết (...), cho tường (...) nước nhà Việt Nam\". Xác định các cụm từ còn thiếu?","dapAn":["Truyền thống/ lịch sử","Đồng lòng/ Dấu tích","Khát vọng/ Di tích","Sử ta/ gốc tích"],"dung":"D"},{"id":404,"chuong":6,"cauHoi":"Hồ Chí Minh khẳng định: ở nước Việt Nam thuộc địa, văn hóa có mối quan hệ thế nào với chính trị ?","dapAn":["Văn hóa có được giải phóng thì chính trị mới được giải phóng","Chính trị giải phóng mở đường cho văn hóa phát triển","Chính trị, xã hội có được giải phóng thì văn hóa mới được giải phóng","Chính trị, kính tế có được giải phóng thì văn hóa mới được giải phóng"],"dung":"B"},{"id":405,"chuong":6,"cauHoi":"Theo Hồ Chí Minh, văn hóa không thể đứng ngoài mà phải ở trong chính trị, tức là:","dapAn":["Văn hóa phải phục vụ nhiệm vụ chính trị","Văn hóa phải là đời sống tinh thần của xã hội","Văn hóa thực hiện nhiệm vụ phò chính, trừ tà","Văn hóa một mặt trận và quan trọng như các mặt trận khác"],"dung":"A"},{"id":406,"chuong":6,"cauHoi":"Theo Hồ Chí Minh, văn hóa không thể đứng ngoài mà phải đứng trong kinh tế, nghĩa là:","dapAn":["Văn hóa phụ thuộc hoàn toàn vào kinh tế, kinh tế quyết định văn hóa","Văn hóa không phụ thuộc hoàn toàn vào kinh tế, mà có vai trò tác động tích cực trở lại kinh tế","Văn hóa và kinh tế có sự tác động quan lại lẫn nhau, tạo thành nền tảng đời sống vật chất của xã hội","Kinh tế không phụ thuộc vào văn hóa, mà kinh tế có vai trò tác động tích cực trở lại văn hóa"],"dung":"B"},{"id":407,"chuong":6,"cauHoi":"Xã hội thế nào, văn nghệ thế ấy. Văn nghệ của dân tộc ta vốn rất phong phú, nhưng dưới chế độ thực dân và phong kiền, nhân dân ta bị nô lệ, thì văn nghệ cũng bị..., không thể phát triển được. Hoàn thiện câu nói của Hồ Chí Minh?","dapAn":["Nô dịch, bị đồng hóa","Nô lệ, kém phát triển","Nô lệ, bị tồi tàn","Nô lệ, bị đồng hóa"],"dung":"C"},{"id":408,"chuong":6,"cauHoi":"Bản sắc văn hóa dân tộc theo quan điểm của Hồ Chí Minh được nhìn nhận qua 2 lớp thể hệ, bao gồm:","dapAn":["Hình thức và nội dung","Hình thức và tính chất","Nội dung và nguyên tắc","Tính chất và nguyên tắc"],"dung":"A"},{"id":409,"chuong":6,"cauHoi":"Theo Hồ Chí Minh, về nội dung của bản sắc văn hóa dân tộc được biểu hiện như thế nào?","dapAn":["Ở lòng yêu nước, thương nòi; tinh thần độc lập, tự cường, tự tôn dân tộc","Ở lòng yêu nước, thương dân; tinh thần hữu nghị với các nước trên thế giới","Ở lòng yêu nước, thương những người bị áp bức, bóc lột","Ở lòng yêu nước, yêu chế độ xã hội chủ nghĩa; khát vọng hòa bình, giàu mạnh"],"dung":"A"},{"id":410,"chuong":6,"cauHoi":"Theo Hồ Chí Minh, hình thức, cốt cách văn hóa dân tộc được biểu hiện:","dapAn":["Ở ngôn ngữ, phong tục, tập quán, lễ hội, truyền thống, cách cảm và nghĩ","Ở cách nói, cách viết, các diễn đạt của các tác phẩm văn hóa văn nghệ","Ở lối sống, đạo đức, nhân cách của con người Việt Nam","Ở triết lý giáo dục Việt Nam trong thời kỳ đất nước độc lập"],"dung":"A"},{"id":411,"chuong":6,"cauHoi":"Theo Hồ Chí Minh yếu tố nào là ngọn nguồn đi tới chủ nghĩa Mác - Lênin?","dapAn":["Văn hóa phương Đông","Văn hóa phương Tây","Đạo đức truyền thống","Bản sắc văn hóa dân tộc"],"dung":"D"},{"id":412,"chuong":6,"cauHoi":"Trước Cách mạng tháng Tám năm 1945, Hồ Chí Minh có quan điểm xây dựng nền văn hóa mới với định hướng về tâm lý là gì?","dapAn":["Tinh thần vì nước quên mình, vì lợi ích chung quên lợi ích riêng","Tinh thần làm chủ","Tinh thần học tập, nâng cao trình độ chuyên môn, nghiệp vụ","Tinh thần độc lập tự cường"],"dung":"D"},{"id":413,"chuong":6,"cauHoi":"Theo Hồ Chí Minh, mặt trận văn hóa là cuộc chiến đấu trên lĩnh vực văn hóa; vì vậy anh chị em văn nghệ sĩ là (..) trên mặt trận ấy; cũng như các chiến sĩ khác, chiến sĩ nghệ thuật có nhiệm vụ (...) Tổ quốc, phục vụ nhân dân. Xác định cụm từ còn thiếu?","dapAn":["Chiến sĩ/phục vụ","Chiến sĩ/phụng sự","Lãnh đạo/phục vụ","Lãnh đạo/phụng sự"],"dung":"B"},{"id":414,"chuong":6,"cauHoi":"Trước Cách mạng tháng Tám năm 1945, Hồ Chí Minh có quan điểm xây dựng nền văn hóa mới với định hướng về luân lý là gì?","dapAn":["Tinh thần độc lập tự cường","Biết hi sinh mình, làm lợi cho quân chúng","Mọi sự nghiệp liên quan đến phúc lợi của cá nhân phải được đảm bảo","Dân quyền"],"dung":"B"},{"id":415,"chuong":6,"cauHoi":"Luận điểm: \"Cũng như sông thì có nguồn mới có nước, không có nguồn thì sông cạn. Cây phải có gốc, không có gốc thì cây héo. Người cách mạng phải có (...), không có (...) thì dù tài giỏi mấy cũng không lãnh đạo được nhân dân\"2. Xác định cụm từ còn thiếu ?","dapAn":["Tình thương","Lòng nhân ải","Đạo đức","Liêm"],"dung":"C"},{"id":416,"chuong":6,"cauHoi":"Luận điểm: \"Sức có mạnh mới gánh được nặng và đi được xa. Người cách mạng phải có đạo đức cách mạng làm nền tăng, mới hoàn thành được (.)73, Xác định cụm từ thiếu?","dapAn":["Nhiệm vụ cách mạng vẻ vang","Nhiệm vụ xây dựng đất nước","Nhiệm vụ mới của đất nước","Nhiệm vụ xây dựng đời sống mới"],"dung":"A"},{"id":417,"chuong":6,"cauHoi":"Phẩm chất đạo đức bao trùm nhất trong quan điểm Hồ Chí Minh về những chuẩn mực đạo đức cách mạng là gì?","dapAn":["Trung với nước, hiếu với dân","Cần kiệm, liêm, chính, chí công vô tư","Có tình yêu thương con người, sống có tình có nghĩa","Có tinh thần quốc tế trong sáng"],"dung":"A"},{"id":418,"chuong":6,"cauHoi":"Hồ Chí Minh chỉ ra rằng: \"Mỗi con người đều có thiện và ác ở trong lòng. Ta phải biết làm cho phần tốt ở trong mỗi con người (..), đó là thái đội của người cách mạng\"74. Xác định cụm từ còn thiếu trong dấu ngoặc đơn?","dapAn":["Này nở như hoa mùa Xuân và phần xấu bị mất dần đi","Nảy nở như hoa mùa Hè và phần xấu bị mất dần đi","Nảy nở như hoa mùa Thu và phần xấu bị mất dần đi","Nảy nở như hoa mùa Đông và phần xấu bị mất dần đi"],"dung":"A"},{"id":419,"chuong":6,"cauHoi":"Theo Hồ Chí Minh, chữ \"Cần\" được hiểu như thế nào?","dapAn":["Lao động siêng năng, chăm chỉ, không lười biếng, không ỉ lại vào người khác; thông qua lao động để giao tiếp với mọi người đề hoàn thiện bản thân","Lao động cần cù, siêng năng; có kế hoạch, sáng tạo, năng suất cao; lao động với tinh thần tự lực cách sinh, không lười biếng","Lao động chăm chỉ, coi lao động là vinh quang, là động lực, là niềm vui nên luôn tích cực, chủ động trong lao động","Lao động cần củ; xem tao động là niềm vui, niềm hạnh phúc; chủ động, tích cực trong lao động; lấy lao động làm thước đo giá trị ở mỗi người"],"dung":"B"},{"id":420,"chuong":6,"cauHoi":"Theo Hồ Chí Minh, chữ \"Liêm\" có nghĩa là: \"Không tham địa vị. Không tham (...). Không tham (...). Không ham người (...) mình. Chỉ có một thứ ham là ham học, ham làm, ham tiến bộ\"7. Xác dịnh cụm từ còn thiếu?","dapAn":["Quyền lực/ giàu sang/ tâng bốc","Tiền tài/ sung sướng/ tâng bốc","Đanh vọng/ quyền lực/ xu nịnh","Chức vụ/ giàu sang/ xu nịnh"],"dung":"B"},{"id":421,"chuong":6,"cauHoi":"Theo Hồ Chí Minh, yếu tố nào sau đây được xem là quý trọng nhất?","dapAn":["Vốn","Khoa học, kỹ thuật","Con người","Tài nguyên, khoáng sản."],"dung":"C"},{"id":422,"chuong":6,"cauHoi":"Hồ Chí Minh viết: \"Vô luận việc gì, đều do (...) làm ra, từ nhỏ đến to, từ gần đến xa, đều thế cả\"7. Xác dịnh cụm từ còn thiếu?","dapAn":["Nông dân","Công nhân","Người","Con người"],"dung":"C"},{"id":423,"chuong":6,"cauHoi":"Hồ Chí Minh yêu cầu: \"Việc dễ mấy không có (...) cũng chịu, việc khó mấy có (...) liệu cũng xong\". Xác định cụm từ còn thiều?","dapAn":["Dân- Nhân dân","Nhân dân- Dân","Nhân dân- Nông dẫn","Dân- Công nhân"],"dung":"B"},{"id":424,"chuong":6,"cauHoi":"Chọn đáp án đúng nhất với quan điểm của Hồ Chí Minh về chủ thể sáng tạo ra mọi giá trị vật chất, tinh thần cho xã hội là?","dapAn":["Nông dân","Công nhân","Trí thức","Nhân dân"],"dung":"D"},{"id":425,"chuong":6,"cauHoi":"Để xây dựng được con người vừa hồng vừa chuyên, Hồ Chí Minh chú trọng đến lĩnh vực gì ?","dapAn":["Kinh tế","Giáo dục","Chính trị","Văn hóa - xã hội"],"dung":"B"},{"id":426,"chuong":6,"cauHoi":"Dưới ánh sáng tư tưởng Hồ Chí Minh, Cương lĩnh xây dựng đất nước (2011) của Đảng đã khẳng định: \"Con người là (...) phát triển, đồng thời là (...) phát triển. Tôn trọng và bảo vệ quyền con người, gắn quyền con người với quyền và lợi ích của dân tộc, đất nước và quyền làm chủ của nhân dân\". Xác định cụm từ còn thiếu?","dapAn":["Trung tâm của chiến lược/ chủ thể","Trọng tâm của chiến lược/ chủ thể","Quan trọng của chiến lược/ chủ thể","Then chốt của chiến lược/ chủ thể"],"dung":"A"},{"id":427,"chuong":6,"cauHoi":"Theo Hồ Chí Minh, bản sắc văn hóa dân tộc được hiểu thế nào?","dapAn":["Những giá trị bền vững của cộng đồng các dân tộc Việt Nam như yêu nước, tinh thần độc lập tự cường, tự tôn dân tộc","Những giá trị văn hóa bền vững của cộng đồng các dân tộc Việt Nam; là thành quả của quá trình lao động, sản xuất chiến đấu và giao lưu của con người Việt Nam","Những giá trị văn hóa bền vững, là thành quả của quá trình lao động, sản xuất, chiến đấu của cộng đồng người Việt Nam","Những giá trị bền vững của cộng đồng các dân tộc Việt Nam. Được nhìn nhận qua 2 lớp thế hệ"],"dung":"B"},{"id":428,"chuong":6,"cauHoi":"Theo Hồ Chí Minh, giữ gìn bản sắc văn hóa dân tộc phải đi đôi với tiếp thu tinh hoa văn hóa nhân loại. Tuy nhiên, để giữa giữ gìn cốt cách văn hóa dân tộc với tiếp thu văn hóa nhân loại cần phải có điều kiện gì?","dapAn":["Lấy văn hóa dân tộc làm gốc","Lấy văn hóa dân tộc làm nền tảng","Lấy văn hóa dân tộc làm then chốt","Lấy văn hóa dân tộc làm chỗ dựa"],"dung":"A"},{"id":429,"chuong":6,"cauHoi":"Theo Hồ Chí Minh, nội dung tiếp thu tinh hoa văn hóa nhân loại là gì?","dapAn":["Là văn hóa phương Đông, đặc biệt là văn hóa Ấn Độ, Trung Quốc","Là văn hóa phương Tây, đặc biệt là tư tưởng dân chủ tư sản","Là toàn diện bao gồm Đông, Tây, kim, cổ, tất cả các mặt, các khía cạnh","Là toàn diện bao gồm văn hóa phương Đông, phương Tây"],"dung":"C"},{"id":430,"chuong":6,"cauHoi":"Tiêu chí tiếp thu tinh hoa văn hóa nhân loại theo Hồ Chí Minh là gì?","dapAn":["Tiếp thu cái gì hay, cái gì tốt của văn hóa nhân loại thì thì ta học lấy","Tiếp thu tất cả văn hóa nhân loại, không bỏ sót nền văn hóa nào","Chỉ tiếp thu các giá trị văn hóa Trung Quốc, Án Độ, Liên Xô","Tiếp thu có chọn lọc văn hóa nhân loại, nhưng chú trọng tiếp thu văn hóa các nước cùng chung chế độ xã hội chủ nghĩa"],"dung":"A"},{"id":431,"chuong":6,"cauHoi":"Đối với một quốc gia cần, kiệm, liêm, chính là thước đo sự giàu có về vật chất, vững mạnh về tinh thần, thể hiện (...) theo tư tướng của Hồ Chí Minh. Xác định cụm từ còn thiếu ?","dapAn":["Sự tiến bộ, khoa học và là động lực của chế độ mới","Sự phong phú, đa dạng và là yêu cầu của đời sống mới","Sự văn minh, tiến bộ và là nền tảng của đời sống mới","Sự khoa học, văn minh và là cơ sở của đời sống mới 105"],"dung":"C"},{"id":432,"chuong":6,"cauHoi":"Vai trò của văn hóa văn nghệ trong quan điểm Hồ Chí Minh là gì?","dapAn":["Nâng cao lòng yêu nước, tình cảm cách mạng, sự lạc quan, ý chí quyết tâm và niềm tin vào thắng lợi cuối cùng của cách mạng","Nâng cao tinh thần lạc quan, vui vẻ và niềm tin vào cách mạng","Là thang thuốc tinh thần vô giá, cổ vũ bộ đội trong kháng chiến","Giúp mọi người lạc quan, vui tươi trong cuộc sống và chiến đấu, lao động và học tập"],"dung":"A"},{"id":433,"chuong":6,"cauHoi":"Theo Hồ Chí Minh, văn hóa giáo dục có vai trò như thế nào?","dapAn":["Giúp người học có kiến thức về chuyên môn, nghiệp vụ, có năng lực làm chủ","Diệt giặc dốt, xóa mà chữ, giúp con người hiểu biết quy luật phát triển xã hội","Giúp người học hiểu biết sâu sắc về lịch sử, địa lý dân tộc và thế giới","Nâng cao trình độ dân trí, đấu tranh chống các biểu hiện phản văn hóa"],"dung":"B"},{"id":434,"chuong":6,"cauHoi":"Với sứ mệnh trồng người, theo Hồ Chí Minh văn hóa giáo dục thực hiện nhiệm vụ gì?","dapAn":["Đào tạo con người mới, cán bộ mới, nguồn nhân lực chất lượng cao cho sự nghiệp cách mạng","Đào tạo đội ngũ trí thức phát triển toàn diện cả đức, trí, thế, mỹ đáp ứng được yêu cầu sự nghiệp đấu tranh giải phóng dân tộc","Đào tạo con người Việt Nam giỏi về chuyên môn, nghiệp vụ đáp ứng được yêu cầu của sự nghiệp đổi mới đất nước","Cải tạo trí thức cũ, xây dựng trí thức mới, đáp ứng được yêu cầu, nhiệm vụ của sự nghiệp xây dựng chủ nghĩa xã hội"],"dung":"A"},{"id":435,"chuong":6,"cauHoi":"Theo Hồ Chí Minh, văn hóa đạo đức lối sống có vai trò như thế nào?","dapAn":["Giúp giáo dục đạo đức cách mạng cần, kiệm, liêm, chính, chí công vô tư mỹ","Giúp nâng cao phẩm giá, phong cách, hướng con người tới giá trị chân, thiện,","Giúp xây dựng đời sống văn hóa lành mạnh, sống có ý thức bảo vệ môi trường","Giúp nâng cao người dân nâng cao ý thức xây dựng văn hóa, tích cực đấu tranh chống những biêu hiện phản văn hóa, phản tiến bộ"],"dung":"B"},{"id":436,"chuong":6,"cauHoi":"Để làm tròn nhiệm vụ \"phò chính trừ tà\" của mình, theo Hồ Chí Minh chiến sĩ nghệ thuật phải có lập trường như thế nào?","dapAn":["Tư tưởng vững vàng, có cách lập luận vấn đề rõ ràng, khúc triết","Tư tường bám sát thực tiễn, ngòi bút phải sâu sắc, gần gũi với nhân dân","Tư tưởng vững vàng, bám sát thực tiễn; phê bình nghiêm khắc những thói hư tật xấu, ca tụng chân thật những người tốt, việc tốt","Tư tưởng vững vàng, luôn nghe và viết theo đời sống thực tiễn của quần chúng"],"dung":"C"},{"id":437,"chuong":6,"cauHoi":"Văn hóa phải gắn với thực tiễn đời sống của nhân dân. Để làm được như vậy, Hồ Chí Minh đã khẳng định các văn nghệ sĩ phải:","dapAn":["Thật sự giác ngộ, tin tưởng vào quần chúng,v.v..để thấu hiểu tâm tư, tình cảm và nguyện vọng của nhân dân","Thật hòa mình vào quần chúng, v.v. để hiểu thấu tâm tư, tình cảm, nguyện vọng của nhân dân","Thật thà, dũng cảm, đoàn kết quần chúng thành một khối, v.v.. để hiểu thấu tâm tư, tình cảm, nguyện vọng của nhân dân","Thật tin tưởng, yêu dân, kính dân, v.v..để thấu hiểu tâm tư, tình cảm, nguyện vọng của nhân dân"],"dung":"B"},{"id":438,"chuong":6,"cauHoi":"Tính đại chúng của nền văn hóa theo quan điểm Hồ Chí Minh được thể hiện ở những việc nào?","dapAn":["Phải phục vụ dân tộc và do dân tộc xây dựng nên","Phải phục vụ nhân dân và do nhân dân xây dựng nên","Phải phục vụ đồng bào và do đồng bào xây dựng nên","Phải phục vụ quần chúng và do quần chúng xây dựng nên"],"dung":"B"},{"id":439,"chuong":6,"cauHoi":"Trong thời kì xây dựng chủ nghĩa xã hội ở miền Bắc, Hồ Chí Minh chủ trương xây dựng nền văn hóa như thế nào?","dapAn":["Có nội dung xã hội chủ nghĩa và tính chất dân tộc","Có nội dung xã hội chủ nghĩa và tính chất thời đại","Có nội dung tư bản chủ nghĩa và tính chất thời đại","Có nội dung tư bản chủ nghĩa và tính chất dân tộc"],"dung":"A"},{"id":440,"chuong":6,"cauHoi":"Để giữ gìn bản sắc văn hóa dân tộc, theo Hồ Chí Minh trách nhiệm của con người Việt Nam là cần phải làm gì?","dapAn":["Biết kết thừa, chọn lọc những cái hay của văn hóa các dân tộc thiểu số và tích cực hội nhập, giao lưu văn quốc tế *","Xây dựng nền văn hóa mới trên cơ sở kế thừa, tiếp thu những giá trị văn hóa đông, tây để làm giàu bản sắc văn hóa dân tộc","Phải trân trọng, khai thác, giữ gìn, phát huy, phát triển những giá trị của văn hóa dân tộc, đáp ứng yêu cầu, nhiệm vụ từng giai đoạn cách mạng","Tích cực đấu tranh chống những biểu hiện phản văn hóa, phản tiến bộ, đặc biệt là các hủ tục, mê tính, dị đoan"],"dung":"C"},{"id":441,"chuong":6,"cauHoi":"Hồ Chí Minh rất quan tâm đến giáo dục toàn diện cho các em học sinh, sinh viên cả về \"Đức, trí, thể, mỹ\". Trong đó, đức được xác định bao gồm:","dapAn":["Nếp ăn ở, sinh hoạt hàng ngày, trước hết là với giã đình, anh em, bạn bè, rộng ra là với quốc gia, dân tộc; học để làm việc, làm người, làm cán bộ","Nếp ăn ở, khả năng vượt lên khó khăn, thử thách để đạt được mục tiêu trong cuộc sống","Nếp ăn ở, ý thức tự lực, tự cường, khát vọng vươn lên để khẳng định những giá trị bản thân trong học tập, lao động","Nếp ăn ở, học tập, sinh hoạt, lao động, học biết chán, luôn có ý thức thi đua trong học tập"],"dung":"A"},{"id":442,"chuong":6,"cauHoi":"Theo Hồ Chí Minh, đạo đức là nhân tố tạo nên sự hấp dẫn của chủ nghĩa xã hội bắt nguồn trước hết từ đâu?","dapAn":["Những giá trị đạo đức cao đẹp, mức sống vật chất dồi dào của những người cộng sản ưu tú","Những giá trị đạo đức cao đẹp, tự tưởng tự do giải phóng của những người cộng sản ưu tú","Những giá trị đạo đức cao đẹp, phẩm chất của những người cộng sản ưu tú","Những giá trị đạo đức cao đẹp, lối sống mới của những người cộng ưu tú"],"dung":"C"},{"id":443,"chuong":6,"cauHoi":"Theo Hồ Chí Minh, trung với nước là phải làm gì?","dapAn":["Yêu nước, xây dựng đất nước giàu mạnh, dân chủ, công bằng, văn minh","Yêu nước, đấu tranh chống các âm mưu của các thế lực thủ địch chống phá sự nghiệp cách mạng","Yêu nước, sẵn sàng hy sinh bản thân cho sự nghiệp đổi mới đất nước và hội nhập quốc tế","Yêu nước, tuyệt đối trung thành với Tổ quốc, suốt đời phấn đấu cho Đảng, cho cách mạng"],"dung":"D"},{"id":444,"chuong":6,"cauHoi":"Theo Hồ Chí Minh, hiếu với dân là phải làm gì?","dapAn":["Khai dân trí, chấn dân khí, hậu dân sinh, mở mang dân quyền","Dân biết, dân bàn, dân làm, dân kiểm tra và dân thụ hướng gốc","Thương dân, tin dân, thân dân, học hòi dân, kính trọng nhân dân, lây dân làm","Phát huy quyền làm chủ của nhân dân, pháp luật phải đảm bảo quyền con người được thi trong thực tế"],"dung":"C"},{"id":445,"chuong":6,"cauHoi":"Chuẩn mực đạo đức nào được Hồ Chí Minh xác định là nội dung cốt lõi của đạo đức cách mạng gắn liền với hoạt động hằng ngày của mỗi người?","dapAn":["Trung với nước, hiếu với dân","Cần, kiệm, liêm, chính, chí công vô tư","Yêu thương con người, sống có tình có nghĩa","Có tinh thần quốc tế trong sáng"],"dung":"B"},{"id":446,"chuong":6,"cauHoi":"Hồ Chí Minh khẳng định, chí công vô tư là công bằng, công tâm, không thiên tư thiên vị, làm việc gì cũng không nghĩ đến mình trước, chỉ biết vì Đảng, vì dân tộc, \"lo trước thiên hạ, vui sau thiên hạ\" có nghĩa là gì?","dapAn":["Nêu cao chủ nghĩa tập thể, trừ bỏ chủ nghĩa cá nhân","Nêu cao tinh thần tự chủ, tự chịu trách nhiệm trước nhân dân","Lấy lợi ích của cá nhân đặt lên trên lợi ích của tập thể","Nêu cao chế độ làm chủ tập thể, trừ bỏ chế độ tư hữu tư nhân"],"dung":"A"},{"id":447,"chuong":6,"cauHoi":"Yêu thương con người được Hồ Chí Minh xác định là một trong những phẩm chất đạo đức cao đẹp nhất. Tình yêu thương đó là một tình cảm rộng lớn, trước hết dành cho những người như thế nào?","dapAn":["Nghèo khổ, bị mất quyền, bị áp bức, bóc lột...","Nghèo khổ, bị mất quyền tự do, dân chủ...","Nghèo khổ, bị mất quyền lãnh thổ, quyền tự quyết...","Nghèo khổ, bị mất quyền chính trị, quyền liên hiệp..."],"dung":"A"},{"id":448,"chuong":6,"cauHoi":"Nói đi đôi với làm được Hồ Chí Minh coi là nguyên tắc như thế nào?","dapAn":["Quan trọng bậc nhất trong xây dựng nhân cách công dân","Quan trọng bậc nhất trong xây dựng một nền đạo đức mới","Quan trọng bậc nhất trong xây dựng phẩm chất của người quân tử","Quan trọng bậc nhất trong xây dựng lối sống xã hội chủ nghĩa"],"dung":"B"},{"id":449,"chuong":6,"cauHoi":"Hồ Chí Minh chỉ rõ: \"Nói chung thì các dân tộc phương Đông đều giàu tình cảm, và đối với họ một tấm gương sống còn có giá trị hơn một trăm bài diễn văn tuyên truyền\"™), điều này muốn nhấn mạnh nguyên tắc nào trong xây dựng đạo đức mới?","dapAn":["Nói phải đi đôi với làm gắn liền với nêu gương về đạo đức","Xây đi đôi với chống","Phải tu dưỡng đạo đức suốt đời","Phải tạo phong trào rộng rãi"],"dung":"A"},{"id":450,"chuong":6,"cauHoi":"Theo Hồ Chí Minh, vấn đề quan trọng trong việc giáo dục đạo đức là:","dapAn":["Khơi dậy ý thức, tiềm năng, sức mạnh và ý thức tự giác của mỗi người","Khơi dậy ý thức đạo đức lành mạnh ở mỗi người, để mọi người tự giác nhận thức được trách nhiệm đạo đức của mình","Khơi dậy trách nhiệm, năng lực và ý thức tự giác tu dưỡng của mỗi người","Khơi dậy tiềm năng, sự phấn đấu bền bỉ và năng lực tự giác của mỗi người"],"dung":"B"},{"id":451,"chuong":6,"cauHoi":"Theo Hồ Chí Minh, trên con đường đi tới tiến bộ và cách mạng, đạo đức mới chỉ có thế xây dựng thành công trên cơ sở nào ?","dapAn":["Kiên trì mục tiêu chống chủ nghĩa đế quốc và những thói hư tật xấu","Kiên trì mục tiêu độc lập dân tộc và rèn luyện đạo đức","Kiên trì mục tiêu chống chủ nghĩa để quốc, chống thói quen và tập tục lạc hậu, loại trử chủ nghĩa cá nhân","Kiên trì mục tiêu đấu tranh chống chủ nghĩa đế quốc và xây dựng chủ nghĩa xã hội"],"dung":"C"},{"id":452,"chuong":6,"cauHoi":"Hồ Chí Minh giải thích chữ Người như thế nào ?","dapAn":["Nghĩa hẹp là gia đình, anh em, họ hàng, bè bạn; nghĩa rộng là đồng bào cả nước; rộng hơn nữa là cả loài người","Nghĩa hẹp là cá nhân, anh em, bè bạn; nghĩa rộng là đồng bào cả nước; rộng hơn nữa là cả loài người hơn nữa là cả loài người","Nghĩa hẹp là cá nhân; nghĩa rộng là gia đình, anh em, họ hàng, bè bạn; rộng người","Nghĩa hẹp là cá thể; nghĩa rộng là đồng bào cả nước; rộng hơn nữa là cả loài"],"dung":"A"},{"id":453,"chuong":6,"cauHoi":"Theo Hồ Chí Minh, tính xã hội của con người được hiểu như thế nào ?","dapAn":["Là con người xã hội, thành viên của một cộng đồng xã hội","Là cá nhân sống trong xã hội, có trách nhiệm với xã hội","Là thành viên của xã hôi, chịu sự tác động từ những mặt trái của xã hội","Là thành viên của xã hội, bị ảnh hưởng bởi môi trường xã hội"],"dung":"A"},{"id":454,"chuong":6,"cauHoi":"Khi nêu ra những hiểu biết về yếu tố sinh vật của con người, Hồ Chí Minh khẳng định mọi đường lối, chủ trương, chính sách, nhiệm vụ của Đảng, Nhà nước cần phải thực hiện nay là gì ?","dapAn":["Làm cho dân có cuộc sống ấm no, không có áp bức, bất công","Làm cho dân được tự do, sống một đời hạnh phúc","Làm cho dân có ăn, có mặt, có chỗ ở, có học hành","Làm cho dân được sống bình đẳng, chống phân biệt giàu, nghèo"],"dung":"C"},{"id":455,"chuong":6,"cauHoi":"Nét đặc sắc trong nhìn nhận đặc điểm con người Việt Nam với những điều kiện lịch sử cụ thể, với cấu trúc kinh tế, xã hội cụ thể của Hồ Chí Minh, giúp giải quyết mối quan hệ gì một cách sáng tạo ?","dapAn":["Dân tộc và giai cấp","Cá nhân và cộng đồng","Cá nhân và xã hội","Dân tộc và nhân loại"],"dung":"A"},{"id":456,"chuong":6,"cauHoi":"Con người trong tư tưởng và hành động của Hồ Chí Minh là chiến lược số một. Điều đó, được cụ thể hóa trong những giai đoạn nào của cách mạng Việt Nam?","dapAn":["Giải phóng dân tộc - Xây dựng chế độ dân chủ nhân dân - Tiến dần lên chủ nghĩa xã hội","Giải phóng con người - Xây dựng chế độ dân chủ nhân dân - Tiến dần lên chủ nghĩa xã hội","Giải phóng giai cấp - Xây dựng chế độ dân chủ nhân dân - Tiến dần lên chủ nghĩa xã hội","Giải phóng lực lượng sản xuất - Xây dựng chế độ dân chủ nhân dân - Tiến lên chủ nghĩa xã hội"],"dung":"A"},{"id":457,"chuong":6,"cauHoi":"Con người là mục tiêu của cách mạng, tức là hướng tới giải phóng dân tộc, giải phóng giai cấp, giải phóng xã hội, giải phóng con người. Theo Hồ Chí Minh, các giải phóng đó có mối quan hệ với nhau như thế nào ?","dapAn":["Kết hợp chặt chẽ, đồng thời nối tiếp nhau","Kết hợp chặt chẽ, đồng thời bổ sung cho nhau","Kết hợp hài hòa, đồng thời bổ sung cho nhau","Kết hợp chặt chẽ, đồng thời tác động qua lại với nhau"],"dung":"D"},{"id":458,"chuong":6,"cauHoi":"Ý nghĩa của việc xây dựng con người theo Hồ Chí Minh là gì ?","dapAn":["Một trọng tâm, một bộ phận hợp thành của chiến lược phát triển đất nước","Một trọng tâm, một bộ phận hợp thành của Đảng về phát triển kinh tế","Một trọng tâm, một bộ phận hợp thành của Nhà nước về phát triển kinh tế","Một trọng tâm, một bộ phận hợp thành của Mặt trận Tổ quốc Việt Nam về phát triển văn hóa xã hội"],"dung":"A"},{"id":459,"chuong":6,"cauHoi":"Theo Hồ Chí Minh \"Trồng người\" phải được tiến hành như thế nào?","dapAn":["Liên tục, xem đó là thước đo cho trình độ phát triển của lực lượng sản xuất","Thường xuyên trong suốt tiến trình đi lên chủ nghĩa xã hội và phải đạt được những kết quả cụ thể trong từng giai đoạn cách mạng","Liên tục trong suốt quá trình đổi mới và hội nhập kinh tế quốc tế","Tiến hành thường xuyên trong suốt tiến trình đấu tranh giải phóng dân tộc, cũng như quá trình đổi mới đất nước"],"dung":"B"},{"id":460,"chuong":6,"cauHoi":"Công việc trồng người, theo Hồ Chí Minh là trách nhiệm của ai?","dapAn":["Là trách nhiệm riêng của Đảng, Nhà nước","Là trách nhiệm riêng của cá nhân, đoàn thể chính trị - xã hội","Của Đảng, Nhà nước, các đoàn thể chính trị - xã hội kết hợp với tính tích cực, chủ động của từng người","Của Đảng, Nhà nước, các tổ chức quốc tế, đặc biệt là trách nhiệm của các cơ quan, ban ngành thực hiện nhiệm vụ trên lĩnh vực giáo dục"],"dung":"C"},{"id":461,"chuong":6,"cauHoi":"Trong mối quan hệ biện chứng giữa chủ nghĩa xã hội và con người xã hội chủ nghĩa, theo Hồ Chí Minh chủ nghĩa xã hội tạo ra những con người xã hội chủ nghĩa, con người xã hội chủ nghĩa là:","dapAn":["Động lực xây dựng chủ nghĩa xã hội","Mục tiêu xây dựng chủ nghĩa xã hội","Tiêu chuẩn xây dựng chủ nghĩa xã hội","Thước đo xây dựng chủ nghĩa xã hội"],"dung":"A"},{"id":462,"chuong":6,"cauHoi":"Trong xây dựng con người, Hồ Chí Minh chủ trương xây dựng con người toàn diện theo các khía cạnh nào sau đây ?","dapAn":["Có ý thức tập thể, yêu nước, tiến bộ, có lý tưởng, sống có trách nhiệm","Có ý thức làm chủ, yêu nước, thương dân, có trí tuệ và bản lĩnh vững vàng","Có ý thức làm chủ, tinh thần thập thể, cần kiệm, hăng hái bảo vệ Tổ quốc; có lòng yêu nước, phương pháp làm việc khoa học, dân chủ, nêu gương","Có lòng yêu nước nồng nàn, có chí tiến thủ, có ý thức bảo vệ Tổ quốc"],"dung":"C"},{"id":463,"chuong":6,"cauHoi":"Vận dụng tư tưởng Hồ Chí Minh về vai trò của văn hóa, Nghị quyết Hội nghị lần thứ 5 Ban chấp hành Trung ương khóa VIII về xây dựng và phát triển văn hóa Việt Nam tiên tiến, đậm đà bản sắc dân tộc đã xác định:","dapAn":["Văn hóa là nên tảng tinh thần của xã hội, vừa là mực tiêu vừa là động lực thúc đẩy sự phát triển kinh tế - xã hội","Văn hóa là giá trị tinh thần của xã hội, văn hóa giúp giáo dục, đào tạo con người đáp ứng yêu cầu của sự nghiệp đổi mới","Văn hóa là trung tâm của sự phát triển, quan tâm phát triển văn hóa toàn diện trở thành nền tảng tinh thần của xã hội","Coi trọng phát triển văn hóa, văn nghệ, làm văn hóa trở thành động lực thúc đẩy sự phát triển kinh tế - xã hội"],"dung":"A"},{"id":464,"chuong":6,"cauHoi":"Trong Cương lĩnh xây dựng đất nước trong thời kỳ quá độ lên chủ nghĩa xã hội (bổ sung, phát triển năm 2011) đã khẳng định như thế nào về yếu tố con người theo tư tưởng Hồ Chí Minh?","dapAn":["Xây dựng con người làm chủ thể quyết định thành công sự nghiệp đổi mới và hội nhập quốc tế","Con người vừa là mục tiêu, vừa là động lực của sự nghiệp đổi mới","Con người được quan tâm phát triển toàn diện về đức, trí, thể, mỹ","Con người là trung tâm của chiến lược phát triển, đồng thời là chủ thể phát triển"],"dung":"D"},{"id":465,"chuong":6,"cauHoi":"Theo Hồ Chí Minh, thế hệ trẻ Việt Nam có vai trò như thế nào?","dapAn":["Là người tiên phong trong học tập, lao động, quyết định đên thăng lợi của sự nghiệp đấu tranh giải phóng dân tộc","Là người chủ tương lai của nước nhà; nước nhà thịnh hay suy, yếu hay mạnh một phần lớn là do các thanh niên","Người đi đầu trong xây dựng, bảo vệ Tổ quốc; chủ động học tập để trở thành nhing cong dan toan can","Người có trình độ học vân cao; có công hiên quan trọng trong sự nghiệp đổi mới và hội nhập quốc tế"],"dung":"B"},{"id":466,"chuong":6,"cauHoi":"Học tập đạo đức cách mạng Hồ Chí Minh, người Việt Nam trong thời đại mới trước hết phải học những gì ?","dapAn":["Học cần, kiệm, liêm, chính, chí công vô tư","Học trung với nước, hiếu với dân, suốt đời đấu tranh cho sự nghiệp cách mạng","Học kính trọng nhân dân","Ý chí nghị lực, quyết tâm vượt qua mọi thử thách"],"dung":"B"},{"id":467,"chuong":6,"cauHoi":"Trong thời kì đổi mới, đi vào nền kinh tế thị trường định hướng xã hội chủ nghĩa, một nền đạo đức mới đang hình thành. Phần lớn sinh viên Việt Nam vẫn giữ được những phẩm chất đạo đức như thế nào?","dapAn":["Yêu nước, thương dân, nhân hậu, nghĩa tình, khoan dung, khiêm tốn","Biết chịu trách nhiệm, sáng tạo trong công việc, năng động trong cuộc sống","Nhân hậu, tình nghĩa, khiêm tốn, luôn cần cù, sáng tạo trong học tập, có chí lập thân, lập nghiệp, dám chịu trách nhiệm, không ỷ lại, bản lĩnh","Trong sạch, lành mạnh, khiêm tồn, sáng tạo, có lý tưởng, bảm lĩnh"],"dung":"C"},{"id":468,"chuong":6,"cauHoi":"Việc học tập tư tưởng, tấm gương đạo đức Hồ Chí Minh đối với sinh viên là tất yếu bởi trong thời kì đối mới một bộ phận sinh viên hiện nay còn có những biếu hiện tiêu cực nào sau đây?","dapAn":["Phai nhạt niềm tin, lý tưởng sống Không có chí lập thân, lập nghiệp","Phai nhạt niềm tin, lý tưởng thiếu trách nhiệm, thờ ơ với gia đình, xã hội...","Tham nhũng, lãng phí, quan liêu D. Sống buông thả, không xác định được mục tiêu lập thân, lập nghiệp","Sống buông thả, không xác định được mục tiêu lập thân, lập nghiệp"],"dung":"B"},{"id":469,"chuong":6,"cauHoi":"Học tập và làm theo đạo đức Hồ Chí Minh là đòi hỏi của sự nghiệp cách mạng, sự nghiệp đổi mới toàn diện đất nước và hội nhập quốc tế, nhằm làm cho: chủ đất nước","dapAn":["Mỗi người trở thành những công dân tốt hơn, xứng đáng là người làm đất nước","Mỗi người trở thành những cán bộ tốt hơn, xứng đáng là người làm chủ","Mỗi người trở thành những thành viên tốt hơn, xứng đáng là người làm chủ đất nước","Mỗi người trở thành những cá nhân tốt hơn, xứng đáng là người làm chủ đất nước"],"dung":"A"},{"id":470,"chuong":6,"cauHoi":"Xác định cụm từ còn thiếu vào câu nói sau của Hồ Chí Minh: \"Một ngày mà Tổ Quốc chưa thống nhất, đồng bào còn chịu khổ, là một ngày tôi 99782 (...)","dapAn":["Ăn không ngon, ngủ không sâu","Ngủ không ngon, ngủ không được","Ăn không ngon, ngủ không yên","Ăn không ngon, ngủ không ngon"],"dung":"C"},{"id":471,"chuong":6,"cauHoi":"Theo Hồ Chí Minh, mọi người dân Việt Nam đều có ý thức dân tộc, trong đó đặc biệt là sinh viên, trách nhiệm của họ là phải:","dapAn":["Vun đắp tinh thần dân tộc, có tinh thần quốc tế trong sáng","Ý thức trách nhiệm với Tổ Quốc thân yêu, biết vun đắp tinh thần dân tộc, tự giác, tích cực thực hiện trách nhiệm của mình","Có ý thức trách nhiệm cao, có lòng tự hào dân tộc, không ngừng đầu tranh chống tiêu cực","Có khắt vọng vươn lên, thắng không kiêu, bại không nản, phấn đấu làm giâu chính đáng"],"dung":"B"},{"id":472,"chuong":6,"cauHoi":"Theo Hồ Chí Minh, phải luôn nhân ái, vị tha, bao dung với con người, tình yêu thương ấy phải gắn với:","dapAn":["Niềm tin tuyệt đối vào sức mạnh và trí tuệ nhân dẫn","Niềm tin vào trí tuệ và lòng nhân ái của con người","Niềm tin vào sức mạnh và lòng trung thực của con người","Niêm tin vào trí tuệ và phẩm giá con người"],"dung":"A"},{"id":473,"chuong":6,"cauHoi":"Để học tập theo tư tưởng, đạo đức, phong cách Hồ Chí Minh, sinh viên Việt cần phải:","dapAn":["Thi đua phần đầu rèn luyện vì ngày mai lập nghiệp","Thi đua học tập, rèn luyện vì ngày mai lập nghiệp","Thi đua phấn đấu học tập vì ngày mai lập nghiệp","Thi đua phấn đấu tích cực rèn luyện vì ngày mai tươi sáng"],"dung":"B"},{"id":474,"chuong":6,"cauHoi":"Theo Hồ Chí Minh \"Muốn xây dựng chủ nghĩa xã hội, trước hết cần phải có những con người xã hội chủ nghĩa\" có nghĩa là:","dapAn":["Xây dựng kinh tế, văn hóa cao mới xây dựng con người","Xây dựng con người xã hội chủ nghĩa xong mới xây dựng chủ nghĩa xã hội","Xây dựng con người phải được đặt ra ngay từ đầu và trong suốt tiến trình xây dựng chủ nghĩa xã hội dựng chủ nghĩa xã hội","Xây dựng chế độ chính trị do nhân dân làm chủ, nhân dân là chủ thể xây"],"dung":"C"},{"id":475,"chuong":6,"cauHoi":"Chủ để nào sau đây là chủ đề học tập và làm theo tư tưởng, đạo đức, phong cách Hồ Chí Minh trong đoàn viên, thanh niên năm 2020?","dapAn":["\"Học tập và làm theo tư tưởng, đạo đức, phong cách Hồ Chí Minh về tinh thần học tập suốt đời\"","\"Thực hành tiết kiệm, chống lãng phí theo tư tưởng, đạo đức, phong cách Hồ Chí Minh\"","\"Học tập và làm theo tư tưởng, đạo đức, phong cách Hồ Chí Minh về trách nhiệm, trung thực, nói đi đôi với làm\"","\"Học tập và làm theo tư tưởng và tấm gương mẫu mực của Hồ Chí Minh về tu dưỡng đạo đức suốt đời\""],"dung":"D"}];